-- Generated typed-view DDL (preview). Apply with scripts/thelibrary_typed_views.py --apply.

CREATE OR REPLACE VIEW THE_LIBRARY.CAMPAIGN_FINANCE.CANDIDATE_FINANCE_SUMMARY COPY GRANTS COMMENT='One row per federal candidate per election cycle: total money raised, total spent, cash on hand, individual contributions, loans, and debts. This is the ONLY FEC bulk file that carries dollar amounts, so it''s the source of every ''candidate raised $X'' number. Keyed by FEC candidate ID (CAND_ID) to link back to the campaigns and committees. Raw landing, values stored as text; 7,933 rows.' AS
SELECT
    "CAND_ID",
    "CAND_NAME",
    "CAND_ICI",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PTY_CD"),'nan'),'NaN'),'NAN'),'')) AS "PTY_CD",
    "CAND_PTY_AFFILIATION",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TTL_RECEIPTS"),'nan'),'NaN'),'NAN'),'')) AS "TTL_RECEIPTS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TRANS_FROM_AUTH"),'nan'),'NaN'),'NAN'),'')) AS "TRANS_FROM_AUTH",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TTL_DISB"),'nan'),'NaN'),'NAN'),'')) AS "TTL_DISB",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TRANS_TO_AUTH"),'nan'),'NaN'),'NAN'),'')) AS "TRANS_TO_AUTH",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COH_BOP"),'nan'),'NaN'),'NAN'),'')) AS "COH_BOP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COH_COP"),'nan'),'NaN'),'NAN'),'')) AS "COH_COP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CAND_CONTRIB"),'nan'),'NaN'),'NAN'),'')) AS "CAND_CONTRIB",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CAND_LOANS"),'nan'),'NaN'),'NAN'),'')) AS "CAND_LOANS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OTHER_LOANS"),'nan'),'NaN'),'NAN'),'')) AS "OTHER_LOANS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CAND_LOAN_REPAY"),'nan'),'NaN'),'NAN'),'')) AS "CAND_LOAN_REPAY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OTHER_LOAN_REPAY"),'nan'),'NaN'),'NAN'),'')) AS "OTHER_LOAN_REPAY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEBTS_OWED_BY"),'nan'),'NaN'),'NAN'),'')) AS "DEBTS_OWED_BY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TTL_INDIV_CONTRIB"),'nan'),'NaN'),'NAN'),'')) AS "TTL_INDIV_CONTRIB",
    "CAND_OFFICE_ST",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CAND_OFFICE_DISTRICT"),'nan'),'NaN'),'NAN'),'')) AS "CAND_OFFICE_DISTRICT",
    "SPEC_ELECTION",
    "PRIM_ELECTION",
    "RUN_ELECTION",
    "GEN_ELECTION",
    "GEN_ELECTION_PRECENT",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OTHER_POL_CMTE_CONTRIB"),'nan'),'NaN'),'NAN'),'')) AS "OTHER_POL_CMTE_CONTRIB",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("POL_PTY_CONTRIB"),'nan'),'NaN'),'NAN'),'')) AS "POL_PTY_CONTRIB",
    CASE WHEN TRIM("CVG_END_DT") LIKE '%-%' OR TRIM("CVG_END_DT") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CVG_END_DT")) END AS "CVG_END_DT",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("INDIV_REFUNDS"),'nan'),'NaN'),'NAN'),'')) AS "INDIV_REFUNDS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CMTE_REFUNDS"),'nan'),'NaN'),'NAN'),'')) AS "CMTE_REFUNDS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CYCLE"),'nan'),'NaN'),'NAN'),'')) AS "CYCLE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_FEC_BULK_SUMMARY;

CREATE OR REPLACE VIEW THE_LIBRARY.CAMPAIGN_FINANCE.FEC_CANDIDATES_FED_FEC_BULK_CANDIDATES COPY GRANTS COMMENT='The FEC candidate master: one row per registered federal candidate per cycle (17,900 rows) -- FEC candidate ID, name, office sought, party, state, district, and incumbent/challenger/open-seat status. The anchor that ties a candidate ID to a name and office across the whole money-in-politics stack. Links to committees and donations via CAND_ID. Raw text landing (FEC bulk cn.txt).' AS
SELECT
    "CAND_ID",
    "CAND_NAME",
    "CAND_PTY_AFFILIATION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CAND_ELECTION_YR"),'nan'),'NaN'),'NAN'),'')) AS "CAND_ELECTION_YR",
    "CAND_OFFICE_ST",
    "CAND_OFFICE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CAND_OFFICE_DISTRICT"),'nan'),'NaN'),'NAN'),'')) AS "CAND_OFFICE_DISTRICT",
    "CAND_ICI",
    "CAND_STATUS",
    "CAND_PCC",
    "CAND_ST1",
    "CAND_ST2",
    "CAND_CITY",
    "CAND_ST",
    "CAND_ZIP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CYCLE"),'nan'),'NaN'),'NAN'),'')) AS "CYCLE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_FEC_BULK_CANDIDATES;

CREATE OR REPLACE VIEW THE_LIBRARY.CAMPAIGN_FINANCE.FEC_CANDIDATE_COMMITTEE_LINKS COPY GRANTS COMMENT='The FEC candidate-to-committee linkage table (ccl.txt): 16,327 rows connecting each candidate ID to the committee IDs authorized by or linked to them, with committee type and designation. This is the clean join that lets you roll individual donations up from a committee to the actual candidate who benefits. Raw landing, all text.' AS
SELECT
    "CAND_ID",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CAND_ELECTION_YR"),'nan'),'NaN'),'NAN'),'')) AS "CAND_ELECTION_YR",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FEC_ELECTION_YR"),'nan'),'NaN'),'NAN'),'')) AS "FEC_ELECTION_YR",
    "CMTE_ID",
    "CMTE_TP",
    "CMTE_DSGN",
    "LINKAGE_ID",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CYCLE"),'nan'),'NaN'),'NAN'),'')) AS "CYCLE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_FEC_BULK_LINKAGES;

CREATE OR REPLACE VIEW THE_LIBRARY.CAMPAIGN_FINANCE.FEC_COMMITTEES_2026 COPY GRANTS COMMENT='Every committee registered with the FEC for the 2026 cycle: committee ID, name, treasurer, address, type, party, and the candidate it''s linked to. This is the committee dimension that candidate-to-money links resolve against. Landed alongside the 2024 committee master to close a 2026 gap (2026 linkages resolved only ~57% before this vs. ~98% for 2024). Keyed by FEC committee ID and candidate ID. Raw landing, stored as text; 20,007 rows.' AS
SELECT
    "FEC_CMTE_ID",
    "CMTE_NM",
    "TRES_NM",
    "CMTE_ST1",
    "CMTE_ST2",
    "CMTE_CITY",
    "CMTE_ST",
    "CMTE_ZIP",
    "CMTE_DSGN",
    "CMTE_TP",
    "CMTE_PTY_AFFILIATION",
    "CMTE_FILING_FREQ",
    "ORG_TP",
    "CONNECTED_ORG_NM",
    "FEC_CAND_ID",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CYCLE"),'nan'),'NaN'),'NAN'),'')) AS "CYCLE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_FEC_BULK_COMMITTEES;

CREATE OR REPLACE VIEW THE_LIBRARY.CAMPAIGN_FINANCE.INDIVIDUAL_DONATIONS COPY GRANTS COMMENT='Every itemized individual contribution (over $200 aggregate) to a federal committee -- donor name, city/state/ZIP, free-text employer and occupation, amount, date, recipient committee, and the conduit for earmarked gifts. 84.2M rows across the 2024 and 2026 cycles. Gotcha: there''s no cycle column (two files were merged), so derive the cycle from TRANSACTION_DT (MMDDYYYY). Raw landing, all text -- cast the amount before summing.' AS
SELECT
    "CMTE_ID",
    "AMNDT_IND",
    "RPT_TP",
    "TRANSACTION_PGI",
    "IMAGE_NUM",
    "TRANSACTION_TP",
    "ENTITY_TP",
    "NAME",
    "CITY",
    "STATE",
    "ZIP_CODE",
    "EMPLOYER",
    "OCCUPATION",
    TRY_TO_DATE(TRIM("TRANSACTION_DT"),'MMDDYYYY') AS "TRANSACTION_DT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TRANSACTION_AMT"),'nan'),'NaN'),'NAN'),'')) AS "TRANSACTION_AMT",
    "OTHER_ID",
    "TRAN_ID",
    "FILE_NUM",
    "MEMO_CD",
    "MEMO_TEXT",
    "SUB_ID",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_FEC_INDIV_CONTRIBUTIONS;

CREATE OR REPLACE VIEW THE_LIBRARY.CAMPAIGN_FINANCE.OUTSIDE_SPENDING COPY GRANTS COMMENT='FEC Schedule E independent expenditures: 83,468 records of outside groups (super PACs and others) spending to support or oppose a candidate, with a flag for which direction. This is the authoritative source for outside for/against spending, keyed by FEC committee and candidate IDs so it joins to the campaign-finance spine. Raw landing table, values stored as text.' AS
SELECT
    "CAND_ID",
    "CAND_NAME",
    "SPE_ID",
    "SPE_NAM",
    "ELE_TYPE",
    "CAN_OFFICE_STATE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CAN_OFFICE_DIS"),'nan'),'NaN'),'NAN'),'')) AS "CAN_OFFICE_DIS",
    "CAN_OFFICE",
    "CAND_PTY_AFF",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXP_AMO"),'nan'),'NaN'),'NAN'),'')) AS "EXP_AMO",
    CASE WHEN TRIM("EXP_DATE") LIKE '%-%' OR TRIM("EXP_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("EXP_DATE")) END AS "EXP_DATE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("AGG_AMO"),'nan'),'NaN'),'NAN'),'')) AS "AGG_AMO",
    "SUP_OPP",
    "PUR",
    "PAY",
    "FILE_NUM",
    "AMNDT_IND",
    "TRAN_ID",
    "IMAGE_NUM",
    "RECEIPT_DAT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FEC_ELECTION_YR"),'nan'),'NaN'),'NAN'),'')) AS "FEC_ELECTION_YR",
    "PREV_FILE_NUM",
    CASE WHEN TRIM("DISSEM_DT") LIKE '%-%' OR TRIM("DISSEM_DT") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DISSEM_DT")) END AS "DISSEM_DT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CYCLE_FILE"),'nan'),'NaN'),'NAN'),'')) AS "CYCLE_FILE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_FEC_INDEPENDENT_EXPENDITURES;

CREATE OR REPLACE VIEW THE_LIBRARY.CAMPAIGN_FINANCE.PAC_CONTRIBUTIONS_TO_CANDIDATES COPY GRANTS COMMENT='Committee-to-candidate transactions: PAC and party contributions, plus independent expenditures for or against a candidate, one row each (866,730 rows) with amount, date and transaction type. The organized-money leg of follow-the-money in politics. Carries both CMTE_ID (the committee) and CAND_ID (the candidate) so it links committees to candidates by cycle. Raw text landing (FEC bulk pas2).' AS
SELECT
    "CMTE_ID",
    "AMNDT_IND",
    "RPT_TP",
    "TRANSACTION_PGI",
    "IMAGE_NUM",
    "TRANSACTION_TP",
    "ENTITY_TP",
    "NAME",
    "CITY",
    "STATE",
    "ZIP_CODE",
    "EMPLOYER",
    "OCCUPATION",
    TRY_TO_DATE(TRIM("TRANSACTION_DT"),'MMDDYYYY') AS "TRANSACTION_DT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TRANSACTION_AMT"),'nan'),'NaN'),'NAN'),'')) AS "TRANSACTION_AMT",
    "OTHER_ID",
    "CAND_ID",
    "TRAN_ID",
    "FILE_NUM",
    "MEMO_CD",
    "MEMO_TEXT",
    "SUB_ID",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CYCLE"),'nan'),'NaN'),'NAN'),'')) AS "CYCLE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_FEC_COMMITTEE_TO_CANDIDATE;

CREATE OR REPLACE VIEW THE_LIBRARY.COMPANIES.IRELAND_COMPANIES COPY GRANTS COMMENT='Ireland''s official company register (CRO): company ID, name, status, incorporation date, type, and registered address. Meant to be the corporate-entity layer for Ireland, joinable by country + name. Heads up: only 3 rows landed here -- this is a placeholder sample, not the real registry, so use it to understand the columns, not to look up companies. Raw landing, stored as text.' AS
SELECT
    "COMPANY_NUM",
    "COMPANY_NAME",
    "COMPANY_STATUS_CODE",
    "COMPANY_STATUS",
    "COMPANY_TYPE_CODE",
    "COMPANY_TYPE",
    CASE WHEN TRIM("COMPANY_REG_DATE") LIKE '%-%' OR TRIM("COMPANY_REG_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("COMPANY_REG_DATE")) END AS "COMPANY_REG_DATE",
    CASE WHEN TRIM("LAST_AR_DATE") LIKE '%-%' OR TRIM("LAST_AR_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("LAST_AR_DATE")) END AS "LAST_AR_DATE",
    "COMPANY_ADDRESS_1",
    "COMPANY_ADDRESS_2",
    "COMPANY_ADDRESS_3",
    "COMPANY_ADDRESS_4",
    CASE WHEN TRIM("COMP_DISSOLVED_DATE") LIKE '%-%' OR TRIM("COMP_DISSOLVED_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("COMP_DISSOLVED_DATE")) END AS "COMP_DISSOLVED_DATE",
    "NARD",
    CASE WHEN TRIM("LAST_ACCOUNTS_DATE") LIKE '%-%' OR TRIM("LAST_ACCOUNTS_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("LAST_ACCOUNTS_DATE")) END AS "LAST_ACCOUNTS_DATE",
    CASE WHEN TRIM("COMPANY_STATUS_DATE") LIKE '%-%' OR TRIM("COMPANY_STATUS_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("COMPANY_STATUS_DATE")) END AS "COMPANY_STATUS_DATE",
    "NACE_V2_CODE",
    "EIRCODE",
    CASE WHEN TRIM("COMPANY_NAME_EFF_DATE") LIKE '%-%' OR TRIM("COMPANY_NAME_EFF_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("COMPANY_NAME_EFF_DATE")) END AS "COMPANY_NAME_EFF_DATE",
    CASE WHEN TRIM("COMPANY_TYPE_EFF_DATE") LIKE '%-%' OR TRIM("COMPANY_TYPE_EFF_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("COMPANY_TYPE_EFF_DATE")) END AS "COMPANY_TYPE_EFF_DATE",
    "PRINC_OBJECT_CODE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_IE_CRO;

CREATE OR REPLACE VIEW THE_LIBRARY.COMPANIES.LARGEST_US_COMPANIES COPY GRANTS COMMENT='The top 100 US companies ranked by revenue, with industry, revenue growth, employee count, and headquarters. A quick who''s-who of American corporate giants, useful as a starting reference to join out to contracts, filings, and lobbying by company name. Heads up: only 100 rows, scraped from Wikipedia, and the only join key is company NAME (fuzzy). Raw landing table, values stored as text.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RANK"),'nan'),'NaN'),'NAN'),'')) AS "RANK",
    "NAME",
    "INDUSTRY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REVENUE_USD_MILLIONS"),'nan'),'NaN'),'NAN'),'')) AS "REVENUE_USD_MILLIONS",
    "REVENUE_GROWTH",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EMPLOYEES"),'nan'),'NaN'),'NAN'),'')) AS "EMPLOYEES",
    "HEADQUARTERS",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_WIKIPEDIA_LARGEST_US_COMPANIES;

CREATE OR REPLACE VIEW THE_LIBRARY.COMPANIES.NONPROFIT_990_FILINGS COPY GRANTS COMMENT='Return-level index of electronically filed IRS Form 990s: EIN, organization, tax period, gross receipts, total revenue/expenses/assets. A 200-row probe of the bulk XML universe. EIN joins it straight to the 3.9M-row tax-exempt master file on this shelf -- the index says who filed, the BMF says who exists.' AS
SELECT
    "EIN",
    "ORGANIZATIONNAME",
    "TAXPERIODBEGINDT",
    "TAXPERIODENDDT",
    "FORMTYPE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RETURNTS"),'nan'),'NaN'),'NAN'),'')) AS "RETURNTS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TAXYR"),'nan'),'NaN'),'NAN'),'')) AS "TAXYR",
    "GROSSRECEIPTSAMT",
    "TOTALASSETSEOYAMT",
    "TOTALLIABILITIESEOYAMT",
    "TOTALREVENUEAMT",
    "TOTALEXPENSESAMT",
    "OFFICERCOMPENSATIONAMT",
    "USADDRESS_ZIPCD",
    "USADDRESS_STATEABBREVIATIONCD",
    "EXEMPTIONCD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OBJECTID"),'nan'),'NaN'),'NAN'),'')) AS "OBJECTID",
    "RETURNID",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_IRS_990;

CREATE OR REPLACE VIEW THE_LIBRARY.COMPANIES.NONPROFIT_ORGANIZATIONS COPY GRANTS COMMENT='The IRS Business Master File: the full roster of US tax-exempt orgs (1,974,830 rows) -- EIN, name, address, NTEE category code, subsection/foundation status, and assets/income/revenue. The IRS side of the EIN bridge, so it links nonprofits to donations, contracts and the banned lists by EIN. Concatenated from the 4 regional extracts. Raw text landing (IRS) -- every value stored as text.' AS
SELECT
    "EIN",
    "NAME",
    "ICO",
    "STREET",
    "CITY",
    "STATE",
    "ZIP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_GROUP"),'nan'),'NaN'),'NAN'),'')) AS "C_GROUP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SUBSECTION"),'nan'),'NaN'),'NAN'),'')) AS "SUBSECTION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("AFFILIATION"),'nan'),'NaN'),'NAN'),'')) AS "AFFILIATION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CLASSIFICATION"),'nan'),'NaN'),'NAN'),'')) AS "CLASSIFICATION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RULING"),'nan'),'NaN'),'NAN'),'')) AS "RULING",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEDUCTIBILITY"),'nan'),'NaN'),'NAN'),'')) AS "DEDUCTIBILITY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FOUNDATION"),'nan'),'NaN'),'NAN'),'')) AS "FOUNDATION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTIVITY"),'nan'),'NaN'),'NAN'),'')) AS "ACTIVITY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_ORGANIZATION"),'nan'),'NaN'),'NAN'),'')) AS "C_ORGANIZATION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("STATUS"),'nan'),'NaN'),'NAN'),'')) AS "STATUS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TAX_PERIOD"),'nan'),'NaN'),'NAN'),'')) AS "TAX_PERIOD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ASSET_CD"),'nan'),'NaN'),'NAN'),'')) AS "ASSET_CD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("INCOME_CD"),'nan'),'NaN'),'NAN'),'')) AS "INCOME_CD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FILING_REQ_CD"),'nan'),'NaN'),'NAN'),'')) AS "FILING_REQ_CD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PF_FILING_REQ_CD"),'nan'),'NaN'),'NAN'),'')) AS "PF_FILING_REQ_CD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACCT_PD"),'nan'),'NaN'),'NAN'),'')) AS "ACCT_PD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ASSET_AMT"),'nan'),'NaN'),'NAN'),'')) AS "ASSET_AMT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("INCOME_AMT"),'nan'),'NaN'),'NAN'),'')) AS "INCOME_AMT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REVENUE_AMT"),'nan'),'NaN'),'NAN'),'')) AS "REVENUE_AMT",
    "NTEE_CD",
    "SORT_NAME",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_IRS_BMF;

CREATE OR REPLACE VIEW THE_LIBRARY.COMPANIES.REVOKED_NONPROFITS COPY GRANTS COMMENT='The IRS auto-revocation list: 1.2M nonprofits stripped of tax-exempt status (usually for failing to file for three straight years), with the revocation date and any later reinstatement. Keyed by EIN, so you can check whether an org still soliciting donations or receiving grants is actually a revoked shell. Raw landing -- every value is text.' AS
SELECT
    "EIN",
    "LEGAL_NAME",
    "DBA_NAME",
    "ORG_ADDRESS",
    "CITY",
    "STATE",
    "ZIP_CODE",
    "COUNTRY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXEMPTION_TYPE"),'nan'),'NaN'),'NAN'),'')) AS "EXEMPTION_TYPE",
    CASE WHEN TRIM("REVOCATION_DATE") LIKE '%-%' OR TRIM("REVOCATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("REVOCATION_DATE")) END AS "REVOCATION_DATE",
    CASE WHEN TRIM("REVOCATION_POSTING_DATE") LIKE '%-%' OR TRIM("REVOCATION_POSTING_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("REVOCATION_POSTING_DATE")) END AS "REVOCATION_POSTING_DATE",
    "EXEMPTION_REINSTATEMENT_DATE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_IRS_REVOCATION;

CREATE OR REPLACE VIEW THE_LIBRARY.COMPANIES.SEC_EDGAR_FILINGS_API COPY GRANTS COMMENT='Filing-level metadata from the SEC''s structured JSON API: who filed (CIK, EIN, entity name), which form, when, and links to documents. A 200-row probe -- the bigger sibling SEC_EDGAR_FILINGS on this shelf carries 49K rows from the full-text side. Both carry CIK, the steel join key of corporate America.' AS
SELECT
    "CIK",
    "ENTITYNAME",
    "EIN",
    "ACCESSIONNUMBER",
    "FILEDAT",
    CASE WHEN TRIM("REPORTDATE") LIKE '%-%' OR TRIM("REPORTDATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("REPORTDATE")) END AS "REPORTDATE",
    "FORM",
    "PRIMARYDOCUMENT",
    "PRIMARYDOCDESCRIPTION",
    "ITEMS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ISINLINEXBRL"),'nan'),'NaN'),'NAN'),'')) AS "ISINLINEXBRL",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ISXBRL"),'nan'),'NaN'),'NAN'),'')) AS "ISXBRL",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SIC"),'nan'),'NaN'),'NAN'),'')) AS "SIC",
    "SICDESCRIPTION",
    "STATEOFINCORPORATION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FISCALYEAREND"),'nan'),'NaN'),'NAN'),'')) AS "FISCALYEAREND",
    "TICKERS",
    "EXCHANGES",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_SEC_EDGAR;

CREATE OR REPLACE VIEW THE_LIBRARY.COMPANIES.TAX_EXEMPT_ORGANIZATIONS COPY GRANTS COMMENT='The complete IRS Business Master File of tax-exempt organizations: every nonprofit, foundation, church group, and association the IRS recognizes -- 3.9 million of them, with EIN, address, exemption subsection, and ruling date. This is the spine table for anything nonprofit: start here, then hang 990 financials, revocations, and grants off the EIN.' AS
SELECT
    "EIN",
    "NAME",
    "ICO",
    "STREET",
    "CITY",
    "STATE",
    "ZIP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_GROUP"),'nan'),'NaN'),'NAN'),'')) AS "C_GROUP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SUBSECTION"),'nan'),'NaN'),'NAN'),'')) AS "SUBSECTION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("AFFILIATION"),'nan'),'NaN'),'NAN'),'')) AS "AFFILIATION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CLASSIFICATION"),'nan'),'NaN'),'NAN'),'')) AS "CLASSIFICATION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RULING"),'nan'),'NaN'),'NAN'),'')) AS "RULING",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEDUCTIBILITY"),'nan'),'NaN'),'NAN'),'')) AS "DEDUCTIBILITY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FOUNDATION"),'nan'),'NaN'),'NAN'),'')) AS "FOUNDATION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTIVITY"),'nan'),'NaN'),'NAN'),'')) AS "ACTIVITY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_ORGANIZATION"),'nan'),'NaN'),'NAN'),'')) AS "C_ORGANIZATION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("STATUS"),'nan'),'NaN'),'NAN'),'')) AS "STATUS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TAX_PERIOD"),'nan'),'NaN'),'NAN'),'')) AS "TAX_PERIOD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ASSET_CD"),'nan'),'NaN'),'NAN'),'')) AS "ASSET_CD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("INCOME_CD"),'nan'),'NaN'),'NAN'),'')) AS "INCOME_CD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FILING_REQ_CD"),'nan'),'NaN'),'NAN'),'')) AS "FILING_REQ_CD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PF_FILING_REQ_CD"),'nan'),'NaN'),'NAN'),'')) AS "PF_FILING_REQ_CD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACCT_PD"),'nan'),'NaN'),'NAN'),'')) AS "ACCT_PD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ASSET_AMT"),'nan'),'NaN'),'NAN'),'')) AS "ASSET_AMT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("INCOME_AMT"),'nan'),'NaN'),'NAN'),'')) AS "INCOME_AMT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REVENUE_AMT"),'nan'),'NaN'),'NAN'),'')) AS "REVENUE_AMT",
    "NTEE_CD",
    "SORT_NAME",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_IRS_EO_BMF;

CREATE OR REPLACE VIEW THE_LIBRARY.CRIME_SECURITY.ARMED_CONFLICT_EVENTS COPY GRANTS COMMENT='The gold-standard conflict backbone: individual events of organized violence (war, insurgency, one-sided killings) with a date, lat/lon, the two sides, and best/low/high fatality estimates because exact death counts are uncertain. Map it, count it, or track a war over time. Raw as loaded (all text); has lat/lon for spatial joins, no country ID key. UCDP GED Global v251.' AS
SELECT
    "ID",
    "RELID",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    "ACTIVE_YEAR",
    "CODE_STATUS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TYPE_OF_VIOLENCE"),'nan'),'NaN'),'NAN'),'')) AS "TYPE_OF_VIOLENCE",
    "CONFLICT_DSET_ID",
    "CONFLICT_NEW_ID",
    "CONFLICT_NAME",
    "DYAD_DSET_ID",
    "DYAD_NEW_ID",
    "DYAD_NAME",
    "SIDE_A_DSET_ID",
    "SIDE_A_NEW_ID",
    "SIDE_A",
    "SIDE_B_DSET_ID",
    "SIDE_B_NEW_ID",
    "SIDE_B",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NUMBER_OF_SOURCES"),'nan'),'NaN'),'NAN'),'')) AS "NUMBER_OF_SOURCES",
    "SOURCE_ARTICLE",
    "SOURCE_OFFICE",
    "SOURCE_DATE",
    "SOURCE_HEADLINE",
    "SOURCE_ORIGINAL",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WHERE_PREC"),'nan'),'NaN'),'NAN'),'')) AS "WHERE_PREC",
    "WHERE_COORDINATES",
    "WHERE_DESCRIPTION",
    "ADM_1",
    "ADM_2",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LATITUDE"),'nan'),'NaN'),'NAN'),'')) AS "LATITUDE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LONGITUDE"),'nan'),'NaN'),'NAN'),'')) AS "LONGITUDE",
    "GEOM_WKT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PRIOGRID_GID"),'nan'),'NaN'),'NAN'),'')) AS "PRIOGRID_GID",
    "COUNTRY",
    "COUNTRY_ID",
    "REGION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EVENT_CLARITY"),'nan'),'NaN'),'NAN'),'')) AS "EVENT_CLARITY",
    "DATE_PREC",
    CASE WHEN TRIM("DATE_START") LIKE '%-%' OR TRIM("DATE_START") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE_START")) END AS "DATE_START",
    CASE WHEN TRIM("DATE_END") LIKE '%-%' OR TRIM("DATE_END") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE_END")) END AS "DATE_END",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEATHS_A"),'nan'),'NaN'),'NAN'),'')) AS "DEATHS_A",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEATHS_B"),'nan'),'NaN'),'NAN'),'')) AS "DEATHS_B",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEATHS_CIVILIANS"),'nan'),'NaN'),'NAN'),'')) AS "DEATHS_CIVILIANS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEATHS_UNKNOWN"),'nan'),'NaN'),'NAN'),'')) AS "DEATHS_UNKNOWN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BEST"),'nan'),'NaN'),'NAN'),'')) AS "BEST",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HIGH"),'nan'),'NaN'),'NAN'),'')) AS "HIGH",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LOW"),'nan'),'NaN'),'NAN'),'')) AS "LOW",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GWNOA"),'nan'),'NaN'),'NAN'),'')) AS "GWNOA",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GWNOB"),'nan'),'NaN'),'NAN'),'')) AS "GWNOB",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_UCDP_GED;

