    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EDUCATN1"),'nan'),'NaN'),'NAN'),'')) AS "EDUCATN1",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EDUCATN2"),'nan'),'NaN'),'NAN'),'')) AS "EDUCATN2",
