    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("VICSERVICES"),'nan'),'NaN'),'NAN'),'')) AS "VICSERVICES",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LOCATIONR"),'nan'),'NaN'),'NAN'),'')) AS "LOCATIONR",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DIREL"),'nan'),'NaN'),'NAN'),'')) AS "DIREL",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WEAPON"),'nan'),'NaN'),'NAN'),'')) AS "WEAPON",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WEAPCAT"),'nan'),'NaN'),'NAN'),'')) AS "WEAPCAT",
