    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SERIOUS"),'nan'),'NaN'),'NAN'),'')) AS "SERIOUS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TREATMENT"),'nan'),'NaN'),'NAN'),'')) AS "TREATMENT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OFFENDERAGE"),'nan'),'NaN'),'NAN'),'')) AS "OFFENDERAGE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OFFENDERSEX"),'nan'),'NaN'),'NAN'),'')) AS "OFFENDERSEX",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OFFTRACENEW"),'nan'),'NaN'),'NAN'),'')) AS "OFFTRACENEW",
