CREATE OR REPLACE VIEW THE_LIBRARY.CRIME_SECURITY.EUROPOL_THREAT_REPORTS COPY GRANTS COMMENT='An index of Europol''s flagship strategic reports on serious organized crime (SOCTA) and cybercrime (IOCTA): title, year, language, and download link. It''s a small document index (26 reports), there for provenance when an investigation cites European threat assessments.' AS
SELECT
    "REPORT_TITLE",
    "REPORT_TYPE",
    CASE WHEN TRIM("PUBLISH_DATE") LIKE '%-%' OR TRIM("PUBLISH_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("PUBLISH_DATE")) END AS "PUBLISH_DATE",
    CASE WHEN TRIM("UPDATE_DATE") LIKE '%-%' OR TRIM("UPDATE_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("UPDATE_DATE")) END AS "UPDATE_DATE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REPORT_YEAR"),'nan'),'NaN'),'NAN'),'')) AS "REPORT_YEAR",
    "LANGUAGE",
    "FILE_FORMAT",
    "FILE_SIZE_MB",
    "DOWNLOAD_URL",
    "DOCUMENT_VARIANT",
    "ISBN",
    "DOI",
    "SERIAL_NUMBER",
    "PUBLISHER",
    "GEOGRAPHIC_SCOPE",
    "SOURCE_URL",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_EU_SOCTA_EUROPOL;

CREATE OR REPLACE VIEW THE_LIBRARY.CRIME_SECURITY.EXPLOITED_VULNERABILITIES COPY GRANTS COMMENT='CISA''s authoritative catalog of software vulnerabilities (CVEs) with real evidence of active in-the-wild attacks -- which vendor and product, what it does, whether it''s been used in ransomware, and the federal deadline to patch it. The short list of flaws that actually matter right now. Raw as loaded (all text); keyed by CVE_ID. From CISA.' AS
SELECT
    "CVE_ID",
    "VENDOR_PROJECT",
    "PRODUCT",
    "VULNERABILITY_NAME",
    CASE WHEN TRIM("DATE_ADDED") LIKE '%-%' OR TRIM("DATE_ADDED") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE_ADDED")) END AS "DATE_ADDED",
    "SHORT_DESCRIPTION",
    "REQUIRED_ACTION",
    CASE WHEN TRIM("DUE_DATE") LIKE '%-%' OR TRIM("DUE_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DUE_DATE")) END AS "DUE_DATE",
    "KNOWN_RANSOMWARE_CAMPAIGN_USE",
    "NOTES",
    "CWES",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CISA_KEV;

CREATE OR REPLACE VIEW THE_LIBRARY.CRIME_SECURITY.GUN_BACKGROUND_CHECKS COPY GRANTS COMMENT='State-by-month counts of FBI firearm background checks, broken out by 24 check types (handgun, long gun, permit, pawn, private sale, etc.). The cleanest available signal for gun demand -- but a check is NOT a sale: permit rechecks and CCW renewals inflate the totals, so treat it as a proxy. Raw as loaded (all text); join on state name (map to FIPS in staging). FBI via the Data Liberation Project mirror.' AS
SELECT
    "MONTH",
    "STATE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PERMIT"),'nan'),'NaN'),'NAN'),'')) AS "PERMIT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PERMIT_RECHECK"),'nan'),'NaN'),'NAN'),'')) AS "PERMIT_RECHECK",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HANDGUN"),'nan'),'NaN'),'NAN'),'')) AS "HANDGUN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LONG_GUN"),'nan'),'NaN'),'NAN'),'')) AS "LONG_GUN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OTHER"),'nan'),'NaN'),'NAN'),'')) AS "OTHER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MULTIPLE"),'nan'),'NaN'),'NAN'),'')) AS "MULTIPLE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ADMIN"),'nan'),'NaN'),'NAN'),'')) AS "ADMIN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PREPAWN_HANDGUN"),'nan'),'NaN'),'NAN'),'')) AS "PREPAWN_HANDGUN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PREPAWN_LONG_GUN"),'nan'),'NaN'),'NAN'),'')) AS "PREPAWN_LONG_GUN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PREPAWN_OTHER"),'nan'),'NaN'),'NAN'),'')) AS "PREPAWN_OTHER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REDEMPTION_HANDGUN"),'nan'),'NaN'),'NAN'),'')) AS "REDEMPTION_HANDGUN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REDEMPTION_LONG_GUN"),'nan'),'NaN'),'NAN'),'')) AS "REDEMPTION_LONG_GUN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REDEMPTION_OTHER"),'nan'),'NaN'),'NAN'),'')) AS "REDEMPTION_OTHER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RETURNED_HANDGUN"),'nan'),'NaN'),'NAN'),'')) AS "RETURNED_HANDGUN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RETURNED_LONG_GUN"),'nan'),'NaN'),'NAN'),'')) AS "RETURNED_LONG_GUN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RETURNED_OTHER"),'nan'),'NaN'),'NAN'),'')) AS "RETURNED_OTHER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RENTALS_HANDGUN"),'nan'),'NaN'),'NAN'),'')) AS "RENTALS_HANDGUN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RENTALS_LONG_GUN"),'nan'),'NaN'),'NAN'),'')) AS "RENTALS_LONG_GUN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PRIVATE_SALE_HANDGUN"),'nan'),'NaN'),'NAN'),'')) AS "PRIVATE_SALE_HANDGUN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PRIVATE_SALE_LONG_GUN"),'nan'),'NaN'),'NAN'),'')) AS "PRIVATE_SALE_LONG_GUN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PRIVATE_SALE_OTHER"),'nan'),'NaN'),'NAN'),'')) AS "PRIVATE_SALE_OTHER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RETURN_TO_SELLER_HANDGUN"),'nan'),'NaN'),'NAN'),'')) AS "RETURN_TO_SELLER_HANDGUN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RETURN_TO_SELLER_LONG_GUN"),'nan'),'NaN'),'NAN'),'')) AS "RETURN_TO_SELLER_LONG_GUN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RETURN_TO_SELLER_OTHER"),'nan'),'NaN'),'NAN'),'')) AS "RETURN_TO_SELLER_OTHER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTALS"),'nan'),'NaN'),'NAN'),'')) AS "TOTALS",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_FBI_NICS_CHECKS;

CREATE OR REPLACE VIEW THE_LIBRARY.CRIME_SECURITY.HOMICIDE_RATE_BY_COUNTRY COPY GRANTS COMMENT='The homicide rate (killings per 100,000 people) for every country over time, sourced from UNODC via Our World in Data. The standard way to compare violence across countries and track it over time. Carries ISO-3 country codes, so it joins to any country-keyed source in the Library. Raw as loaded (every value stored as text) -- includes regional/aggregate ''entity'' rows alongside individual countries.' AS
SELECT
    "ENTITY",
    "CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HOMICIDE_RATE_PER_100_000_POPULATION"),'nan'),'NaN'),'NAN'),'')) AS "HOMICIDE_RATE_PER_100_000_POPULATION",
    "WORLD_REGION_ACCORDING_TO_OWID",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_OWID_HOMICIDE;

CREATE OR REPLACE VIEW THE_LIBRARY.CRIME_SECURITY.NORTH_KOREA_MISSILE_TESTS COPY GRANTS COMMENT='The authoritative chronology of every North Korean missile flight test from 1984 to today: missile name and type (SRBM/ICBM/etc), date and time, geocoded launch facility (lat/lon), apogee, distance, and whether it succeeded. Built for tracking the pace and reach of the DPRK missile program. Heads up: many ''numeric'' fields (apogee, distance, landing location) are free text including ''Unknown'' -- kept as text here, parse in staging. Raw as loaded (every value stored as text).' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("F1"),'nan'),'NaN'),'NAN'),'')) AS "F1",
    CASE WHEN TRIM("DATE") LIKE '%-%' OR TRIM("DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE")) END AS "DATE",
    CASE WHEN TRIM("DATE_ENTERED_UPDATED") LIKE '%-%' OR TRIM("DATE_ENTERED_UPDATED") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE_ENTERED_UPDATED")) END AS "DATE_ENTERED_UPDATED",
    "LAUNCH_TIME_UTC",
    "MISSILE_NAME",
    "MISSILE_TYPE",
    "LAUNCH_AGENCY_AUTHORITY",
    "FACILITY_NAME",
    "FACILITY_LOCATION",
    "OTHER_NAME",
    "FACILITY_LATITUDE",
    "FACILITY_LONGITUDE",
    "LANDING_LOCATION",
    "APOGEE",
    "DISTANCE_TRAVELLED",
    "CONFIRMATION_STATUS",
    "TEST_OUTCOME",
    "ADDITIONAL_INFORMATION",
    "SOURCE_S",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_NTI_CNS_DPRK_MISSILE_TESTS;

CREATE OR REPLACE VIEW THE_LIBRARY.CRIME_SECURITY.NORTH_KOREA_MISSILE_TESTS_XC_NAGIX_DPRK_MISSILE_TESTS COPY GRANTS COMMENT='A record of North Korean missile flight tests: date, missile type, launch facility, apogee, distance flown, bearing, and whether it succeeded. Good for mapping impact points and tracking escalation. This is a derived/enriched mirror (from CNS/NTI data), not the primary source -- treat missile and facility values as codes needing a lookup. Raw as loaded (all text); no join key.' AS
SELECT
    CASE WHEN TRIM("DATE") LIKE '%-%' OR TRIM("DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE")) END AS "DATE",
    "TIME",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SERIES"),'nan'),'NaN'),'NAN'),'')) AS "SERIES",
    "MISSILE",
    "FACILITY",
    "LANDING",
    "APOGEE",
    "DISTANCE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BEARING"),'nan'),'NaN'),'NAN'),'')) AS "BEARING",
    "OUTCOME",
    "DESCRIPTION",
    "GLIDE",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_NAGIX_DPRK_MISSILE_TESTS;

CREATE OR REPLACE VIEW THE_LIBRARY.CRIME_SECURITY.NUCLEAR_WARHEAD_STOCKPILES COPY GRANTS COMMENT='Estimated nuclear warhead counts for the nine weapons states (US, Russia, China, France, UK, India, Pakistan, Israel, North Korea) plus South Africa and a World total, tracked over time. Great scene-setting for the global arsenal race, keyed by country ISO-3 code. Heads up: this is weapons-states only -- Iran is NOT in it, so it''s context, not Iran data. Raw landing table, values stored as text.' AS
SELECT
    "ENTITY",
    "CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NUMBER_OF_NUCLEAR_WARHEADS"),'nan'),'NaN'),'NAN'),'')) AS "NUMBER_OF_NUCLEAR_WARHEADS",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_OWID_NUCLEAR_WARHEADS;

CREATE OR REPLACE VIEW THE_LIBRARY.CRIME_SECURITY.POLICE_FATAL_SHOOTINGS COPY GRANTS COMMENT='The Washington Post''s incident-level record of people shot and killed by US police: name, age, race, date, city/county/state, lat/lon, and the agency (via AGENCY_IDS). The standard citable source for police-violence reporting. Heads up: fatal SHOOTINGS only -- it excludes Tasers, in-custody deaths, and vehicle deaths, so it undercounts total police killings. Raw as loaded (text); AGENCY_IDS is a delimited list that needs unnesting to name the agency, and lat/lon are often block-level.' AS
SELECT
    "ID",
    CASE WHEN TRIM("DATE") LIKE '%-%' OR TRIM("DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE")) END AS "DATE",
    "THREAT_TYPE",
    "FLEE_STATUS",
    "ARMED_WITH",
    "CITY",
    "COUNTY",
    "STATE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LATITUDE"),'nan'),'NaN'),'NAN'),'')) AS "LATITUDE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LONGITUDE"),'nan'),'NaN'),'NAN'),'')) AS "LONGITUDE",
    "LOCATION_PRECISION",
    "NAME",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("AGE"),'nan'),'NaN'),'NAN'),'')) AS "AGE",
    "GENDER",
    "RACE",
    "RACE_SOURCE",
    "WAS_MENTAL_ILLNESS_RELATED",
    "BODY_CAMERA",
    "AGENCY_IDS",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_WAPO_FATAL_FORCE;

CREATE OR REPLACE VIEW THE_LIBRARY.CRIME_SECURITY.TERRORISM_DEATHS COPY GRANTS COMMENT='For each country and year, the number of people killed in terrorist attacks. Good for tracking where and when terrorism spikes; what counts as ''terrorism'' is a definitional call made by the source, so compare carefully. Raw as loaded (all text); no join key, matched on country name/code. From Our World in Data.' AS
SELECT
    "ENTITY",
    "CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FATALITIES"),'nan'),'NaN'),'NAN'),'')) AS "FATALITIES",
    "WORLD_REGION_ACCORDING_TO_OWID",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_OWID_TERRORISM_DEATHS;

CREATE OR REPLACE VIEW THE_LIBRARY.ECONOMY.FAMINE_FOOD_INSECURITY COPY GRANTS COMMENT='The official famine-tracking data (IPC): how many people fall into each hunger phase -- from stressed up to Phase 5, Famine -- for a country and analysis window. Each row is one phase for one country/date, with the head count and the share of the population it represents. This is the data behind ''famine confirmed'' headlines. Country is an ISO3 code. Raw landing table: every value stored as text, exactly as loaded, so cast the numbers before you do math on them.' AS
SELECT
    "DATE_OF_ANALYSIS",
    "COUNTRY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_COUNTRY_POPULATION"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_COUNTRY_POPULATION",
    "VALIDITY_PERIOD",
    "C_FROM",
    "C_TO",
    "PHASE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NUMBER"),'nan'),'NaN'),'NAN'),'')) AS "NUMBER",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PERCENTAGE"),'nan'),'NaN'),'NAN'),'')) AS "PERCENTAGE",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_IPC_FOOD_INSECURITY_GLOBAL;

CREATE OR REPLACE VIEW THE_LIBRARY.ECONOMY.GLOBAL_FOOD_AGRICULTURE_STATS COPY GRANTS COMMENT='Meant to hold FAO''s global food, agriculture, and trade statistics. Four rows of raw content landed -- a dead probe, not data. Needs a proper re-pour against the FAOSTAT bulk endpoints before it''s anything.' AS
SELECT
    "DATASETCODE",
    "DATASETNAME",
    "TOPIC",
    "DATASETDESCRIPTION",
    CASE WHEN TRIM("DATEUPDATE") LIKE '%-%' OR TRIM("DATEUPDATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATEUPDATE")) END AS "DATEUPDATE",
    "FILELOCATION",
    "FILESIZE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FILEROWS"),'nan'),'NaN'),'NAN'),'')) AS "FILEROWS",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_FAO_FAOSTAT;

CREATE OR REPLACE VIEW THE_LIBRARY.ECONOMY.INCOME_INEQUALITY_GINI COPY GRANTS COMMENT='Income inequality measured by the Gini index, by country and year (Our World in Data). Gini runs 0 (everyone earns the same) to 1 (one person has it all), so a single row tells you how lopsided a country''s income was in a given year, tagged with world region. Country is an ISO3 code for joining. Raw landing table -- values stored as text; cast the coefficient before comparing. Coverage varies by country and year, so it''s uneven, not a complete grid.' AS
SELECT
    "ENTITY",
    "CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GINI_COEFFICIENT"),'nan'),'NaN'),'NAN'),'')) AS "GINI_COEFFICIENT",
    "WORLD_REGION_ACCORDING_TO_OWID",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_OWID_GINI;

CREATE OR REPLACE VIEW THE_LIBRARY.ECONOMY.PENSION_INSURANCE_STATS COPY GRANTS COMMENT='Statistical tables from the Pension Benefit Guaranty Corporation covering the single-employer and multiemployer insurance programs: financial position, claims, and benefit payments, in long metric format by year. Context table for pension-failure stories; pairs with RETIREMENT_PLAN_FILINGS.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DATA_YEAR"),'nan'),'NaN'),'NAN'),'')) AS "DATA_YEAR",
    "PUBLICATION_DATE",
    "PROGRAM_TYPE",
    "TABLE_NAME",
    "METRIC_NAME",
    "METRIC_VALUE",
    "UNIT",
    "STATE",
    "SOURCE_FILE",
    "NOTES_FLAG",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_PBGC_DATA;

CREATE OR REPLACE VIEW THE_LIBRARY.ECONOMY.RETIREMENT_PLAN_FILINGS COPY GRANTS COMMENT='Annual Form 5500 filings: plan name, sponsor and its EIN, plan year, participant counts, and plan type for employer retirement/welfare plans. The sponsor EIN column is gold -- it hard-joins employers to the nonprofit master file, SEC filers, and anything else EIN-keyed.' AS
SELECT
    "ACK_ID",
    "FORM_YEAR",
    "PLAN_YEAR_BEGIN_DATE",
    "PLAN_YEAR_END_DATE",
    "EIN",
    "PLAN_NUM",
    "PLAN_NAME",
    "SPONSOR_DFE_NAME",
    "SPONSOR_DFE_EIN",
    "SPONS_DFE_MAIL_US_STATE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TYPE_PLAN_ENTITY_CD"),'nan'),'NaN'),'NAN'),'')) AS "TYPE_PLAN_ENTITY_CD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOT_PARTCP_BOY_CNT"),'nan'),'NaN'),'NAN'),'')) AS "TOT_PARTCP_BOY_CNT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOT_ACTIVE_PARTCP_CNT"),'nan'),'NaN'),'NAN'),'')) AS "TOT_ACTIVE_PARTCP_CNT",
    "NET_ASSETS_EOY_AMT",
    "TOTAL_ASSETS_BOY_AMT",
    "TOTAL_ASSETS_EOY_AMT",
    "BENEFIT_PYMTS_TOTAL_AMT",
    "ADMIN_EXPENSES_TOTAL_AMT",
    "FILING_STATUS",
    CASE WHEN TRIM("DATE_RECEIVED") LIKE '%-%' OR TRIM("DATE_RECEIVED") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE_RECEIVED")) END AS "DATE_RECEIVED",
    "PREPARER_EIN",
    "BUSINESS_CODE",
    CASE WHEN TRIM("FORM_PLAN_YEAR_BEGIN_DATE") LIKE '%-%' OR TRIM("FORM_PLAN_YEAR_BEGIN_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("FORM_PLAN_YEAR_BEGIN_DATE")) END AS "FORM_PLAN_YEAR_BEGIN_DATE",
    "FORM_TAX_PRD",
    "TYPE_DFE_PLAN_ENTITY_CD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("INITIAL_FILING_IND"),'nan'),'NaN'),'NAN'),'')) AS "INITIAL_FILING_IND",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("AMENDED_IND"),'nan'),'NaN'),'NAN'),'')) AS "AMENDED_IND",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FINAL_FILING_IND"),'nan'),'NaN'),'NAN'),'')) AS "FINAL_FILING_IND",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SHORT_PLAN_YR_IND"),'nan'),'NaN'),'NAN'),'')) AS "SHORT_PLAN_YR_IND",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COLLECTIVE_BARGAIN_IND"),'nan'),'NaN'),'NAN'),'')) AS "COLLECTIVE_BARGAIN_IND",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("F5558_APPLICATION_FILED_IND"),'nan'),'NaN'),'NAN'),'')) AS "F5558_APPLICATION_FILED_IND",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXT_AUTOMATIC_IND"),'nan'),'NaN'),'NAN'),'')) AS "EXT_AUTOMATIC_IND",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DFVC_PROGRAM_IND"),'nan'),'NaN'),'NAN'),'')) AS "DFVC_PROGRAM_IND",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXT_SPECIAL_IND"),'nan'),'NaN'),'NAN'),'')) AS "EXT_SPECIAL_IND",
    "EXT_SPECIAL_TEXT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SPONS_DFE_PN"),'nan'),'NaN'),'NAN'),'')) AS "SPONS_DFE_PN",
    CASE WHEN TRIM("PLAN_EFF_DATE") LIKE '%-%' OR TRIM("PLAN_EFF_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("PLAN_EFF_DATE")) END AS "PLAN_EFF_DATE",
    "SPONS_DFE_DBA_NAME",
