    "SPONS_DFE_MAIL_FOREIGN_CITY",
    "SPONS_DFE_MAIL_FORGN_PROV_ST",
    "SPONS_DFE_MAIL_FOREIGN_CNTRY",
    "SPONS_DFE_MAIL_FORGN_POSTAL_CD",
