    "TYPE_WELFARE_BNFT_CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FUNDING_INSURANCE_IND"),'nan'),'NaN'),'NAN'),'')) AS "FUNDING_INSURANCE_IND",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FUNDING_SEC412_IND"),'nan'),'NaN'),'NAN'),'')) AS "FUNDING_SEC412_IND",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FUNDING_TRUST_IND"),'nan'),'NaN'),'NAN'),'')) AS "FUNDING_TRUST_IND",
