    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENEFIT_GEN_ASSET_IND"),'nan'),'NaN'),'NAN'),'')) AS "BENEFIT_GEN_ASSET_IND",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SCH_R_ATTACHED_IND"),'nan'),'NaN'),'NAN'),'')) AS "SCH_R_ATTACHED_IND",
