CREATE OR REPLACE VIEW THE_LIBRARY.ELECTIONS.ELECTION_ADMINISTRATION_SURVEY COPY GRANTS COMMENT='The federal Election Administration and Voting Survey, one row per local election jurisdiction: voter registration counts, absentee/mail ballot volumes, provisional ballots, polling places, and poll-worker numbers. Column names are survey question codes (A1a, B2c...) -- you''ll want the EAVS codebook open when you query it. FIPS codes join it to any county-level table.' AS
SELECT
    "FIPSCODE",
    "JURISDICTION_NAME",
    "STATE_FULL",
    "STATE_ABBR",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A1A"),'nan'),'NaN'),'NAN'),'')) AS "A1A",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A1B"),'nan'),'NaN'),'NAN'),'')) AS "A1B",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A1C"),'nan'),'NaN'),'NAN'),'')) AS "A1C",
    "A1COMMENTS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A2A"),'nan'),'NaN'),'NAN'),'')) AS "A2A",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A2B"),'nan'),'NaN'),'NAN'),'')) AS "A2B",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A2C"),'nan'),'NaN'),'NAN'),'')) AS "A2C",
    "A2COMMENTS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A3A"),'nan'),'NaN'),'NAN'),'')) AS "A3A",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A3B"),'nan'),'NaN'),'NAN'),'')) AS "A3B",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A3C"),'nan'),'NaN'),'NAN'),'')) AS "A3C",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A3D"),'nan'),'NaN'),'NAN'),'')) AS "A3D",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A3E"),'nan'),'NaN'),'NAN'),'')) AS "A3E",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A3F"),'nan'),'NaN'),'NAN'),'')) AS "A3F",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A3G"),'nan'),'NaN'),'NAN'),'')) AS "A3G",
    "A3H_OTHER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A3H"),'nan'),'NaN'),'NAN'),'')) AS "A3H",
    "A3I_OTHER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A3I"),'nan'),'NaN'),'NAN'),'')) AS "A3I",
    "A3J_OTHER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("A3J"),'nan'),'NaN'),'NAN'),'')) AS "A3J",
