CREATE OR REPLACE VIEW THE_LIBRARY.ELECTIONS.HOUSE_ELECTION_RESULTS COPY GRANTS COMMENT='District-level US House general-election returns, one row per candidate per district per year (29,636 rows): votes, total votes, party, and special/runoff flags. The cleaned ''who won the House'' source. Keyed by state FIPS + district; the winner links to the member spine by name+state+district (fuzzy -- no FEC ID in the file). Raw text landing (MIT Election Data + Science Lab).' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    "STATE",
    "STATE_PO",
    "STATE_FIPS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("STATE_CEN"),'nan'),'NaN'),'NAN'),'')) AS "STATE_CEN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("STATE_IC"),'nan'),'NaN'),'NAN'),'')) AS "STATE_IC",
    "OFFICE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DISTRICT"),'nan'),'NaN'),'NAN'),'')) AS "DISTRICT",
    "STAGE",
    "RUNOFF",
    "SPECIAL",
    "CANDIDATE",
    "PARTY",
    "WRITEIN",
    "MODE",
    "CANDIDATEVOTES",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTALVOTES"),'nan'),'NaN'),'NAN'),'')) AS "TOTALVOTES",
    "UNOFFICIAL",
    "VERSION",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_MEDSL_HOUSE_RETURNS;

CREATE OR REPLACE VIEW THE_LIBRARY.ELECTIONS.PRESIDENTIAL_RESULTS_BY_STATE COPY GRANTS COMMENT='State-level US presidential election results: one row per candidate per state per year, with votes for that candidate and total votes cast. This is the ''who won each state'' geographic layer. Keyed by state FIPS so it joins to census and other geographic data -- but note the president is not in the Congress ID spine, so no member-of-Congress link. Raw landing, stored as text; 3,740 rows.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    "STATE",
    "STATE_PO",
    "STATE_FIPS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("STATE_CEN"),'nan'),'NaN'),'NAN'),'')) AS "STATE_CEN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("STATE_IC"),'nan'),'NaN'),'NAN'),'')) AS "STATE_IC",
    "OFFICE",
    "CANDIDATE",
    "PARTY",
    "WRITEIN",
    "CANDIDATEVOTES",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTALVOTES"),'nan'),'NaN'),'NAN'),'')) AS "TOTALVOTES",
    "VERSION",
    "NOTES",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_MEDSL_PRESIDENT_RETURNS;

CREATE OR REPLACE VIEW THE_LIBRARY.ELECTIONS.SENATE_ELECTION_RESULTS COPY GRANTS COMMENT='State-level Senate general-election returns, one row per candidate per race per year (3,945 rows): votes, total votes, party, plus flags for special elections and runoffs. The cleaned canonical ''who won the Senate'' source. Keyed by state FIPS; the winner links to the member spine by name+state (fuzzy -- no FEC ID in the file). Raw text landing (MIT Election Data + Science Lab).' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    "STATE",
    "STATE_PO",
    "STATE_FIPS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("STATE_CEN"),'nan'),'NaN'),'NAN'),'')) AS "STATE_CEN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("STATE_IC"),'nan'),'NaN'),'NAN'),'')) AS "STATE_IC",
    "OFFICE",
    "DISTRICT",
    "STAGE",
    "SPECIAL",
    "CANDIDATE",
    "PARTY_DETAILED",
    "WRITEIN",
    "MODE",
    "CANDIDATEVOTES",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTALVOTES"),'nan'),'NaN'),'NAN'),'')) AS "TOTALVOTES",
    "UNOFFICIAL",
    "VERSION",
    "PARTY_SIMPLIFIED",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_MEDSL_SENATE_RETURNS;

CREATE OR REPLACE VIEW THE_LIBRARY.ENERGY_ENVIRONMENT.CO2_EMISSIONS_ANNUAL COPY GRANTS COMMENT='For each country and year, its total annual CO2 emissions -- the core number behind who''s driving climate change and how that''s shifted over time. Note this is total emissions, not per-person. Raw as loaded (all text); no join key, matched on country name/code. From Our World in Data.' AS
SELECT
    "ENTITY",
    "CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ANNUAL_CO_EMISSIONS"),'nan'),'NaN'),'NAN'),'')) AS "ANNUAL_CO_EMISSIONS",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_OWID_CO2;

CREATE OR REPLACE VIEW THE_LIBRARY.ENERGY_ENVIRONMENT.ENVIRONMENTAL_DEFENDER_ATTACKS COPY GRANTS COMMENT='One row per documented killing, disappearance, or attack on a land/environmental defender: name, country, year, sector (mining, logging, agribusiness...), and alleged perpetrator type. Compiled by Global Witness -- grim, careful data that pairs with mining and land-deal tables.' AS
SELECT
    "DEFENDER_NAME",
    "COUNTRY",
    "REGION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    "INCIDENT_TYPE",
    "SECTOR",
    "INDIGENOUS_STATUS",
    "GENDER",
    "PERPETRATOR",
    "SOURCE_REPORT",
    "NOTES_CONTEXT",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_GLOBAL_WITNESS_DEFENDERS;

CREATE OR REPLACE VIEW THE_LIBRARY.ENERGY_ENVIRONMENT.FOSSIL_FUEL_ENERGY_SHARE COPY GRANTS COMMENT='For every country and year, what percent of primary energy came from coal, oil, and gas. The single clearest number for how far off fossil fuels a country still is. Raw as loaded (all text) -- cast the year and percent before charting. From Our World in Data; no join key, matched on country name/code.' AS
SELECT
    "ENTITY",
    "CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FOSSIL_FUELS"),'nan'),'NaN'),'NAN'),'')) AS "FOSSIL_FUELS",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_OWID_FOSSIL_SHARE;

CREATE OR REPLACE VIEW THE_LIBRARY.ENERGY_ENVIRONMENT.GLOBAL_TEMPERATURE_ANOMALY COPY GRANTS COMMENT='Global temperature anomaly by year (Our World in Data): how much warmer or cooler each year was versus a long-run baseline, with upper and lower uncertainty bounds. This is the classic warming curve -- the closer you get to today, the higher the anomaly. Entity is usually ''World'' but region rows exist. Raw landing table -- values stored as text; cast the average and bounds before plotting the trend.' AS
SELECT
    "ENTITY",
    "CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("AVERAGE"),'nan'),'NaN'),'NAN'),'')) AS "AVERAGE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LOWER_BOUND"),'nan'),'NaN'),'NAN'),'')) AS "LOWER_BOUND",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("UPPER_BOUND"),'nan'),'NaN'),'NAN'),'')) AS "UPPER_BOUND",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_OWID_TEMP_ANOMALY;

CREATE OR REPLACE VIEW THE_LIBRARY.ENERGY_ENVIRONMENT.MINERAL_PRODUCTION_BY_COUNTRY COPY GRANTS COMMENT='USGS mineral resources data: who produces how much of which commodity, reserves, rank, and how import-reliant the US is -- including critical minerals. Country and commodity by year make this the reference table for supply-chain and resource-leverage questions.' AS
SELECT
    "COUNTRY",
