    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LONGITUDE"),'nan'),'NaN'),'NAN'),'')) AS "LONGITUDE",
    "REGION",
    "STATE",
    "COUNTY",
    "COM_TYPE",
    "COMMOD1",
    "COMMOD2",
    "COMMOD3",
    "OPER_TYPE",
    "DEP_TYPE",
    "PROD_SIZE",
    "DEV_STAT",
    "ORE",
    "GANGUE",
    "OTHER_MATL",
    "OREBODY_FM",
    "WORK_TYPE",
    "MODEL",
    "ALTERATION",
    "CONC_PROC",
    "NAMES",
    "ORE_CTRL",
    "REPORTER",
    "HROCK_UNIT",
    "HROCK_TYPE",
    "AROCK_UNIT",
    "AROCK_TYPE",
    "STRUCTURE",
    "TECTONIC",
    "REF",
    "YFP_BA",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YR_FST_PRD"),'nan'),'NaN'),'NAN'),'')) AS "YR_FST_PRD",
    "YLP_BA",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YR_LST_PRD"),'nan'),'NaN'),'NAN'),'')) AS "YR_LST_PRD",
    "DY_BA",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DISC_YR"),'nan'),'NaN'),'NAN'),'')) AS "DISC_YR",
