CREATE OR REPLACE VIEW THE_LIBRARY.ENERGY_ENVIRONMENT.POLLUTION_ENFORCEMENT COPY GRANTS COMMENT='EPA''s ECHO file: 3.2 million regulated facilities and their enforcement record -- inspections, violations, penalties, and compliance status across air, water, waste, and drinking-water programs. Cross it with who''s getting fined vs. who keeps polluting and you find where enforcement breaks down. Carries lat/lon and FIPS for spatial joins. Raw landing table, values stored as text.' AS
SELECT
    "FRS_ID",
    "FAC_NAME",
    "FAC_STREET",
    "FAC_CITY",
    "FAC_STATE",
    "FAC_ZIP",
    "FAC_COUNTY",
    "FAC_FIPS_CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_EPA_REGION"),'nan'),'NaN'),'NAN'),'')) AS "FAC_EPA_REGION",
    "FAC_INDIAN_CNTRY_FLG",
    "FAC_FEDERAL_FLG",
    "FAC_US_MEX_BORDER_FLG",
    "FAC_CHESAPEAKE_BAY_FLG",
    "FAC_NAA_FLAG",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_LAT"),'nan'),'NaN'),'NAN'),'')) AS "FAC_LAT",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_LONG"),'nan'),'NaN'),'NAN'),'')) AS "FAC_LONG",
    "FAC_MAP_ICON",
    "FAC_COLLECTION_METHOD",
    "FAC_REFERENCE_POINT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_ACCURACY_METERS"),'nan'),'NaN'),'NAN'),'')) AS "FAC_ACCURACY_METERS",
    "FAC_DERIVED_TRIBES",
    "FAC_DERIVED_HUC",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_DERIVED_WBD"),'nan'),'NaN'),'NAN'),'')) AS "FAC_DERIVED_WBD",
    "FAC_DERIVED_STCTY_FIPS",
    "FAC_DERIVED_ZIP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_DERIVED_CD113"),'nan'),'NaN'),'NAN'),'')) AS "FAC_DERIVED_CD113",
    "FAC_DERIVED_CB2010",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_PERCENT_MINORITY"),'nan'),'NaN'),'NAN'),'')) AS "FAC_PERCENT_MINORITY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_POP_DEN"),'nan'),'NaN'),'NAN'),'')) AS "FAC_POP_DEN",
    "FAC_MAJOR_FLAG",
    "FAC_ACTIVE_FLAG",
    "FAC_MYRTK_UNIVERSE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_INSPECTION_COUNT"),'nan'),'NaN'),'NAN'),'')) AS "FAC_INSPECTION_COUNT",
    CASE WHEN TRIM("FAC_DATE_LAST_INSPECTION") LIKE '%-%' OR TRIM("FAC_DATE_LAST_INSPECTION") LIKE '%/%' THEN TRY_TO_DATE(TRIM("FAC_DATE_LAST_INSPECTION")) END AS "FAC_DATE_LAST_INSPECTION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_DAYS_LAST_INSPECTION"),'nan'),'NaN'),'NAN'),'')) AS "FAC_DAYS_LAST_INSPECTION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_INFORMAL_COUNT"),'nan'),'NaN'),'NAN'),'')) AS "FAC_INFORMAL_COUNT",
    CASE WHEN TRIM("FAC_DATE_LAST_INFORMAL_ACTION") LIKE '%-%' OR TRIM("FAC_DATE_LAST_INFORMAL_ACTION") LIKE '%/%' THEN TRY_TO_DATE(TRIM("FAC_DATE_LAST_INFORMAL_ACTION")) END AS "FAC_DATE_LAST_INFORMAL_ACTION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_FORMAL_ACTION_COUNT"),'nan'),'NaN'),'NAN'),'')) AS "FAC_FORMAL_ACTION_COUNT",
    CASE WHEN TRIM("FAC_DATE_LAST_FORMAL_ACTION") LIKE '%-%' OR TRIM("FAC_DATE_LAST_FORMAL_ACTION") LIKE '%/%' THEN TRY_TO_DATE(TRIM("FAC_DATE_LAST_FORMAL_ACTION")) END AS "FAC_DATE_LAST_FORMAL_ACTION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_TOTAL_PENALTIES"),'nan'),'NaN'),'NAN'),'')) AS "FAC_TOTAL_PENALTIES",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_PENALTY_COUNT"),'nan'),'NaN'),'NAN'),'')) AS "FAC_PENALTY_COUNT",
    CASE WHEN TRIM("FAC_DATE_LAST_PENALTY") LIKE '%-%' OR TRIM("FAC_DATE_LAST_PENALTY") LIKE '%/%' THEN TRY_TO_DATE(TRIM("FAC_DATE_LAST_PENALTY")) END AS "FAC_DATE_LAST_PENALTY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_LAST_PENALTY_AMT"),'nan'),'NaN'),'NAN'),'')) AS "FAC_LAST_PENALTY_AMT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_QTRS_WITH_NC"),'nan'),'NaN'),'NAN'),'')) AS "FAC_QTRS_WITH_NC",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FAC_PROGRAMS_WITH_SNC"),'nan'),'NaN'),'NAN'),'')) AS "FAC_PROGRAMS_WITH_SNC",
    "FAC_COMPLIANCE_STATUS",
    "FAC_SNC_FLG",
    "FAC_3YR_COMPLIANCE_HISTORY",
    "AIR_FLAG",
    "NPDES_FLAG",
    "SDWIS_FLAG",
    "RCRA_FLAG",
    "TRI_FLAG",
    "GHG_FLAG",
    "AIR_IDS",
    "CAA_PERMIT_TYPES",
    "CAA_NAICS",
    "CAA_SICS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CAA_EVALUATION_COUNT"),'nan'),'NaN'),'NAN'),'')) AS "CAA_EVALUATION_COUNT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CAA_DAYS_LAST_EVALUATION"),'nan'),'NaN'),'NAN'),'')) AS "CAA_DAYS_LAST_EVALUATION",
    "CAA_INFORMAL_COUNT",
    "CAA_FORMAL_ACTION_COUNT",
    CASE WHEN TRIM("CAA_DATE_LAST_FORMAL_ACTION") LIKE '%-%' OR TRIM("CAA_DATE_LAST_FORMAL_ACTION") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CAA_DATE_LAST_FORMAL_ACTION")) END AS "CAA_DATE_LAST_FORMAL_ACTION",
    "CAA_PENALTIES",
    CASE WHEN TRIM("CAA_LAST_PENALTY_DATE") LIKE '%-%' OR TRIM("CAA_LAST_PENALTY_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CAA_LAST_PENALTY_DATE")) END AS "CAA_LAST_PENALTY_DATE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CAA_LAST_PENALTY_AMT"),'nan'),'NaN'),'NAN'),'')) AS "CAA_LAST_PENALTY_AMT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CAA_QTRS_WITH_NC"),'nan'),'NaN'),'NAN'),'')) AS "CAA_QTRS_WITH_NC",
    "CAA_COMPLIANCE_STATUS",
    "CAA_HPV_FLAG",
    "CAA_3YR_COMPL_QTRS_HISTORY",
    "NPDES_IDS",
    "CWA_PERMIT_TYPES",
    "CWA_COMPLIANCE_TRACKING",
    "CWA_NAICS",
    "CWA_SICS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CWA_INSPECTION_COUNT"),'nan'),'NaN'),'NAN'),'')) AS "CWA_INSPECTION_COUNT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CWA_DAYS_LAST_INSPECTION"),'nan'),'NaN'),'NAN'),'')) AS "CWA_DAYS_LAST_INSPECTION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CWA_INFORMAL_COUNT"),'nan'),'NaN'),'NAN'),'')) AS "CWA_INFORMAL_COUNT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CWA_FORMAL_ACTION_COUNT"),'nan'),'NaN'),'NAN'),'')) AS "CWA_FORMAL_ACTION_COUNT",
    CASE WHEN TRIM("CWA_DATE_LAST_FORMAL_ACTION") LIKE '%-%' OR TRIM("CWA_DATE_LAST_FORMAL_ACTION") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CWA_DATE_LAST_FORMAL_ACTION")) END AS "CWA_DATE_LAST_FORMAL_ACTION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CWA_PENALTIES"),'nan'),'NaN'),'NAN'),'')) AS "CWA_PENALTIES",
    CASE WHEN TRIM("CWA_LAST_PENALTY_DATE") LIKE '%-%' OR TRIM("CWA_LAST_PENALTY_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CWA_LAST_PENALTY_DATE")) END AS "CWA_LAST_PENALTY_DATE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CWA_LAST_PENALTY_AMT"),'nan'),'NaN'),'NAN'),'')) AS "CWA_LAST_PENALTY_AMT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CWA_QTRS_WITH_NC"),'nan'),'NaN'),'NAN'),'')) AS "CWA_QTRS_WITH_NC",
    "CWA_COMPLIANCE_STATUS",
    "CWA_SNC_FLAG",
    "CWA_13QTRS_COMPL_HISTORY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CWA_13QTRS_EFFLNT_EXCEEDANCES"),'nan'),'NaN'),'NAN'),'')) AS "CWA_13QTRS_EFFLNT_EXCEEDANCES",
    "CWA_3_YR_QNCR_CODES",
    "RCRA_IDS",
    "RCRA_PERMIT_TYPES",
    "RCRA_NAICS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RCRA_INSPECTION_COUNT"),'nan'),'NaN'),'NAN'),'')) AS "RCRA_INSPECTION_COUNT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RCRA_DAYS_LAST_EVALUATION"),'nan'),'NaN'),'NAN'),'')) AS "RCRA_DAYS_LAST_EVALUATION",
    "RCRA_INFORMAL_COUNT",
    "RCRA_FORMAL_ACTION_COUNT",
    CASE WHEN TRIM("RCRA_DATE_LAST_FORMAL_ACTION") LIKE '%-%' OR TRIM("RCRA_DATE_LAST_FORMAL_ACTION") LIKE '%/%' THEN TRY_TO_DATE(TRIM("RCRA_DATE_LAST_FORMAL_ACTION")) END AS "RCRA_DATE_LAST_FORMAL_ACTION",
    "RCRA_PENALTIES",
    CASE WHEN TRIM("RCRA_LAST_PENALTY_DATE") LIKE '%-%' OR TRIM("RCRA_LAST_PENALTY_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("RCRA_LAST_PENALTY_DATE")) END AS "RCRA_LAST_PENALTY_DATE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RCRA_LAST_PENALTY_AMT"),'nan'),'NaN'),'NAN'),'')) AS "RCRA_LAST_PENALTY_AMT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RCRA_QTRS_WITH_NC"),'nan'),'NaN'),'NAN'),'')) AS "RCRA_QTRS_WITH_NC",
    "RCRA_COMPLIANCE_STATUS",
    "RCRA_SNC_FLAG",
    "RCRA_3YR_COMPL_QTRS_HISTORY",
    "SDWA_IDS",
    "SDWA_SYSTEM_TYPES",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SDWA_INFORMAL_COUNT"),'nan'),'NaN'),'NAN'),'')) AS "SDWA_INFORMAL_COUNT",
    "SDWA_FORMAL_ACTION_COUNT",
    "SDWA_COMPLIANCE_STATUS",
    "SDWA_SNC_FLAG",
    "TRI_IDS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TRI_RELEASES_TRANSFERS"),'nan'),'NaN'),'NAN'),'')) AS "TRI_RELEASES_TRANSFERS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TRI_ON_SITE_RELEASES"),'nan'),'NaN'),'NAN'),'')) AS "TRI_ON_SITE_RELEASES",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TRI_OFF_SITE_TRANSFERS"),'nan'),'NaN'),'NAN'),'')) AS "TRI_OFF_SITE_TRANSFERS",
    "TRI_REPORTER_IN_PAST",
    "FEC_CASE_IDS",
    "FEC_NUMBER_OF_CASES",
    CASE WHEN TRIM("FEC_LAST_CASE_DATE") LIKE '%-%' OR TRIM("FEC_LAST_CASE_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("FEC_LAST_CASE_DATE")) END AS "FEC_LAST_CASE_DATE",
    "FEC_TOTAL_PENALTIES",
    "GHG_IDS",
    "GHG_CO2_RELEASES",
    "DFR_URL",
    "FAC_SIC_CODES",
    "FAC_NAICS_CODES",
    CASE WHEN TRIM("FAC_DATE_LAST_INSPECTION_EPA") LIKE '%-%' OR TRIM("FAC_DATE_LAST_INSPECTION_EPA") LIKE '%/%' THEN TRY_TO_DATE(TRIM("FAC_DATE_LAST_INSPECTION_EPA")) END AS "FAC_DATE_LAST_INSPECTION_EPA",
    CASE WHEN TRIM("FAC_DATE_LAST_INSPECTION_STATE") LIKE '%-%' OR TRIM("FAC_DATE_LAST_INSPECTION_STATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("FAC_DATE_LAST_INSPECTION_STATE")) END AS "FAC_DATE_LAST_INSPECTION_STATE",
    CASE WHEN TRIM("FAC_DATE_LAST_FORMAL_ACT_EPA") LIKE '%-%' OR TRIM("FAC_DATE_LAST_FORMAL_ACT_EPA") LIKE '%/%' THEN TRY_TO_DATE(TRIM("FAC_DATE_LAST_FORMAL_ACT_EPA")) END AS "FAC_DATE_LAST_FORMAL_ACT_EPA",
    CASE WHEN TRIM("FAC_DATE_LAST_FORMAL_ACT_ST") LIKE '%-%' OR TRIM("FAC_DATE_LAST_FORMAL_ACT_ST") LIKE '%/%' THEN TRY_TO_DATE(TRIM("FAC_DATE_LAST_FORMAL_ACT_ST")) END AS "FAC_DATE_LAST_FORMAL_ACT_ST",
    CASE WHEN TRIM("FAC_DATE_LAST_INFORMAL_ACT_EPA") LIKE '%-%' OR TRIM("FAC_DATE_LAST_INFORMAL_ACT_EPA") LIKE '%/%' THEN TRY_TO_DATE(TRIM("FAC_DATE_LAST_INFORMAL_ACT_EPA")) END AS "FAC_DATE_LAST_INFORMAL_ACT_EPA",
    CASE WHEN TRIM("FAC_DATE_LAST_INFORMAL_ACT_ST") LIKE '%-%' OR TRIM("FAC_DATE_LAST_INFORMAL_ACT_ST") LIKE '%/%' THEN TRY_TO_DATE(TRIM("FAC_DATE_LAST_INFORMAL_ACT_ST")) END AS "FAC_DATE_LAST_INFORMAL_ACT_ST",
    "FAC_FEDERAL_AGENCY",
    "TRI_REPORTER",
    "FAC_IMP_WATER_FLG",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_EPA_ECHO;

CREATE OR REPLACE VIEW THE_LIBRARY.ENERGY_ENVIRONMENT.STORM_EVENTS COPY GRANTS COMMENT='NOAA''s event-by-event record of US extreme weather: what happened (tornado, flood, heat, etc), where (lat/lon and FIPS), and the human and economic toll -- fatalities, injuries, and property/crop damage. The granular impact layer that disaster declarations miss. Heads up: damage amounts are text with K/M/B suffixes (''2.5K'', ''10.00M'') that must be parsed, and CZ_TYPE=''Z'' rows are NWS forecast zones, not counties -- don''t blindly join those to county FIPS. Raw as loaded (every value stored as text).' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BEGIN_YEARMONTH"),'nan'),'NaN'),'NAN'),'')) AS "BEGIN_YEARMONTH",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BEGIN_DAY"),'nan'),'NaN'),'NAN'),'')) AS "BEGIN_DAY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BEGIN_TIME"),'nan'),'NaN'),'NAN'),'')) AS "BEGIN_TIME",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("END_YEARMONTH"),'nan'),'NaN'),'NAN'),'')) AS "END_YEARMONTH",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("END_DAY"),'nan'),'NaN'),'NAN'),'')) AS "END_DAY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("END_TIME"),'nan'),'NaN'),'NAN'),'')) AS "END_TIME",
    "EPISODE_ID",
    "EVENT_ID",
    "STATE",
    "STATE_FIPS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    "MONTH_NAME",
    "EVENT_TYPE",
    "CZ_TYPE",
    "CZ_FIPS",
    "CZ_NAME",
    "WFO",
    "BEGIN_DATE_TIME",
    "CZ_TIMEZONE",
    "END_DATE_TIME",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("INJURIES_DIRECT"),'nan'),'NaN'),'NAN'),'')) AS "INJURIES_DIRECT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("INJURIES_INDIRECT"),'nan'),'NaN'),'NAN'),'')) AS "INJURIES_INDIRECT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEATHS_DIRECT"),'nan'),'NaN'),'NAN'),'')) AS "DEATHS_DIRECT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEATHS_INDIRECT"),'nan'),'NaN'),'NAN'),'')) AS "DEATHS_INDIRECT",
    "DAMAGE_PROPERTY",
    "DAMAGE_CROPS",
    "SOURCE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MAGNITUDE"),'nan'),'NaN'),'NAN'),'')) AS "MAGNITUDE",
    "MAGNITUDE_TYPE",
    "FLOOD_CAUSE",
    "CATEGORY",
    "TOR_F_SCALE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOR_LENGTH"),'nan'),'NaN'),'NAN'),'')) AS "TOR_LENGTH",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOR_WIDTH"),'nan'),'NaN'),'NAN'),'')) AS "TOR_WIDTH",
    "TOR_OTHER_WFO",
    "TOR_OTHER_CZ_STATE",
    "TOR_OTHER_CZ_FIPS",
    "TOR_OTHER_CZ_NAME",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BEGIN_RANGE"),'nan'),'NaN'),'NAN'),'')) AS "BEGIN_RANGE",
    "BEGIN_AZIMUTH",
    "BEGIN_LOCATION",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("END_RANGE"),'nan'),'NaN'),'NAN'),'')) AS "END_RANGE",
    "END_AZIMUTH",
    "END_LOCATION",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BEGIN_LAT"),'nan'),'NaN'),'NAN'),'')) AS "BEGIN_LAT",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BEGIN_LON"),'nan'),'NaN'),'NAN'),'')) AS "BEGIN_LON",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("END_LAT"),'nan'),'NaN'),'NAN'),'')) AS "END_LAT",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("END_LON"),'nan'),'NaN'),'NAN'),'')) AS "END_LON",
    "EPISODE_NARRATIVE",
    "EVENT_NARRATIVE",
    "DATA_SOURCE",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_NOAA_STORM_EVENTS;

CREATE OR REPLACE VIEW THE_LIBRARY.ENERGY_ENVIRONMENT.WATER_MONITORING_READINGS COPY GRANTS COMMENT='Readings from the USGS national water monitoring network: site, parameter (streamflow, gauge height, temperature...), timestamp, and value, with state/county codes and coordinates. 6.7 million rows of real instrument data -- the backbone for any drought, flood, or contamination timeline.' AS
SELECT
    "SITE_NO",
    "SITE_NAME",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PARAMETER_CD"),'nan'),'NaN'),'NAN'),'')) AS "PARAMETER_CD",
    "PARAMETER_NAME",
    CASE WHEN TRIM("DATETIME") LIKE '%-%' OR TRIM("DATETIME") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATETIME")) END AS "DATETIME",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("VALUE"),'nan'),'NaN'),'NAN'),'')) AS "VALUE",
    "UNIT_CD",
    "QUALIFIER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("STATE_CD"),'nan'),'NaN'),'NAN'),'')) AS "STATE_CD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COUNTY_CD"),'nan'),'NaN'),'NAN'),'')) AS "COUNTY_CD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HUC_CD"),'nan'),'NaN'),'NAN'),'')) AS "HUC_CD",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LATITUDE"),'nan'),'NaN'),'NAN'),'')) AS "LATITUDE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LONGITUDE"),'nan'),'NaN'),'NAN'),'')) AS "LONGITUDE",
    "AGENCY_CD",
    "DATA_TYPE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_USGS_WATER;

CREATE OR REPLACE VIEW THE_LIBRARY.GEOGRAPHY.EUROSTAT_INDICATORS COPY GRANTS COMMENT='Indicator observations from Eurostat''s SDMX API: dataflow, country, period, and value. A 450-row probe demonstrating the pipe. The country codes join to any ISO-keyed international table; specific indicators need targeted pours.' AS
SELECT
    "DATAFLOW_ID",
    "GEO",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TIME"),'nan'),'NaN'),'NAN'),'')) AS "TIME",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OBS_VALUE"),'nan'),'NaN'),'NAN'),'')) AS "OBS_VALUE",
    "OBS_STATUS",
    "UNIT",
    "FREQ",
    "INDICATOR",
    "RAW_XML_SERIES_KEY",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_EUROSTAT;

CREATE OR REPLACE VIEW THE_LIBRARY.GEOGRAPHY.FERTILITY_RATE_BY_COUNTRY COPY GRANTS COMMENT='The total fertility rate (average children born per woman) for every country over time, from Our World in Data. The demographic engine behind aging and population-decline stories. Carries ISO-3 country codes, so it joins to any country-keyed source in the Library. Raw as loaded (every value stored as text) -- includes regional/aggregate ''entity'' rows alongside individual countries.' AS
SELECT
    "ENTITY",
    "CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_FERTILITY_RATE"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_FERTILITY_RATE",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_OWID_FERTILITY;

CREATE OR REPLACE VIEW THE_LIBRARY.GEOGRAPHY.GLOBAL_NEWS_EVENTS COPY GRANTS COMMENT='Event records from GDELT 2.0, which scans world news every 15 minutes and codes events: actors, event codes, locations, and tone. A 1,015-row probe of a firehose that produces millions of rows daily. Powerful for timelines once poured at scale; treat machine-coded events as leads, not facts.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GLOBALEVENTID"),'nan'),'NaN'),'NAN'),'')) AS "GLOBALEVENTID",
    TRY_TO_DATE(TRIM("SQLDATE"),'YYYYMMDD') AS "SQLDATE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MONTHYEAR"),'nan'),'NaN'),'NAN'),'')) AS "MONTHYEAR",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    "FRACTIONDATE",
    "ACTOR1CODE",
    "ACTOR1NAME",
    "ACTOR1COUNTRYCODE",
    "ACTOR1TYPE1CODE",
    "ACTOR2CODE",
    "ACTOR2NAME",
    "ACTOR2COUNTRYCODE",
    "ACTOR2TYPE1CODE",
    "ISROOTEVENT",
    "EVENTCODE",
    "EVENTBASECODE",
    "EVENTROOTCODE",
    "QUADCLASS",
    "GOLDSTEINSCALE",
    "NUMMENTIONS",
    "NUMSOURCES",
    "NUMARTICLES",
    "AVGTONE",
    "ACTOR1GEO_TYPE",
    "ACTOR1GEO_FULLNAME",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTOR1GEO_COUNTRYCODE"),'nan'),'NaN'),'NAN'),'')) AS "ACTOR1GEO_COUNTRYCODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTOR1GEO_LAT"),'nan'),'NaN'),'NAN'),'')) AS "ACTOR1GEO_LAT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTOR1GEO_LONG"),'nan'),'NaN'),'NAN'),'')) AS "ACTOR1GEO_LONG",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTOR2GEO_TYPE"),'nan'),'NaN'),'NAN'),'')) AS "ACTOR2GEO_TYPE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTOR2GEO_FULLNAME"),'nan'),'NaN'),'NAN'),'')) AS "ACTOR2GEO_FULLNAME",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTOR2GEO_COUNTRYCODE"),'nan'),'NaN'),'NAN'),'')) AS "ACTOR2GEO_COUNTRYCODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTOR2GEO_LAT"),'nan'),'NaN'),'NAN'),'')) AS "ACTOR2GEO_LAT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTOR2GEO_LONG"),'nan'),'NaN'),'NAN'),'')) AS "ACTOR2GEO_LONG",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTIONGEO_TYPE"),'nan'),'NaN'),'NAN'),'')) AS "ACTIONGEO_TYPE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTIONGEO_FULLNAME"),'nan'),'NaN'),'NAN'),'')) AS "ACTIONGEO_FULLNAME",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTIONGEO_COUNTRYCODE"),'nan'),'NaN'),'NAN'),'')) AS "ACTIONGEO_COUNTRYCODE",
    "ACTIONGEO_LAT",
    "ACTIONGEO_LONG",
    "DATEADDED",
    "SOURCEURL",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXTRA_COL_0"),'nan'),'NaN'),'NAN'),'')) AS "EXTRA_COL_0",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXTRA_COL_1"),'nan'),'NaN'),'NAN'),'')) AS "EXTRA_COL_1",
    "EXTRA_COL_2",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXTRA_COL_3"),'nan'),'NaN'),'NAN'),'')) AS "EXTRA_COL_3",
    "EXTRA_COL_4",
    "EXTRA_COL_5",
    "EXTRA_COL_6",
    "EXTRA_COL_7",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXTRA_COL_8"),'nan'),'NaN'),'NAN'),'')) AS "EXTRA_COL_8",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXTRA_COL_9"),'nan'),'NaN'),'NAN'),'')) AS "EXTRA_COL_9",
    "EXTRA_COL_10",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXTRA_COL_11"),'nan'),'NaN'),'NAN'),'')) AS "EXTRA_COL_11",
    "EXTRA_COL_12",
    "EXTRA_COL_13",
    "EXTRA_COL_14",
    "EXTRA_COL_15",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXTRA_COL_16"),'nan'),'NaN'),'NAN'),'')) AS "EXTRA_COL_16",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXTRA_COL_17"),'nan'),'NaN'),'NAN'),'')) AS "EXTRA_COL_17",
    "EXTRA_COL_18",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXTRA_COL_19"),'nan'),'NaN'),'NAN'),'')) AS "EXTRA_COL_19",
    "EXTRA_COL_20",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_GDELT;

CREATE OR REPLACE VIEW THE_LIBRARY.GEOGRAPHY.HISTORICAL_TOPO_MAPS COPY GRANTS COMMENT='Catalog records for USGS''s scanned historical topo maps: title, creation/publication dates, file format, and download URL. A finding aid for ''what did the terrain look like then'' -- 250 rows probed from a much larger collection.' AS
SELECT
    "TITLE",
    "MPDESC",
    "SOURCEID",
    "SOURCENAME",
    CASE WHEN TRIM("DATECREATED") LIKE '%-%' OR TRIM("DATECREATED") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATECREATED")) END AS "DATECREATED",
    CASE WHEN TRIM("LASTUPDATED") LIKE '%-%' OR TRIM("LASTUPDATED") LIKE '%/%' THEN TRY_TO_DATE(TRIM("LASTUPDATED")) END AS "LASTUPDATED",
    CASE WHEN TRIM("PUBLICATIONDATE") LIKE '%-%' OR TRIM("PUBLICATIONDATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("PUBLICATIONDATE")) END AS "PUBLICATIONDATE",
    "DOWNLOADURL",
    "FILESIZE",
    "FILEFORMAT",
    "DATASETS",
    "BOUNDINGBOX",
    "FIPS",
    "STATE",
    "COUNTIES",
    "MAPSCALE",
    "PREVIEWGRAPHICURL",
    "METAURL",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_USGS_TOPOVIEW;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.APPEALS_JUDGE_IDEOLOGY COPY GRANTS COMMENT='The Judicial Common Space (JCS) lifetime ideology score for US Courts of Appeals judges, placed on the same left-right scale used for Congress. 705 rows, one per judge with name, circuit, and score. Lets you ask whether a case landed before a liberal or conservative bench. Heads up: raw landing (text-as-loaded) with no clean join key -- match to judges by name/circuit.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("UNNAMED_0"),'nan'),'NaN'),'NAN'),'')) AS "UNNAMED_0",
    "NAME",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CIRCUIT"),'nan'),'NaN'),'NAN'),'')) AS "CIRCUIT",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("JCS"),'nan'),'NaN'),'NAN'),'')) AS "JCS",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_JCS_COA;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.BILL_COSPONSORS_FED_GOVINFO_BILL_COSPONSORS COPY GRANTS COMMENT='The official GovInfo cosponsor list flattened to one row per (bill, cosponsor): the member''s bioguide id, party, state, whether they were an original cosponsor, the date they signed on, and the date they withdrew (if they did). Shows who backed what and who quietly pulled support. Keyed by member BIOGUIDE. Raw landing, stored as text.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CONGRESS"),'nan'),'NaN'),'NAN'),'')) AS "CONGRESS",
    "BILL_TYPE",
    "BILL_NUMBER",
    "COSPONSOR_BIOGUIDE",
    "COSPONSOR_NAME",
    "COSPONSOR_PARTY",
    "COSPONSOR_STATE",
    "IS_ORIGINAL",
    CASE WHEN TRIM("SPONSORSHIP_DATE") LIKE '%-%' OR TRIM("SPONSORSHIP_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("SPONSORSHIP_DATE")) END AS "SPONSORSHIP_DATE",
    "SPONSORSHIP_WITHDRAWN_DATE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_GOVINFO_BILL_COSPONSORS;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.CONGRESSIONAL_BILLS COPY GRANTS COMMENT='Official status records for 36,465 congressional measures: bill number, sponsor, cosponsor list, full action history, and a flag (with public-law number) for the ones that actually became law. Sponsor and cosponsors carry bioguide IDs, so it joins cleanly to the member roster -- follow a lawmaker to everything they''ve pushed. Raw landing table, values stored as text.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CONGRESS"),'nan'),'NaN'),'NAN'),'')) AS "CONGRESS",
    "BILL_TYPE",
    "BILL_NUMBER",
    CASE WHEN TRIM("INTRODUCED_DATE") LIKE '%-%' OR TRIM("INTRODUCED_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("INTRODUCED_DATE")) END AS "INTRODUCED_DATE",
    "TITLE",
    "SPONSOR_BIOGUIDE",
    "SPONSOR_NAME",
    "LAW_TYPE",
    "LAW_NUMBER",
    "ACTION_TYPES",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("N_ACTIONS"),'nan'),'NaN'),'NAN'),'')) AS "N_ACTIONS",
    CASE WHEN TRIM("LATEST_ACTION_DATE") LIKE '%-%' OR TRIM("LATEST_ACTION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("LATEST_ACTION_DATE")) END AS "LATEST_ACTION_DATE",
    "LATEST_ACTION_TEXT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("N_COSPONSORS"),'nan'),'NaN'),'NAN'),'')) AS "N_COSPONSORS",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_GOVINFO_BILLSTATUS;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.CONGRESSIONAL_ROLLCALL_VOTES_FED_VOTEVIEW_ROLLCALL_META COPY GRANTS COMMENT='One row per congressional roll-call vote (3,364 rows): the chamber, date, the question being voted on, the bill number, yea and nay counts, and whether it passed. This is the context and denominator for the member-by-member vote matrix -- what was voted on and how it came out. Keyed by congress+chamber+roll number. Raw text landing (Voteview / UCLA).' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CONGRESS"),'nan'),'NaN'),'NAN'),'')) AS "CONGRESS",
    "CHAMBER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ROLLNUMBER"),'nan'),'NaN'),'NAN'),'')) AS "ROLLNUMBER",
    CASE WHEN TRIM("DATE") LIKE '%-%' OR TRIM("DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE")) END AS "DATE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SESSION"),'nan'),'NaN'),'NAN'),'')) AS "SESSION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CLERK_ROLLNUMBER"),'nan'),'NaN'),'NAN'),'')) AS "CLERK_ROLLNUMBER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEA_COUNT"),'nan'),'NaN'),'NAN'),'')) AS "YEA_COUNT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NAY_COUNT"),'nan'),'NaN'),'NAN'),'')) AS "NAY_COUNT",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NOMINATE_MID_1"),'nan'),'NaN'),'NAN'),'')) AS "NOMINATE_MID_1",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NOMINATE_MID_2"),'nan'),'NaN'),'NAN'),'')) AS "NOMINATE_MID_2",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NOMINATE_SPREAD_1"),'nan'),'NaN'),'NAN'),'')) AS "NOMINATE_SPREAD_1",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NOMINATE_SPREAD_2"),'nan'),'NaN'),'NAN'),'')) AS "NOMINATE_SPREAD_2",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NOMINATE_LOG_LIKELIHOOD"),'nan'),'NaN'),'NAN'),'')) AS "NOMINATE_LOG_LIKELIHOOD",
    "BILL_NUMBER",
    "VOTE_RESULT",
    "VOTE_DESC",
    "VOTE_QUESTION",
    "DTL_DESC",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_VOTEVIEW_ROLLCALL_META;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.CONGRESS_COMMITTEE_MEMBERSHIP COPY GRANTS COMMENT='Current committee and subcommittee membership for Congress: which member sits on or chairs which committee, with their party, rank, and role. 3,879 rows keyed by BIOGUIDE, so it joins straight to the member spine -- letting you connect a lawmaker''s committee power to the industries donating to them. Raw landing, all text.' AS
SELECT
    "COMMITTEE_CODE",
    "COMMITTEE_NAME",
    "IS_SUBCOMMITTEE",
    "BIOGUIDE",
    "MEMBER_NAME",
    "PARTY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RANK"),'nan'),'NaN'),'NAN'),'')) AS "RANK",
    "TITLE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CONGRESS_COMMITTEE_MEMBERSHIP;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.CONGRESS_IDEOLOGY_SCORES COPY GRANTS COMMENT='The standard ideology measure (DW-NOMINATE) for every member of Congress in every Congress: a two-dimensional score placing each member on the liberal-conservative spectrum, plus basic bio. Keyed by ICPSR ID so it links to the Congress member spine. This is the small member-level file; the full member-by-vote matrix lives separately. Raw landing, stored as text; 51,061 rows from Voteview/UCLA.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CONGRESS"),'nan'),'NaN'),'NAN'),'')) AS "CONGRESS",
    "CHAMBER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ICPSR"),'nan'),'NaN'),'NAN'),'')) AS "ICPSR",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("STATE_ICPSR"),'nan'),'NaN'),'NAN'),'')) AS "STATE_ICPSR",
    "DISTRICT_CODE",
    "STATE_ABBREV",
    "PARTY_CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OCCUPANCY"),'nan'),'NaN'),'NAN'),'')) AS "OCCUPANCY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LAST_MEANS"),'nan'),'NaN'),'NAN'),'')) AS "LAST_MEANS",
    "BIONAME",
    "BIOGUIDE_ID",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BORN"),'nan'),'NaN'),'NAN'),'')) AS "BORN",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DIED"),'nan'),'NaN'),'NAN'),'')) AS "DIED",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NOMINATE_DIM1"),'nan'),'NaN'),'NAN'),'')) AS "NOMINATE_DIM1",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NOMINATE_DIM2"),'nan'),'NaN'),'NAN'),'')) AS "NOMINATE_DIM2",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NOMINATE_LOG_LIKELIHOOD"),'nan'),'NaN'),'NAN'),'')) AS "NOMINATE_LOG_LIKELIHOOD",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NOMINATE_GEO_MEAN_PROBABILITY"),'nan'),'NaN'),'NAN'),'')) AS "NOMINATE_GEO_MEAN_PROBABILITY",
    "NOMINATE_NUMBER_OF_VOTES",
    "NOMINATE_NUMBER_OF_ERRORS",
    "CONDITIONAL",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NOKKEN_POOLE_DIM1"),'nan'),'NaN'),'NAN'),'')) AS "NOKKEN_POOLE_DIM1",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NOKKEN_POOLE_DIM2"),'nan'),'NaN'),'NAN'),'')) AS "NOKKEN_POOLE_DIM2",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_VOTEVIEW_MEMBERS;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.CONGRESS_MEMBERS_FED_CONGRESS_LEGISLATORS COPY GRANTS COMMENT='Every current and historical member of Congress (plus presidents/VPs): name, party, state, district, terms, and birthday. The keystone: it carries the master ID crosswalk (bioguide, icpsr, fec, opensecrets, govtrack, votesmart, wikidata, and more) so a legislator here links to their votes, their money, and their bio anywhere. Raw landing, stored as text; 12,847 rows spanning all of US history.' AS
SELECT
    "BIOGUIDE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ICPSR"),'nan'),'NaN'),'NAN'),'')) AS "ICPSR",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("THOMAS"),'nan'),'NaN'),'NAN'),'')) AS "THOMAS",
    "LIS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GOVTRACK"),'nan'),'NaN'),'NAN'),'')) AS "GOVTRACK",
    "OPENSECRETS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("VOTESMART"),'nan'),'NaN'),'NAN'),'')) AS "VOTESMART",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CSPAN"),'nan'),'NaN'),'NAN'),'')) AS "CSPAN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HOUSE_HISTORY"),'nan'),'NaN'),'NAN'),'')) AS "HOUSE_HISTORY",
    "BALLOTPEDIA",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MAPLIGHT"),'nan'),'NaN'),'NAN'),'')) AS "MAPLIGHT",
    "WIKIDATA",
    "WIKIPEDIA",
    "GOOGLE_ENTITY_ID",
    "LEGISLATOR_SET",
    "FEC_IDS",
    "NAME_FIRST",
    "NAME_LAST",
    "NAME_OFFICIAL_FULL",
    "BIRTHDAY",
    "GENDER",
    "TERM_TYPE",
    "PARTY",
    "STATE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DISTRICT"),'nan'),'NaN'),'NAN'),'')) AS "DISTRICT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SENATE_CLASS"),'nan'),'NaN'),'NAN'),'')) AS "SENATE_CLASS",
    "TERM_START",
    "TERM_END",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("N_TERMS"),'nan'),'NaN'),'NAN'),'')) AS "N_TERMS",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CONGRESS_LEGISLATORS;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.CONGRESS_ROLLCALL_VOTES COPY GRANTS COMMENT='The full member-by-vote matrix from Voteview: one row per (member, roll-call) with how they voted (cast code), across the whole history of Congress. This is the raw fuel for missed-votes, party-unity, and vote-similarity stats. Members key on ICPSR id. Heads up: raw landing (every value text) -- it''s the vote grid, not the bill text or vote descriptions.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CONGRESS"),'nan'),'NaN'),'NAN'),'')) AS "CONGRESS",
    "CHAMBER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ROLLNUMBER"),'nan'),'NaN'),'NAN'),'')) AS "ROLLNUMBER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ICPSR"),'nan'),'NaN'),'NAN'),'')) AS "ICPSR",
    "CAST_CODE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PROB"),'nan'),'NaN'),'NAN'),'')) AS "PROB",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_VOTEVIEW_ROLLCALLS;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.CORRUPTION_PERCEPTIONS_INDEX COPY GRANTS COMMENT='For every country and year, its Corruption Perceptions Index score -- how corrupt its public sector is seen to be by experts and business people. A perception score, not a count of actual crimes, so read it as reputation. Raw as loaded (all text); no join key, matched on country name/code. From Our World in Data / Transparency International.' AS
SELECT
    "ENTITY",
    "CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CORRUPTION_PERCEPTIONS_INDEX"),'nan'),'NaN'),'NAN'),'')) AS "CORRUPTION_PERCEPTIONS_INDEX",
    "WORLD_REGION_ACCORDING_TO_OWID",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_OWID_CPI;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.COUNTRY_FREEDOM_SCORES COPY GRANTS COMMENT='The annual freedom scorecard: each country rated on political rights and civil liberties (2013-2024), broken into the A1-G4 sub-indicators that build the score -- the standard evidence for a democratic-backsliding story. 2,723 rows (country x year). Heads up: no ISO country code, so you need a name-to-country crosswalk to join it cleanly, and commercial reuse is restricted. Raw landing, all text.' AS
SELECT
    "COUNTRY_TERRITORY",
    "REGION",
    "C_T",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EDITION"),'nan'),'NaN'),'NAN'),'')) AS "EDITION",
