CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.FCC_RADIO_LICENSES COPY GRANTS COMMENT='The FCC Universal Licensing System: every radio station and wireless license, with call sign, licensee entity name, FRN, service code, and license status/dates. 1.7 million rows. Entity names and FRNs make it a solid who-operates-what lookup -- from ham radio to broadcast empires.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("UNIQUE_SYSTEM_IDENTIFIER"),'nan'),'NaN'),'NAN'),'')) AS "UNIQUE_SYSTEM_IDENTIFIER",
    "ULS_FILE_NUMBER",
    "EBF_TRANSACTION_ID",
    "CALL_SIGN",
    "LICENSE_STATUS",
    "RADIO_SERVICE_CODE",
    CASE WHEN TRIM("GRANT_DATE") LIKE '%-%' OR TRIM("GRANT_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("GRANT_DATE")) END AS "GRANT_DATE",
    CASE WHEN TRIM("EXPIRED_DATE") LIKE '%-%' OR TRIM("EXPIRED_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("EXPIRED_DATE")) END AS "EXPIRED_DATE",
    CASE WHEN TRIM("CANCELLATION_DATE") LIKE '%-%' OR TRIM("CANCELLATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CANCELLATION_DATE")) END AS "CANCELLATION_DATE",
    "ELIGIBILITY_RULE_NUM",
    "ENTITY_NAME",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FRN"),'nan'),'NaN'),'NAN'),'')) AS "FRN",
    "EIN",
    "ADDRESS_LINE1",
    "CITY",
    "STATE",
    "ZIP_CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PO_BOX"),'nan'),'NaN'),'NAN'),'')) AS "PO_BOX",
    "ATTENTION_LINE",
    "PHONE",
    "FAX",
    "EMAIL",
    "CONTACT_COMPANY",
    "APPLICANT_TYPE_CODE",
    "FCC_COUNTY_CODE",
    CASE WHEN TRIM("LAST_ACTION_DATE") LIKE '%-%' OR TRIM("LAST_ACTION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("LAST_ACTION_DATE")) END AS "LAST_ACTION_DATE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_FCC_LICENSING;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.FEDERAL_JUDGES COPY GRANTS COMMENT='The authoritative directory of all 4,067 federal judges (district, circuit, Supreme Court) from 1789 to today: name, demographics, birth/death, plus who nominated them, the appointing president''s party, ABA rating, and confirmation vote for up to six appointments each. The backbone dimension for the judiciary. Keyed on the FJC nid. Raw landing -- wide, text-as-loaded, one column set per appointment.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NID"),'nan'),'NaN'),'NAN'),'')) AS "NID",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("JID"),'nan'),'NaN'),'NAN'),'')) AS "JID",
    "LAST_NAME",
    "FIRST_NAME",
    "MIDDLE_NAME",
    "SUFFIX",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BIRTH_MONTH"),'nan'),'NaN'),'NAN'),'')) AS "BIRTH_MONTH",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BIRTH_DAY"),'nan'),'NaN'),'NAN'),'')) AS "BIRTH_DAY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BIRTH_YEAR"),'nan'),'NaN'),'NAN'),'')) AS "BIRTH_YEAR",
    "BIRTH_CITY",
    "BIRTH_STATE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEATH_MONTH"),'nan'),'NaN'),'NAN'),'')) AS "DEATH_MONTH",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEATH_DAY"),'nan'),'NaN'),'NAN'),'')) AS "DEATH_DAY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEATH_YEAR"),'nan'),'NaN'),'NAN'),'')) AS "DEATH_YEAR",
    "DEATH_CITY",
    "DEATH_STATE",
    "GENDER",
    "RACE_OR_ETHNICITY",
    "COURT_TYPE_1",
    "COURT_NAME_1",
    "APPOINTMENT_TITLE_1",
    "APPOINTING_PRESIDENT_1",
    "PARTY_OF_APPOINTING_PRESIDENT_1",
    "REAPPOINTING_PRESIDENT_1",
    "PARTY_OF_REAPPOINTING_PRESIDENT_1",
    "ABA_RATING_1",
    "SEAT_ID_1",
    "STATUTE_AUTHORIZING_NEW_SEAT_1",
    CASE WHEN TRIM("RECESS_APPOINTMENT_DATE_1") LIKE '%-%' OR TRIM("RECESS_APPOINTMENT_DATE_1") LIKE '%/%' THEN TRY_TO_DATE(TRIM("RECESS_APPOINTMENT_DATE_1")) END AS "RECESS_APPOINTMENT_DATE_1",
    CASE WHEN TRIM("NOMINATION_DATE_1") LIKE '%-%' OR TRIM("NOMINATION_DATE_1") LIKE '%/%' THEN TRY_TO_DATE(TRIM("NOMINATION_DATE_1")) END AS "NOMINATION_DATE_1",
    CASE WHEN TRIM("COMMITTEE_REFERRAL_DATE_1") LIKE '%-%' OR TRIM("COMMITTEE_REFERRAL_DATE_1") LIKE '%/%' THEN TRY_TO_DATE(TRIM("COMMITTEE_REFERRAL_DATE_1")) END AS "COMMITTEE_REFERRAL_DATE_1",
    CASE WHEN TRIM("HEARING_DATE_1") LIKE '%-%' OR TRIM("HEARING_DATE_1") LIKE '%/%' THEN TRY_TO_DATE(TRIM("HEARING_DATE_1")) END AS "HEARING_DATE_1",
    "JUDICIARY_COMMITTEE_ACTION_1",
    CASE WHEN TRIM("COMMITTEE_ACTION_DATE_1") LIKE '%-%' OR TRIM("COMMITTEE_ACTION_DATE_1") LIKE '%/%' THEN TRY_TO_DATE(TRIM("COMMITTEE_ACTION_DATE_1")) END AS "COMMITTEE_ACTION_DATE_1",
    "SENATE_VOTE_TYPE_1",
    "AYES_NAYS_1",
    CASE WHEN TRIM("CONFIRMATION_DATE_1") LIKE '%-%' OR TRIM("CONFIRMATION_DATE_1") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CONFIRMATION_DATE_1")) END AS "CONFIRMATION_DATE_1",
    CASE WHEN TRIM("COMMISSION_DATE_1") LIKE '%-%' OR TRIM("COMMISSION_DATE_1") LIKE '%/%' THEN TRY_TO_DATE(TRIM("COMMISSION_DATE_1")) END AS "COMMISSION_DATE_1",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SERVICE_AS_CHIEF_JUDGE_BEGIN_1"),'nan'),'NaN'),'NAN'),'')) AS "SERVICE_AS_CHIEF_JUDGE_BEGIN_1",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SERVICE_AS_CHIEF_JUDGE_END_1"),'nan'),'NaN'),'NAN'),'')) AS "SERVICE_AS_CHIEF_JUDGE_END_1",
    "C_2ND_SERVICE_AS_CHIEF_JUDGE_BEGIN_1",
    "C_2ND_SERVICE_AS_CHIEF_JUDGE_END_1",
    CASE WHEN TRIM("SENIOR_STATUS_DATE_1") LIKE '%-%' OR TRIM("SENIOR_STATUS_DATE_1") LIKE '%/%' THEN TRY_TO_DATE(TRIM("SENIOR_STATUS_DATE_1")) END AS "SENIOR_STATUS_DATE_1",
