    CASE WHEN TRIM("COMMITTEE_REFERRAL_DATE_2") LIKE '%-%' OR TRIM("COMMITTEE_REFERRAL_DATE_2") LIKE '%/%' THEN TRY_TO_DATE(TRIM("COMMITTEE_REFERRAL_DATE_2")) END AS "COMMITTEE_REFERRAL_DATE_2",
    CASE WHEN TRIM("HEARING_DATE_2") LIKE '%-%' OR TRIM("HEARING_DATE_2") LIKE '%/%' THEN TRY_TO_DATE(TRIM("HEARING_DATE_2")) END AS "HEARING_DATE_2",
