CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.FEDERAL_JUDGE_APPOINTMENTS COPY GRANTS COMMENT='One row per judgeship appointment for every Article III federal judge (4,766 rows): the court, the appointing president and their party, nomination and confirmation dates, the Senate Ayes/Nays, ABA rating, and when service ended. This is how you trace who put a judge on the bench and how contested it was. Keyed by the FJC judge NID. Raw text landing (Federal Judicial Center).' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NID"),'nan'),'NaN'),'NAN'),'')) AS "NID",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SEQUENCE"),'nan'),'NaN'),'NAN'),'')) AS "SEQUENCE",
    "JUDGE_NAME",
    "COURT_TYPE",
    "COURT_NAME",
    "APPOINTMENT_TITLE",
    "APPOINTING_PRESIDENT",
    "PARTY_OF_APPOINTING_PRESIDENT",
    "REAPPOINTING_PRESIDENT",
    "PARTY_OF_REAPPOINTING_PRESIDENT",
    "ABA_RATING",
    "SEAT_ID",
    "STATUTE_AUTHORIZING_NEW_SEAT",
    CASE WHEN TRIM("RECESS_APPOINTMENT_DATE") LIKE '%-%' OR TRIM("RECESS_APPOINTMENT_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("RECESS_APPOINTMENT_DATE")) END AS "RECESS_APPOINTMENT_DATE",
    CASE WHEN TRIM("NOMINATION_DATE") LIKE '%-%' OR TRIM("NOMINATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("NOMINATION_DATE")) END AS "NOMINATION_DATE",
    CASE WHEN TRIM("COMMITTEE_REFERRAL_DATE") LIKE '%-%' OR TRIM("COMMITTEE_REFERRAL_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("COMMITTEE_REFERRAL_DATE")) END AS "COMMITTEE_REFERRAL_DATE",
    CASE WHEN TRIM("HEARING_DATE") LIKE '%-%' OR TRIM("HEARING_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("HEARING_DATE")) END AS "HEARING_DATE",
    "JUDICIARY_COMMITTEE_ACTION",
    CASE WHEN TRIM("COMMITTEE_ACTION_DATE") LIKE '%-%' OR TRIM("COMMITTEE_ACTION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("COMMITTEE_ACTION_DATE")) END AS "COMMITTEE_ACTION_DATE",
    "SENATE_VOTE_TYPE",
    "AYES_NAYS",
    CASE WHEN TRIM("CONFIRMATION_DATE") LIKE '%-%' OR TRIM("CONFIRMATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CONFIRMATION_DATE")) END AS "CONFIRMATION_DATE",
    CASE WHEN TRIM("COMMISSION_DATE") LIKE '%-%' OR TRIM("COMMISSION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("COMMISSION_DATE")) END AS "COMMISSION_DATE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SERVICE_AS_CHIEF_JUDGE_BEGIN"),'nan'),'NaN'),'NAN'),'')) AS "SERVICE_AS_CHIEF_JUDGE_BEGIN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SERVICE_AS_CHIEF_JUDGE_END"),'nan'),'NaN'),'NAN'),'')) AS "SERVICE_AS_CHIEF_JUDGE_END",
    "C_2ND_SERVICE_AS_CHIEF_JUDGE_BEGIN",
    "C_2ND_SERVICE_AS_CHIEF_JUDGE_END",
    CASE WHEN TRIM("SENIOR_STATUS_DATE") LIKE '%-%' OR TRIM("SENIOR_STATUS_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("SENIOR_STATUS_DATE")) END AS "SENIOR_STATUS_DATE",
    "TERMINATION",
    CASE WHEN TRIM("TERMINATION_DATE") LIKE '%-%' OR TRIM("TERMINATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("TERMINATION_DATE")) END AS "TERMINATION_DATE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_FJC_SERVICE;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.INSTITUTION_IDEOLOGY_MEDIANS COPY GRANTS COMMENT='The academic ''where does the median voter sit'' series, one row per year (102 total) on a single common scale so you can compare the Supreme Court to Congress to the White House on the same yardstick. Circuit medians plus standard deviations for all 13 appeals circuits show how liberal or conservative each bench leans over time. Raw landing table (Judicial Common Space, Wash U. St. Louis) -- every value stored as text, cast before you do math.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("UNNAMED_0"),'nan'),'NaN'),'NAN'),'')) AS "UNNAMED_0",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    "TERM",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CONGRESS"),'nan'),'NaN'),'NAN'),'')) AS "CONGRESS",
    "PRESIDENT",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HOUSE_MEDIAN"),'nan'),'NaN'),'NAN'),'')) AS "HOUSE_MEDIAN",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SENATE_MEDIAN"),'nan'),'NaN'),'NAN'),'')) AS "SENATE_MEDIAN",
    "SC_MEDIAN",
    "CIRCUIT_MEDIAN1",
    "CIRCUIT_SD1",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CIRCUIT_MEDIAN2"),'nan'),'NaN'),'NAN'),'')) AS "CIRCUIT_MEDIAN2",
    "CIRCUIT_SD2",
    "CIRCUIT_MEDIAN3",
    "CIRCUIT_SD3",
    "CIRCUIT_MEDIAN4",
    "CIRCUIT_SD4",
    "CIRCUIT_MEDIAN5",
    "CIRCUIT_SD5",
    "CIRCUIT_MEDIAN6",
    "CIRCUIT_SD6",
    "CIRCUIT_MEDIAN7",
    "CIRCUIT_SD7",
    "CIRCUIT_MEDIAN8",
    "CIRCUIT_SD8",
    "CIRCUIT_MEDIAN9",
    "CIRCUIT_SD9",
    "CIRCUIT_MEDIAN10",
    "CIRCUIT_SD10",
    "CIRCUIT_MEDIAN11",
    "CIRCUIT_SD11",
    "CIRCUIT_MEDIAN12",
    "CIRCUIT_SD12",
    "CIRCUIT_MEDIAN13",
    "CIRCUIT_SD13",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_JCS_MEDIANS;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.MILITARY_SPENDING_BY_COUNTRY COPY GRANTS COMMENT='Annual military spending for every country in constant US dollars, sourced from SIPRI via Our World in Data. Carries ISO-3 country codes, so it joins to any country-keyed source in the Library -- built for comparing spending trajectories (China vs US vs Taiwan, etc). Heads up: some rows are regional aggregates (tagged ''(SIPRI)'') that you filter out for country-level work, and only this one metric (constant USD) is here -- %GDP and per-capita live in sibling tables. Raw as loaded (every value stored as text).' AS
SELECT
    "ENTITY",
    "CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MILITARY_EXPENDITURE"),'nan'),'NaN'),'NAN'),'')) AS "MILITARY_EXPENDITURE",
    "WORLD_REGION_ACCORDING_TO_OWID",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_OWID_MILSPEND;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.STATE_CANNABIS_LAWS COPY GRANTS COMMENT='A deep coding of U.S. state marijuana policy by state and year: whether medical and recreational use were approved and implemented, how it happened (ballot measure, legislature, court), plus dozens of fine-grained rules -- home growing, dispensary limits, taxes, testing, possession penalties, caregiver rules. Distinguishes ''approved'' from ''implemented'' throughout, so you can see the gap between passing a law and enforcing it. Keyed by state and FIPS. Raw landing table: values stored as text (including some scored/z-scored policy indices), and note a couple of unlabeled COL_* placeholder columns from the source.' AS
SELECT
    "STATE",
    "STATE_AB",
    "FIPS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MML_APPROVED"),'nan'),'NaN'),'NAN'),'')) AS "MML_APPROVED",
