    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BM_PASSED"),'nan'),'NaN'),'NAN'),'')) AS "BM_PASSED",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LEGISLATIVE_ACTION"),'nan'),'NaN'),'NAN'),'')) AS "LEGISLATIVE_ACTION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("STATE_COURT_SIG_ACTION"),'nan'),'NaN'),'NAN'),'')) AS "STATE_COURT_SIG_ACTION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REC_CANN_APPROVED"),'nan'),'NaN'),'NAN'),'')) AS "REC_CANN_APPROVED",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PHARMAPP"),'nan'),'NaN'),'NAN'),'')) AS "PHARMAPP",
