    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PERMISSIVEIMP"),'nan'),'NaN'),'NAN'),'')) AS "PERMISSIVEIMP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FISCALAPP"),'nan'),'NaN'),'NAN'),'')) AS "FISCALAPP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FISCALIMP"),'nan'),'NaN'),'NAN'),'')) AS "FISCALIMP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PHARMAPPSCALE"),'nan'),'NaN'),'NAN'),'')) AS "PHARMAPPSCALE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PHARMIMPSCALE"),'nan'),'NaN'),'NAN'),'')) AS "PHARMIMPSCALE",
