    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HIGH_PLANT_RCL_IMP"),'nan'),'NaN'),'NAN'),'')) AS "HIGH_PLANT_RCL_IMP",
