    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("POSSESSION_NO_JAIL_NO_FELON_IMP"),'nan'),'NaN'),'NAN'),'')) AS "POSSESSION_NO_JAIL_NO_FELON_IMP",
    "COL_78",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DISP_APP"),'nan'),'NaN'),'NAN'),'')) AS "DISP_APP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DISP_IMP"),'nan'),'NaN'),'NAN'),'')) AS "DISP_IMP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DISP_FEE_HIGH_APP"),'nan'),'NaN'),'NAN'),'')) AS "DISP_FEE_HIGH_APP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DISP_FEE_HIGH_IMP"),'nan'),'NaN'),'NAN'),'')) AS "DISP_FEE_HIGH_IMP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NO_DISP_LIMIT_MML_APP"),'nan'),'NaN'),'NAN'),'')) AS "NO_DISP_LIMIT_MML_APP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NO_DISP_LIMIT_MML_IMP"),'nan'),'NaN'),'NAN'),'')) AS "NO_DISP_LIMIT_MML_IMP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COMMERCIAL_MML_DISP_APP"),'nan'),'NaN'),'NAN'),'')) AS "COMMERCIAL_MML_DISP_APP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COMMERCIAL_MML_DISP_IMP"),'nan'),'NaN'),'NAN'),'')) AS "COMMERCIAL_MML_DISP_IMP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GROW_FEE_HIGH_APP"),'nan'),'NaN'),'NAN'),'')) AS "GROW_FEE_HIGH_APP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GROW_FEE_HIGH_IMP"),'nan'),'NaN'),'NAN'),'')) AS "GROW_FEE_HIGH_IMP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MML_TAX_APP"),'nan'),'NaN'),'NAN'),'')) AS "MML_TAX_APP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MML_TAX_IMP"),'nan'),'NaN'),'NAN'),'')) AS "MML_TAX_IMP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HI_MML_TAX_APP"),'nan'),'NaN'),'NAN'),'')) AS "HI_MML_TAX_APP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HI_MML_TAX_IMP"),'nan'),'NaN'),'NAN'),'')) AS "HI_MML_TAX_IMP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OTHER_STATES_MML_APP"),'nan'),'NaN'),'NAN'),'')) AS "OTHER_STATES_MML_APP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OTHER_STATES_MML_IMP"),'nan'),'NaN'),'NAN'),'')) AS "OTHER_STATES_MML_IMP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REC_CANN_DISP_APP"),'nan'),'NaN'),'NAN'),'')) AS "REC_CANN_DISP_APP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REC_CANN_DISP_IMP"),'nan'),'NaN'),'NAN'),'')) AS "REC_CANN_DISP_IMP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WHOLESALE_TAX_HIGH_RCL_APP"),'nan'),'NaN'),'NAN'),'')) AS "WHOLESALE_TAX_HIGH_RCL_APP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WHOLESALE_TAX_HIGH_RCL_IMP"),'nan'),'NaN'),'NAN'),'')) AS "WHOLESALE_TAX_HIGH_RCL_IMP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RETAIL_TAX_RCL_HIGH_APP"),'nan'),'NaN'),'NAN'),'')) AS "RETAIL_TAX_RCL_HIGH_APP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RETAIL_TAX_RCL_HIGH_IMP"),'nan'),'NaN'),'NAN'),'')) AS "RETAIL_TAX_RCL_HIGH_IMP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("STATE_SALES_TAX_HIGH_RCL_APP"),'nan'),'NaN'),'NAN'),'')) AS "STATE_SALES_TAX_HIGH_RCL_APP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("STATE_SALES_TAX_HIGH_RCL_IMP"),'nan'),'NaN'),'NAN'),'')) AS "STATE_SALES_TAX_HIGH_RCL_IMP",
