FROM LIBRARY_RAW.LANDING.ST_CANNABIS_POLICY_BUNDLES;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.SUPREME_COURT_JUSTICE_IDEOLOGY COPY GRANTS COMMENT='The Judicial Common Space (JCS) ideology score for each Supreme Court justice, on the same DW-NOMINATE scale as Congress, one row per (justice, term) from 1937 to 2022. Tracks how a justice''s placement -- and the Court''s overall tilt -- shifted over time. 782 rows. Raw landing, stored as text; match to justices by name.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("UNNAMED_0"),'nan'),'NaN'),'NAN'),'')) AS "UNNAMED_0",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TERM"),'nan'),'NaN'),'NAN'),'')) AS "TERM",
    "JUSTICENAME",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("JCS"),'nan'),'NaN'),'NAN'),'')) AS "JCS",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_JCS_SCOTUS;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT.UN_VOTE_AGREEMENT_PAIRS COPY GRANTS COMMENT='For each pair of countries and year, how closely they voted together at the UN General Assembly, plus each side''s ''ideal point'' (where it sits on a global alignment scale). The standard academic measure of who''s diplomatically in whose camp. Raw as loaded (all text); countries identified by ccode, no standard join key. Voeten data via Harvard Dataverse.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COL_0"),'nan'),'NaN'),'NAN'),'')) AS "COL_0",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SESSION_X"),'nan'),'NaN'),'NAN'),'')) AS "SESSION_X",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CCODE1"),'nan'),'NaN'),'NAN'),'')) AS "CCODE1",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CCODE2"),'nan'),'NaN'),'NAN'),'')) AS "CCODE2",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("AGREE"),'nan'),'NaN'),'NAN'),'')) AS "AGREE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("IDEALPOINTFP_X"),'nan'),'NaN'),'NAN'),'')) AS "IDEALPOINTFP_X",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NVOTESFP_X"),'nan'),'NaN'),'NAN'),'')) AS "NVOTESFP_X",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("IDEALPOINTFP_Y"),'nan'),'NaN'),'NAN'),'')) AS "IDEALPOINTFP_Y",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NVOTESFP_Y"),'nan'),'NaN'),'NAN'),'')) AS "NVOTESFP_Y",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("IDEALPOINTDISTANCE"),'nan'),'NaN'),'NAN'),'')) AS "IDEALPOINTDISTANCE",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_VOETEN_UNGA_VOTES;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT_SPENDING.FEDERAL_AGENCY_BUDGETS COPY GRANTS COMMENT='Every top-tier federal agency from USAspending.gov with current fiscal-year budget authority, dollars obligated, dollars actually paid out (outlays), and each agency''s share of the total federal budget. Only 111 rows -- the high-level scoreboard of who controls what money. Joins to detailed spending by agency name. Raw landing, all text.' AS
SELECT
    "AGENCY_ID",
    "TOPTIER_CODE",
    "ABBREVIATION",
    "AGENCY_NAME",
    "CONGRESSIONAL_JUSTIFICATION_URL",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTIVE_FY"),'nan'),'NaN'),'NAN'),'')) AS "ACTIVE_FY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTIVE_FQ"),'nan'),'NaN'),'NAN'),'')) AS "ACTIVE_FQ",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OUTLAY_AMOUNT"),'nan'),'NaN'),'NAN'),'')) AS "OUTLAY_AMOUNT",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OBLIGATED_AMOUNT"),'nan'),'NaN'),'NAN'),'')) AS "OBLIGATED_AMOUNT",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BUDGET_AUTHORITY_AMOUNT"),'nan'),'NaN'),'NAN'),'')) AS "BUDGET_AUTHORITY_AMOUNT",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CURRENT_TOTAL_BUDGET_AUTHORITY_AMOUNT"),'nan'),'NaN'),'NAN'),'')) AS "CURRENT_TOTAL_BUDGET_AUTHORITY_AMOUNT",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PERCENTAGE_OF_TOTAL_BUDGET_AUTHORITY"),'nan'),'NaN'),'NAN'),'')) AS "PERCENTAGE_OF_TOTAL_BUDGET_AUTHORITY",
    "AGENCY_SLUG",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_USASPENDING_TOPTIER_AGENCIES;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT_SPENDING.FEDERAL_AWARD_SPENDING COPY GRANTS COMMENT='Award-level federal spending from the USAspending REST API: recipient (with UEI/DUNS/EIN), awarding agency, award type, and obligated vs. outlaid dollars. Only a 300-row probe has landed -- the full firehose is enormous and comes later. Recipient IDs make this joinable to contractors, nonprofits, and sanctions lists.' AS
SELECT
    "AWARD_ID",
    "GENERATED_UNIQUE_AWARD_ID",
    "RECIPIENT_NAME",
    "RECIPIENT_UEI",
    "RECIPIENT_DUNS",
    "RECIPIENT_EIN",
    "AWARDING_AGENCY_NAME",
    "AWARDING_AGENCY_CODE",
    "FUNDING_AGENCY_NAME",
    "AWARD_TYPE",
    "TOTAL_OBLIGATION",
    "TOTAL_OUTLAY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("AWARD_AMOUNT"),'nan'),'NaN'),'NAN'),'')) AS "AWARD_AMOUNT",
    CASE WHEN TRIM("START_DATE") LIKE '%-%' OR TRIM("START_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("START_DATE")) END AS "START_DATE",
    CASE WHEN TRIM("END_DATE") LIKE '%-%' OR TRIM("END_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("END_DATE")) END AS "END_DATE",
    CASE WHEN TRIM("LAST_MODIFIED_DATE") LIKE '%-%' OR TRIM("LAST_MODIFIED_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("LAST_MODIFIED_DATE")) END AS "LAST_MODIFIED_DATE",
    "FISCAL_YEAR",
    "NAICS_CODE",
    "NAICS_DESCRIPTION",
    "CFDA_NUMBER",
    "CFDA_TITLE",
    "PLACE_OF_PERFORMANCE_STATE",
    "PLACE_OF_PERFORMANCE_FIPS",
    "PLACE_OF_PERFORMANCE_CITY",
    "RECIPIENT_LOCATION_STATE",
    "RECIPIENT_LOCATION_FIPS",
    "FEDERAL_ACCOUNT_CODE",
    "TREASURY_ACCOUNT_SYMBOL",
    "DEF_CODE",
    "TRANSACTION_COUNT",
    "SUBAWARD_COUNT",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_US_USASPENDING_API;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT_SPENDING.FEDERAL_CONTRACTS COPY GRANTS COMMENT='6.3 million federal prime contract transactions (Oct 2024-Sep 2025): the awarding agency, the company (with UEI/DUNS/CAGE IDs and parent company), dollar amounts, work description, industry code, and even top-officer pay. The core follow-the-money table for government spending, keyed by UEI/DUNS/NAICS/FIPS so it joins to companies and places. Raw landing table, values stored as text.' AS
SELECT
    "CONTRACT_AWARD_UNIQUE_KEY",
    "AWARD_ID_PIID",
    CASE WHEN TRIM("ACTION_DATE") LIKE '%-%' OR TRIM("ACTION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("ACTION_DATE")) END AS "ACTION_DATE",
    CASE WHEN TRIM("PERIOD_OF_PERFORMANCE_START_DATE") LIKE '%-%' OR TRIM("PERIOD_OF_PERFORMANCE_START_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("PERIOD_OF_PERFORMANCE_START_DATE")) END AS "PERIOD_OF_PERFORMANCE_START_DATE",
    CASE WHEN TRIM("PERIOD_OF_PERFORMANCE_CURRENT_END_DATE") LIKE '%-%' OR TRIM("PERIOD_OF_PERFORMANCE_CURRENT_END_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("PERIOD_OF_PERFORMANCE_CURRENT_END_DATE")) END AS "PERIOD_OF_PERFORMANCE_CURRENT_END_DATE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FEDERAL_ACTION_OBLIGATION"),'nan'),'NaN'),'NAN'),'')) AS "FEDERAL_ACTION_OBLIGATION",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_DOLLARS_OBLIGATED"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_DOLLARS_OBLIGATED",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CURRENT_TOTAL_VALUE_OF_AWARD"),'nan'),'NaN'),'NAN'),'')) AS "CURRENT_TOTAL_VALUE_OF_AWARD",
    "AWARDING_AGENCY_NAME",
    "AWARDING_SUB_AGENCY_NAME",
    "FUNDING_AGENCY_NAME",
    "RECIPIENT_UEI",
    "RECIPIENT_DUNS",
    "CAGE_CODE",
    "RECIPIENT_NAME",
    "RECIPIENT_DOING_BUSINESS_AS_NAME",
    "RECIPIENT_PARENT_UEI",
    "RECIPIENT_PARENT_NAME",
    "RECIPIENT_CITY_NAME",
    "RECIPIENT_STATE_CODE",
    "RECIPIENT_ZIP_4_CODE",
    "RECIPIENT_COUNTRY_NAME",
    "PRIMARY_PLACE_OF_PERFORMANCE_STATE_CODE",
    "PRIMARY_PLACE_OF_PERFORMANCE_CITY_NAME",
    "AWARD_TYPE",
    "NAICS_CODE",
    "NAICS_DESCRIPTION",
    "PRODUCT_OR_SERVICE_CODE_DESCRIPTION",
    "TRANSACTION_DESCRIPTION",
    "HIGHLY_COMPENSATED_OFFICER_1_NAME",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HIGHLY_COMPENSATED_OFFICER_1_AMOUNT"),'nan'),'NaN'),'NAN'),'')) AS "HIGHLY_COMPENSATED_OFFICER_1_AMOUNT",
    "HIGHLY_COMPENSATED_OFFICER_2_NAME",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HIGHLY_COMPENSATED_OFFICER_2_AMOUNT"),'nan'),'NaN'),'NAN'),'')) AS "HIGHLY_COMPENSATED_OFFICER_2_AMOUNT",
    "FOREIGN_OWNED",
    "USASPENDING_PERMALINK",
    CASE WHEN TRIM("LAST_MODIFIED_DATE") LIKE '%-%' OR TRIM("LAST_MODIFIED_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("LAST_MODIFIED_DATE")) END AS "LAST_MODIFIED_DATE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_USASPENDING_CONTRACTS;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT_SPENDING.FOREIGN_AID_TRANSACTIONS COPY GRANTS COMMENT='Every disbursement and obligation of US foreign assistance from ForeignAssistance.gov -- 4 million transactions with country, managing agency, sector, and dollar amounts by fiscal year. This is the ledger of where American aid money actually went.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COUNTRY"),'nan'),'NaN'),'NAN'),'')) AS "COUNTRY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MANAGING_AGENCY"),'nan'),'NaN'),'NAN'),'')) AS "MANAGING_AGENCY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FUNDING_AGENCY"),'nan'),'NaN'),'NAN'),'')) AS "FUNDING_AGENCY",
    "USG_SECTOR",
    "DAC_CATEGORY",
    "OBLIGATION_AMOUNT",
    "DISBURSEMENT_AMOUNT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FISCAL_YEAR"),'nan'),'NaN'),'NAN'),'')) AS "FISCAL_YEAR",
    "EIN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TRANSACTION_TYPE"),'nan'),'NaN'),'NAN'),'')) AS "TRANSACTION_TYPE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_FOREIGNASSISTANCE;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT_SPENDING.GRANT_OPPORTUNITIES COPY GRANTS COMMENT='Grant opportunity listings pulled from the Grants.gov search API: which agency is offering money, for what category, who''s eligible, and whether it''s still open. Only a 100-row probe has landed so far -- treat it as a working sample of the feed, not the full universe of open grants.' AS
SELECT
    "OPPORTUNITY_ID",
    "OPPORTUNITY_NUMBER",
    "OPPORTUNITY_TITLE",
    "AGENCY_CODE",
    "AGENCY_NAME",
    "OPPORTUNITY_STATUS",
    "OPPORTUNITY_CATEGORY",
    "FUNDING_INSTRUMENT_TYPE",
    "CATEGORY_OF_FUNDING_ACTIVITY",
    "CFDA_NUMBERS",
    "ELIGIBLE_APPLICANTS",
    "AWARD_CEILING",
    "AWARD_FLOOR",
    "ESTIMATED_TOTAL_PROGRAM_FUNDING",
    "EXPECTED_NUMBER_OF_AWARDS",
    CASE WHEN TRIM("POSTED_DATE") LIKE '%-%' OR TRIM("POSTED_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("POSTED_DATE")) END AS "POSTED_DATE",
    CASE WHEN TRIM("CLOSE_DATE") LIKE '%-%' OR TRIM("CLOSE_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CLOSE_DATE")) END AS "CLOSE_DATE",
    "LAST_UPDATED_DATE",
    "ARCHIVE_DATE",
    "SYNOPSIS_DESC",
    "GRANTOR_CONTACT_EMAIL",
    "GRANTOR_CONTACT_NAME",
    "VERSION",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_GRANTS_GOV;

CREATE OR REPLACE VIEW THE_LIBRARY.GOVERNMENT_SPENDING.SBA_SMALL_BUSINESS_LOANS COPY GRANTS COMMENT='Loan-level records for the SBA''s two big small-business programs, FOIA-released and updated quarterly: who borrowed, where they are, who lent, and how much. Borrower names and addresses make this a strong name/place-match table for tracing businesses.' AS
SELECT
    CASE WHEN TRIM("ASOFDATE") LIKE '%-%' OR TRIM("ASOFDATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("ASOFDATE")) END AS "ASOFDATE",
    "PROGRAM",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LOCATIONID"),'nan'),'NaN'),'NAN'),'')) AS "LOCATIONID",
    "BORRNAME",
    "BORRSTREET",
    "BORRCITY",
    "BORRSTATE",
    "BORRZIP",
    "CDC_NAME",
    "CDC_STREET",
    "CDC_CITY",
    "CDC_STATE",
    "CDC_ZIP",
    "THIRDPARTYLENDER_NAME",
    "THIRDPARTYLENDER_CITY",
    "THIRDPARTYLENDER_STATE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("THIRDPARTYDOLLARS"),'nan'),'NaN'),'NAN'),'')) AS "THIRDPARTYDOLLARS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GROSSAPPROVAL"),'nan'),'NaN'),'NAN'),'')) AS "GROSSAPPROVAL",
    CASE WHEN TRIM("APPROVALDATE") LIKE '%-%' OR TRIM("APPROVALDATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("APPROVALDATE")) END AS "APPROVALDATE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("APPROVALFY"),'nan'),'NaN'),'NAN'),'')) AS "APPROVALFY",
    CASE WHEN TRIM("FIRSTDISBURSEMENTDATE") LIKE '%-%' OR TRIM("FIRSTDISBURSEMENTDATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("FIRSTDISBURSEMENTDATE")) END AS "FIRSTDISBURSEMENTDATE",
    "PROCESSINGMETHOD",
    "SUBPROGRAM",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TERMINMONTHS"),'nan'),'NaN'),'NAN'),'')) AS "TERMINMONTHS",
    "NAICSCODE",
    "NAICSDESCRIPTION",
    "FRANCHISECODE",
    "FRANCHISENAME",
    "PROJECTCOUNTY",
    "PROJECTSTATE",
    "SBADISTRICTOFFICE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CONGRESSIONALDISTRICT"),'nan'),'NaN'),'NAN'),'')) AS "CONGRESSIONALDISTRICT",
    "BUSINESSTYPE",
    "BUSINESSAGE",
    "LOANSTATUS",
    CASE WHEN TRIM("PAIDINFULLDATE") LIKE '%-%' OR TRIM("PAIDINFULLDATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("PAIDINFULLDATE")) END AS "PAIDINFULLDATE",
    CASE WHEN TRIM("CHARGEOFFDATE") LIKE '%-%' OR TRIM("CHARGEOFFDATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CHARGEOFFDATE")) END AS "CHARGEOFFDATE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GROSSCHARGEOFFAMOUNT"),'nan'),'NaN'),'NAN'),'')) AS "GROSSCHARGEOFFAMOUNT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("JOBSSUPPORTED"),'nan'),'NaN'),'NAN'),'')) AS "JOBSSUPPORTED",
    "COLLATERALIND",
    "BANKNAME",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BANKFDICNUMBER"),'nan'),'NaN'),'NAN'),'')) AS "BANKFDICNUMBER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BANKNCUANUMBER"),'nan'),'NaN'),'NAN'),'')) AS "BANKNCUANUMBER",
    "BANKSTREET",
    "BANKCITY",
    "BANKSTATE",
    "BANKZIP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SBAGUARANTEEDAPPROVAL"),'nan'),'NaN'),'NAN'),'')) AS "SBAGUARANTEEDAPPROVAL",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("INITIALINTERESTRATE"),'nan'),'NaN'),'NAN'),'')) AS "INITIALINTERESTRATE",
    "FIXEDORVARIABLEINTERESTIND",
    "REVOLVERSTATUS",
    "SOLDSECMRKTIND",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_SBA_LOANS;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.ANXIETY_DEPRESSION_RATES COPY GRANTS COMMENT='CDC''s Household Pulse tracker of mental-health symptoms: the estimated share of adults reporting anxiety or depression, broken out by state and by subgroup (age, race, gender, etc.) across survey periods since 2020. Includes confidence intervals so you can judge how solid each estimate is. Raw landing table -- every value stored as text, and these are survey-based estimates with margins of error, not exact counts. Cast VALUE before charting trends.' AS
SELECT
    "INDICATOR",
    "C_GROUP",
    "STATE",
    "SUBGROUP",
    "PHASE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TIME_PERIOD"),'nan'),'NaN'),'NAN'),'')) AS "TIME_PERIOD",
    "TIME_PERIOD_LABEL",
    CASE WHEN TRIM("TIME_PERIOD_START_DATE") LIKE '%-%' OR TRIM("TIME_PERIOD_START_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("TIME_PERIOD_START_DATE")) END AS "TIME_PERIOD_START_DATE",
    CASE WHEN TRIM("TIME_PERIOD_END_DATE") LIKE '%-%' OR TRIM("TIME_PERIOD_END_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("TIME_PERIOD_END_DATE")) END AS "TIME_PERIOD_END_DATE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("VALUE"),'nan'),'NaN'),'NAN'),'')) AS "VALUE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LOWCI"),'nan'),'NaN'),'NAN'),'')) AS "LOWCI",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HIGHCI"),'nan'),'NaN'),'NAN'),'')) AS "HIGHCI",
    "CONFIDENCE_INTERVAL",
    "QUARTILE_RANGE",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CDC_ANXIETY_DEPRESSION;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.BANNED_HEALTHCARE_PROVIDERS COPY GRANTS COMMENT='Every individual and entity currently excluded from Medicare, Medicaid and other federal health programs (83,464 rows), with the exclusion type and the date it started. Cross it with who''s still getting paid and you find money going where it shouldn''t. Keyed by NPI plus name/address/EIN, so it joins straight to the provider and payment tables. Raw landing (HHS Office of Inspector General) -- values stored as text.' AS
SELECT
    "LASTNAME",
    "FIRSTNAME",
    "MIDNAME",
    "BUSNAME",
    "GENERAL",
    "SPECIALTY",
    "UPIN",
    "NPI",
    "DOB",
    "ADDRESS",
    "CITY",
    "STATE",
    "ZIP",
    "EXCLTYPE",
    TRY_TO_DATE(TRIM("EXCLDATE"),'YYYYMMDD') AS "EXCLDATE",
    "REINDATE",
    "WAIVERDATE",
    "WVRSTATE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_HHS_OIG_LEIE;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.CDC_HEALTH_INDICATORS COPY GRANTS COMMENT='Indicator-level records pulled from data.cdc.gov spanning vaccinations, chronic disease, outbreaks, and environmental health: indicator, state/FIPS/ZIP, year, and value. A broad sampler of CDC''s portal rather than one deep dataset -- good for quick health context by place.' AS
SELECT
    "DATASET_ID",
    "INDICATOR",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    "STATE",
    "FIPS",
    "ZIP_CODE",
    "VALUE",
    "UNIT",
    "DATA_VALUE_TYPE",
    "TOPIC",
    "CATEGORY",
    "SOURCE",
    "UPDATED_AT",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CDC_DATA_PORTAL;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.DIALYSIS_FACILITIES COPY GRANTS COMMENT='All 7,557 Medicare-certified dialysis facilities from CMS Care Compare -- location, ownership (for-profit vs non-profit, and the chain that owns it), star rating, and outcome measures like patient mortality, hospitalization, infection, and transfusion rates. Keyed by CCN, so it joins to other CMS provider data. Great for asking whether for-profit or chain-owned centers have worse patient outcomes. Raw landing, all text.' AS
SELECT
    "CCN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NETWORK"),'nan'),'NaN'),'NAN'),'')) AS "NETWORK",
    "FACILITY_NAME",
    "FIVE_STAR_DATE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FIVE_STAR"),'nan'),'NaN'),'NAN'),'')) AS "FIVE_STAR",
    "FIVE_STAR_DATA_AVAILABILITY_CODE",
    "ADDRESS_LINE_1",
    "ADDRESS_LINE_2",
    "CITY_TOWN",
    "STATE",
    "ZIP_CODE",
    "COUNTY_PARISH",
    "TELEPHONE_NUMBER",
    "PROFIT_OR_NON_PROFIT",
    "CHAIN_OWNED",
    "CHAIN_ORGANIZATION",
    "LATE_SHIFT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OF_DIALYSIS_STATIONS"),'nan'),'NaN'),'NAN'),'')) AS "OF_DIALYSIS_STATIONS",
    "OFFERS_IN_CENTER_HEMODIALYSIS",
    "OFFERS_PERITONEAL_DIALYSIS",
    "OFFERS_HOME_HEMODIALYSIS_TRAINING",
    CASE WHEN TRIM("CERTIFICATION_DATE") LIKE '%-%' OR TRIM("CERTIFICATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CERTIFICATION_DATE")) END AS "CERTIFICATION_DATE",
    "CLAIMS_DATE",
    "EQRS_DATE",
    "SMR_DATE",
    "PATIENT_SURVIVAL_CATEGORY_TEXT",
    "PATIENT_SURVIVAL_DATA_AVAILABILITY_CODE",
