    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MORTALITY_RATE_FACILITY"),'nan'),'NaN'),'NAN'),'')) AS "MORTALITY_RATE_FACILITY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MORTALITY_RATE_UPPER_CONFIDENCE_LIMIT_97_5"),'nan'),'NaN'),'NAN'),'')) AS "MORTALITY_RATE_UPPER_CONFIDENCE_LIMIT_97_5",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MORTALITY_RATE_LOWER_CONFIDENCE_LIMIT_2_5"),'nan'),'NaN'),'NAN'),'')) AS "MORTALITY_RATE_LOWER_CONFIDENCE_LIMIT_2_5",
