    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HOSPITALIZATION_RATE_UPPER_CONFIDENCE_LIMIT_97_5"),'nan'),'NaN'),'NAN'),'')) AS "HOSPITALIZATION_RATE_UPPER_CONFIDENCE_LIMIT_97_5",
