    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NUMBER_OF_PATIENTS_IN_LONG_TERM_CATHETER_SUMMARY"),'nan'),'NaN'),'NAN'),'')) AS "NUMBER_OF_PATIENTS_IN_LONG_TERM_CATHETER_SUMMARY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NUMBER_OF_PATIENT_MONTHS_IN_LONG_TERM_CATHETER_SUMMARY"),'nan'),'NaN'),'NAN'),'')) AS "NUMBER_OF_PATIENT_MONTHS_IN_LONG_TERM_CATHETER_SUMMARY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PERCENTAGE_OF_ADULT_PATIENTS_WITH_LONG_TERM_CATHETER_IN_USE"),'nan'),'NaN'),'NAN'),'')) AS "PERCENTAGE_OF_ADULT_PATIENTS_WITH_LONG_TERM_CATHETER_IN_USE",
    "NPCR_DATA_AVAILABILITY_CODE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NUMBER_OF_PATIENTS_IN_NPCR_SUMMARY"),'nan'),'NaN'),'NAN'),'')) AS "NUMBER_OF_PATIENTS_IN_NPCR_SUMMARY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NUMBER_OF_PATIENT_MONTHS_IN_NPCR_SUMMARY"),'nan'),'NaN'),'NAN'),'')) AS "NUMBER_OF_PATIENT_MONTHS_IN_NPCR_SUMMARY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PERCENTAGE_OF_PEDIATRIC_HD_PATIENTS_WITH_NPCR"),'nan'),'NaN'),'NAN'),'')) AS "PERCENTAGE_OF_PEDIATRIC_HD_PATIENTS_WITH_NPCR",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CMS_DIALYSIS;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.DRUG_ACQUISITION_COSTS COPY GRANTS COMMENT='The real acquisition cost of drugs (CMS NADAC): what pharmacies actually pay per unit for each drug, identified by NDC, with the drug description, pricing unit, brand/generic flag, and the matching generic''s cost. 1.5M rows. Cross it against what Medicare/Medicaid reimburse and you find the markup -- where the overpayment story lives. NDC is the steel join key to FDA drug data, Part D, and RxNorm. Raw landing table: every value stored as text, so cast prices and dates before comparing.' AS
SELECT
    "NDC_DESCRIPTION",
    "NDC",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NADAC_PER_UNIT"),'nan'),'NaN'),'NAN'),'')) AS "NADAC_PER_UNIT",
    CASE WHEN TRIM("EFFECTIVE_DATE") LIKE '%-%' OR TRIM("EFFECTIVE_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("EFFECTIVE_DATE")) END AS "EFFECTIVE_DATE",
    "PRICING_UNIT",
    "PHARMACY_TYPE_INDICATOR",
    "OTC",
    "EXPLANATION_CODE",
    "CLASSIFICATION_FOR_RATE_SETTING",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CORRESPONDING_GENERIC_DRUG_NADAC_PER_UNIT"),'nan'),'NaN'),'NAN'),'')) AS "CORRESPONDING_GENERIC_DRUG_NADAC_PER_UNIT",
    CASE WHEN TRIM("CORRESPONDING_GENERIC_DRUG_EFFECTIVE_DATE") LIKE '%-%' OR TRIM("CORRESPONDING_GENERIC_DRUG_EFFECTIVE_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CORRESPONDING_GENERIC_DRUG_EFFECTIVE_DATE")) END AS "CORRESPONDING_GENERIC_DRUG_EFFECTIVE_DATE",
    CASE WHEN TRIM("AS_OF_DATE") LIKE '%-%' OR TRIM("AS_OF_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("AS_OF_DATE")) END AS "AS_OF_DATE",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CMS_NADAC;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.DRUG_OVERDOSE_DEATHS COPY GRANTS COMMENT='CDC''s provisional count of U.S. drug-overdose deaths: rows by state, year/month, and indicator (total, or a specific drug class like fentanyl or heroin). Because it''s provisional, it also carries how complete the data is and a predicted value that adjusts for reporting lag. This is the running body count of the overdose epidemic. Raw landing table -- values stored as text, and ''provisional'' means recent months will revise upward as investigations close.' AS
SELECT
    "STATE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    "MONTH",
    "PERIOD",
    "INDICATOR",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DATA_VALUE"),'nan'),'NaN'),'NAN'),'')) AS "DATA_VALUE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PERCENT_COMPLETE"),'nan'),'NaN'),'NAN'),'')) AS "PERCENT_COMPLETE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PERCENT_PENDING_INVESTIGATION"),'nan'),'NaN'),'NAN'),'')) AS "PERCENT_PENDING_INVESTIGATION",
    "STATE_NAME",
    "FOOTNOTE",
    "FOOTNOTE_SYMBOL",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PREDICTED_VALUE"),'nan'),'NaN'),'NAN'),'')) AS "PREDICTED_VALUE",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CDC_OVERDOSE;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.DRUG_OVERDOSE_DEATH_RATES_BY_COUNTY COPY GRANTS COMMENT='The CDC''s county-level overdose death rates -- the map layer of the drug-death crisis, showing which counties got worse and when. Keyed by county FIPS, so it joins to almost any US geographic data. Heads up: the raw death rate here is banded into ranges (a text bucket, not an exact number) to protect small-county privacy -- fine for mapping hotspots, not for precise counts. Raw as loaded (every value stored as text).' AS
SELECT
    "FIPS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    "STATE",
    "ST",
    "FIPS_STATE",
    "COUNTY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("POPULATION"),'nan'),'NaN'),'NAN'),'')) AS "POPULATION",
    "ESTIMATED_AGE_ADJUSTED_DEATH_RATE_11_CATEGORIES_IN_RANGES",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CDC_DRUG_POISONING_COUNTY;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.HEALTHCARE_SHORTAGE_AREAS COPY GRANTS COMMENT='Every Health Professional Shortage Area and Medically Underserved Area designation: discipline (primary care, dental, mental health), shortage score, status, and dates. Heavily geographic -- it link-matches to dozens of place-keyed tables and answers ''is this an underserved area?'' for any US location.' AS
SELECT
    "HPSA_NAME",
    "HPSA_ID",
    "DESIGNATION_TYPE",
    "HPSA_DISCIPLINE_CLASS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HPSA_SCORE"),'nan'),'NaN'),'NAN'),'')) AS "HPSA_SCORE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PC_MCTA_SCORE"),'nan'),'NaN'),'NAN'),'')) AS "PC_MCTA_SCORE",
    "PRIMARY_STATE_ABBREVIATION",
    "HPSA_STATUS",
    CASE WHEN TRIM("HPSA_DESIGNATION_DATE") LIKE '%-%' OR TRIM("HPSA_DESIGNATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("HPSA_DESIGNATION_DATE")) END AS "HPSA_DESIGNATION_DATE",
    CASE WHEN TRIM("HPSA_DESIGNATION_LAST_UPDATE_DATE") LIKE '%-%' OR TRIM("HPSA_DESIGNATION_LAST_UPDATE_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("HPSA_DESIGNATION_LAST_UPDATE_DATE")) END AS "HPSA_DESIGNATION_LAST_UPDATE_DATE",
    "METROPOLITAN_INDICATOR",
    "HPSA_GEOGRAPHY_IDENTIFICATION_NUMBER",
    "HPSA_DEGREE_OF_SHORTAGE",
    CASE WHEN TRIM("WITHDRAWN_DATE") LIKE '%-%' OR TRIM("WITHDRAWN_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("WITHDRAWN_DATE")) END AS "WITHDRAWN_DATE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HPSA_FTE"),'nan'),'NaN'),'NAN'),'')) AS "HPSA_FTE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HPSA_DESIGNATION_POPULATION"),'nan'),'NaN'),'NAN'),'')) AS "HPSA_DESIGNATION_POPULATION",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OF_POPULATION_BELOW_100_POVERTY"),'nan'),'NaN'),'NAN'),'')) AS "OF_POPULATION_BELOW_100_POVERTY",
    "HPSA_FORMAL_RATIO",
    "HPSA_POPULATION_TYPE",
    "RURAL_STATUS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LONGITUDE"),'nan'),'NaN'),'NAN'),'')) AS "LONGITUDE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LATITUDE"),'nan'),'NaN'),'NAN'),'')) AS "LATITUDE",
    "BHCMIS_ORGANIZATION_IDENTIFICATION_NUMBER",
    "BREAK_IN_DESIGNATION",
    "COMMON_COUNTY_NAME",
    "COMMON_POSTAL_CODE",
    "COMMON_REGION_NAME",
    "COMMON_STATE_ABBREVIATION",
    "COMMON_STATE_COUNTY_FIPS_CODE",
    "COMMON_STATE_FIPS_CODE",
    "COMMON_STATE_NAME",
    "COUNTY_EQUIVALENT_NAME",
    "COUNTY_OR_COUNTY_EQUIVALENT_FEDERAL_INFORMATION_PROCESSING_STANDARD_CODE",
    "DISCIPLINE_CLASS_NUMBER",
    "HPSA_ADDRESS",
    "HPSA_CITY",
    "HPSA_COMPONENT_NAME",
    "HPSA_COMPONENT_SOURCE_IDENTIFICATION_NUMBER",
    "HPSA_COMPONENT_STATE_ABBREVIATION",
    "HPSA_COMPONENT_TYPE_CODE",
    "HPSA_COMPONENT_TYPE_DESCRIPTION",
    "HPSA_DESIGNATION_POPULATION_TYPE_DESCRIPTION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HPSA_ESTIMATED_SERVED_POPULATION"),'nan'),'NaN'),'NAN'),'')) AS "HPSA_ESTIMATED_SERVED_POPULATION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HPSA_ESTIMATED_UNDERSERVED_POPULATION"),'nan'),'NaN'),'NAN'),'')) AS "HPSA_ESTIMATED_UNDERSERVED_POPULATION",
    "HPSA_METROPOLITAN_INDICATOR_CODE",
    "HPSA_POPULATION_TYPE_CODE",
    "HPSA_POSTAL_CODE",
    "HPSA_PROVIDER_RATIO_GOAL",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HPSA_RESIDENT_CIVILIAN_POPULATION"),'nan'),'NaN'),'NAN'),'')) AS "HPSA_RESIDENT_CIVILIAN_POPULATION",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HPSA_SHORTAGE"),'nan'),'NaN'),'NAN'),'')) AS "HPSA_SHORTAGE",
    "HPSA_STATUS_CODE",
    "HPSA_TYPE_CODE",
    "HPSA_WITHDRAWN_DATE_STRING",
    "PRIMARY_STATE_FIPS_CODE",
    "PRIMARY_STATE_NAME",
    "PROVIDER_TYPE",
    "RURAL_STATUS_CODE",
    "STATE_ABBREVIATION",
    "STATE_AND_COUNTY_FEDERAL_INFORMATION_PROCESSING_STANDARD_CODE",
    "STATE_FIPS_CODE",
    "STATE_NAME",
    "U_S_MEXICO_BORDER_100_KILOMETER_INDICATOR",
    "U_S_MEXICO_BORDER_COUNTY_INDICATOR",
    CASE WHEN TRIM("DATA_WAREHOUSE_RECORD_CREATE_DATE") LIKE '%-%' OR TRIM("DATA_WAREHOUSE_RECORD_CREATE_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATA_WAREHOUSE_RECORD_CREATE_DATE")) END AS "DATA_WAREHOUSE_RECORD_CREATE_DATE",
    "DATA_WAREHOUSE_RECORD_CREATE_DATE_TEXT",
    "UNNAMED_65",
    "UNNAMED_64",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_HRSA_SHORTAGE_AREAS;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.HEALTH_INSURANCE_COVERAGE COPY GRANTS COMMENT='CDC survey indicators of health insurance coverage: the share of people insured, broken out by state, demographic subgroup, and time period, with confidence intervals. Tracks who has coverage and who doesn''t across the country. These are survey estimates, not headcounts, so read them with the intervals. Raw landing, stored as text; 16,056 rows from CDC NCHS.' AS
SELECT
    "INDICATOR",
    "C_GROUP",
    "STATE",
    "SUBGROUP",
    "PHASE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TIME_PERIOD"),'nan'),'NaN'),'NAN'),'')) AS "TIME_PERIOD",
    "TIME_PERIOD_LABEL",
    CASE WHEN TRIM("TIME_PERIOD_START_DATE") LIKE '%-%' OR TRIM("TIME_PERIOD_START_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("TIME_PERIOD_START_DATE")) END AS "TIME_PERIOD_START_DATE",
    CASE WHEN TRIM("TIME_PERIOD_END_DATE") LIKE '%-%' OR TRIM("TIME_PERIOD_END_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("TIME_PERIOD_END_DATE")) END AS "TIME_PERIOD_END_DATE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("VALUE"),'nan'),'NaN'),'NAN'),'')) AS "VALUE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LOWCI"),'nan'),'NaN'),'NAN'),'')) AS "LOWCI",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HIGHCI"),'nan'),'NaN'),'NAN'),'')) AS "HIGHCI",
    "CONFIDENCE_INTERVAL",
    "QUARTILE_RANGE",
    "QUARTILE_NUMBER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SUPPRESSION_FLAG"),'nan'),'NaN'),'NAN'),'')) AS "SUPPRESSION_FLAG",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CDC_HEALTH_INSURANCE;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.HOME_HEALTH_AGENCIES COPY GRANTS COMMENT='All 12,392 home health agencies certified by Medicare, with services offered, ownership, star ratings, and dozens of patient-outcome measures (how often patients got better, Medicare spending per episode). One row per agency, keyed by CCN so it joins to billing and ownership. Raw landing table, values stored as text.' AS
SELECT
    "STATE",
    "CCN",
    "PROVIDER_NAME",
    "ADDRESS",
    "CITY_TOWN",
    "ZIP_CODE",
    "TELEPHONE_NUMBER",
    "TYPE_OF_OWNERSHIP",
    "OFFERS_NURSING_CARE_SERVICES",
    "OFFERS_PHYSICAL_THERAPY_SERVICES",
    "OFFERS_OCCUPATIONAL_THERAPY_SERVICES",
    "OFFERS_SPEECH_PATHOLOGY_SERVICES",
    "OFFERS_MEDICAL_SOCIAL_SERVICES",
    "OFFERS_HOME_HEALTH_AIDE_SERVICES",
    CASE WHEN TRIM("CERTIFICATION_DATE") LIKE '%-%' OR TRIM("CERTIFICATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CERTIFICATION_DATE")) END AS "CERTIFICATION_DATE",
    "QUALITY_OF_PATIENT_CARE_STAR_RATING",
    "FOOTNOTE_FOR_QUALITY_OF_PATIENT_CARE_STAR_RATING",
    "NUMERATOR_FOR_HOW_OFTEN_THE_HOME_HEALTH_TEAM_BEGAN_THEIR_PATIENTS_CARE_IN_A_TIMELY_MANNER",
    "DENOMINATOR_FOR_HOW_OFTEN_THE_HOME_HEALTH_TEAM_BEGAN_THEIR_PATIENTS_CARE_IN_A_TIMELY_MANNER",
    "HOW_OFTEN_THE_HOME_HEALTH_TEAM_BEGAN_THEIR_PATIENTS_CARE_IN_A_TIMELY_MANNER",
    "FOOTNOTE_FOR_HOW_OFTEN_THE_HOME_HEALTH_TEAM_BEGAN_THEIR_PATIENTS_CARE_IN_A_TIMELY_MANNER",
    "NUMERATOR_FOR_HOW_OFTEN_THE_HOME_HEALTH_TEAM_DETERMINED_WHETHER_PATIENTS_RECEIVED_A_FLU_SHOT_FOR_THE_CURRENT_FLU_SEASON",
    "DENOMINATOR_FOR_HOW_OFTEN_THE_HOME_HEALTH_TEAM_DETERMINED_WHETHER_PATIENTS_RECEIVED_A_FLU_SHOT_FOR_THE_CURRENT_FLU_SEASON",
    "HOW_OFTEN_THE_HOME_HEALTH_TEAM_DETERMINED_WHETHER_PATIENTS_RECEIVED_A_FLU_SHOT_FOR_THE_CURRENT_FLU_SEASON",
    "FOOTNOTE_FOR_HOW_OFTEN_THE_HOME_HEALTH_TEAM_DETERMINED_WHETHER_PATIENTS_RECEIVED_A_FLU_SHOT_FOR_THE_CURRENT_FLU_SEASON",
    "NUMERATOR_FOR_HOW_OFTEN_PATIENTS_GOT_BETTER_AT_WALKING_OR_MOVING_AROUND",
    "DENOMINATOR_FOR_HOW_OFTEN_PATIENTS_GOT_BETTER_AT_WALKING_OR_MOVING_AROUND",
    "HOW_OFTEN_PATIENTS_GOT_BETTER_AT_WALKING_OR_MOVING_AROUND",
    "FOOTNOTE_FOR_HOW_OFTEN_PATIENTS_GOT_BETTER_AT_WALKING_OR_MOVING_AROUND",
    "NUMERATOR_FOR_HOW_OFTEN_PATIENTS_GOT_BETTER_AT_GETTING_IN_AND_OUT_OF_BED",
    "DENOMINATOR_FOR_HOW_OFTEN_PATIENTS_GOT_BETTER_AT_GETTING_IN_AND_OUT_OF_BED",
    "HOW_OFTEN_PATIENTS_GOT_BETTER_AT_GETTING_IN_AND_OUT_OF_BED",
    "FOOTNOTE_FOR_HOW_OFTEN_PATIENTS_GOT_BETTER_AT_GETTING_IN_AND_OUT_OF_BED",
    "NUMERATOR_FOR_HOW_OFTEN_PATIENTS_GOT_BETTER_AT_BATHING",
    "DENOMINATOR_FOR_HOW_OFTEN_PATIENTS_GOT_BETTER_AT_BATHING",
    "HOW_OFTEN_PATIENTS_GOT_BETTER_AT_BATHING",
    "FOOTNOTE_FOR_HOW_OFTEN_PATIENTS_GOT_BETTER_AT_BATHING",
    "NUMERATOR_FOR_HOW_OFTEN_PATIENTS_BREATHING_IMPROVED",
    "DENOMINATOR_FOR_HOW_OFTEN_PATIENTS_BREATHING_IMPROVED",
    "HOW_OFTEN_PATIENTS_BREATHING_IMPROVED",
    "FOOTNOTE_FOR_HOW_OFTEN_PATIENTS_BREATHING_IMPROVED",
    "NUMERATOR_FOR_HOW_OFTEN_PATIENTS_GOT_BETTER_AT_TAKING_THEIR_DRUGS_CORRECTLY_BY_MOUTH",
    "DENOMINATOR_FOR_HOW_OFTEN_PATIENTS_GOT_BETTER_AT_TAKING_THEIR_DRUGS_CORRECTLY_BY_MOUTH",
    "HOW_OFTEN_PATIENTS_GOT_BETTER_AT_TAKING_THEIR_DRUGS_CORRECTLY_BY_MOUTH",
    "FOOTNOTE_FOR_HOW_OFTEN_PATIENTS_GOT_BETTER_AT_TAKING_THEIR_DRUGS_CORRECTLY_BY_MOUTH",
    "NUMERATOR_FOR_CHANGES_IN_SKIN_INTEGRITY_POST_ACUTE_CARE_PRESSURE_ULCER_INJURY",
    "DENOMINATOR_FOR_CHANGES_IN_SKIN_INTEGRITY_POST_ACUTE_CARE_PRESSURE_ULCER_INJURY",
    "CHANGES_IN_SKIN_INTEGRITY_POST_ACUTE_CARE_PRESSURE_ULCER_INJURY",
