    "FOOTNOTE_FOR_HOW_OFTEN_PHYSICIAN_RECOMMENDED_ACTIONS_TO_ADDRESS_MEDICATION_ISSUES_WERE_COMPLETELY_TIMELY",
    "NUMERATOR_FOR_PERCENT_OF_RESIDENTS_EXPERIENCING_ONE_OR_MORE_FALLS_WITH_MAJOR_INJURY",
    "DENOMINATOR_FOR_PERCENT_OF_RESIDENTS_EXPERIENCING_ONE_OR_MORE_FALLS_WITH_MAJOR_INJURY",
    "PERCENT_OF_RESIDENTS_EXPERIENCING_ONE_OR_MORE_FALLS_WITH_MAJOR_INJURY",
    "FOOTNOTE_FOR_PERCENT_OF_RESIDENTS_EXPERIENCING_ONE_OR_MORE_FALLS_WITH_MAJOR_INJURY",
    "NUMERATOR_FOR_DISCHARGE_FUNCTION_SCORE",
    "DENOMINATOR_FOR_DISCHARGE_FUNCTION_SCORE",
    "DISCHARGE_FUNCTION_SCORE",
    "FOOTNOTE_FOR_DISCHARGE_FUNCTION_SCORE",
    "NUMERATOR_FOR_TRANSFER_OF_HEALTH_INFORMATION_TO_THE_PROVIDER",
    "DENOMINATOR_FOR_TRANSFER_OF_HEALTH_INFORMATION_TO_THE_PROVIDER",
