CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.HOSPICES COPY GRANTS COMMENT='All 6,852 hospice providers certified by Medicare, with location, ownership type, and certification date. One row per hospice, keyed by CCN (the Medicare facility ID) so it joins to billing, ownership, and quality data. The end-of-life care leg of the CMS provider spine. Raw landing table, values stored as text.' AS
SELECT
    "CCN",
    "FACILITY_NAME",
    "ADDRESS_LINE_1",
    "ADDRESS_LINE_2",
    "CITY_TOWN",
    "STATE",
    "ZIP_CODE",
    "COUNTY_PARISH",
    "TELEPHONE_NUMBER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CMS_REGION"),'nan'),'NaN'),'NAN'),'')) AS "CMS_REGION",
    "OWNERSHIP_TYPE",
    CASE WHEN TRIM("CERTIFICATION_DATE") LIKE '%-%' OR TRIM("CERTIFICATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CERTIFICATION_DATE")) END AS "CERTIFICATION_DATE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CMS_HOSPICE;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.HOSPITALS COPY GRANTS COMMENT='All 5,432 hospitals in the Medicare system, with type, ownership, whether they have an ER, overall quality rating, and counts of how they score on mortality, safety, and readmissions. One row per hospital, keyed by CCN so it joins to billing, ownership, and the rest of the provider spine. Raw landing table, values stored as text.' AS
SELECT
    "CCN",
    "FACILITY_NAME",
    "ADDRESS",
    "CITY_TOWN",
    "STATE",
    "ZIP_CODE",
    "COUNTY_PARISH",
    "TELEPHONE_NUMBER",
    "HOSPITAL_TYPE",
    "HOSPITAL_OWNERSHIP",
    "EMERGENCY_SERVICES",
    "MEETS_CRITERIA_FOR_BIRTHING_FRIENDLY_DESIGNATION",
    "HOSPITAL_OVERALL_RATING",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HOSPITAL_OVERALL_RATING_FOOTNOTE"),'nan'),'NaN'),'NAN'),'')) AS "HOSPITAL_OVERALL_RATING_FOOTNOTE",
    "MORT_GROUP_MEASURE_COUNT",
    "COUNT_OF_FACILITY_MORT_MEASURES",
    "COUNT_OF_MORT_MEASURES_BETTER",
    "COUNT_OF_MORT_MEASURES_NO_DIFFERENT",
    "COUNT_OF_MORT_MEASURES_WORSE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MORT_GROUP_FOOTNOTE"),'nan'),'NaN'),'NAN'),'')) AS "MORT_GROUP_FOOTNOTE",
    "SAFETY_GROUP_MEASURE_COUNT",
    "COUNT_OF_FACILITY_SAFETY_MEASURES",
    "COUNT_OF_SAFETY_MEASURES_BETTER",
    "COUNT_OF_SAFETY_MEASURES_NO_DIFFERENT",
    "COUNT_OF_SAFETY_MEASURES_WORSE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SAFETY_GROUP_FOOTNOTE"),'nan'),'NaN'),'NAN'),'')) AS "SAFETY_GROUP_FOOTNOTE",
    "READM_GROUP_MEASURE_COUNT",
    "COUNT_OF_FACILITY_READM_MEASURES",
    "COUNT_OF_READM_MEASURES_BETTER",
    "COUNT_OF_READM_MEASURES_NO_DIFFERENT",
    "COUNT_OF_READM_MEASURES_WORSE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("READM_GROUP_FOOTNOTE"),'nan'),'NaN'),'NAN'),'')) AS "READM_GROUP_FOOTNOTE",
    "PT_EXP_GROUP_MEASURE_COUNT",
    "COUNT_OF_FACILITY_PT_EXP_MEASURES",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PT_EXP_GROUP_FOOTNOTE"),'nan'),'NaN'),'NAN'),'')) AS "PT_EXP_GROUP_FOOTNOTE",
    "TE_GROUP_MEASURE_COUNT",
    "COUNT_OF_FACILITY_TE_MEASURES",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TE_GROUP_FOOTNOTE"),'nan'),'NaN'),'NAN'),'')) AS "TE_GROUP_FOOTNOTE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CMS_HOSPITAL_GENERAL;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.HOSPITAL_QUALITY_RATINGS COPY GRANTS COMMENT='The CMS Provider Data Catalog (Hospital Compare) hospital roster: facility ID, name, address, type, ownership, and quality/safety designations. The most-connected table in the whole Library -- name+ZIP matches tie it to cost reports, provider files, and enforcement tables. Start here for anything hospital-shaped.' AS
SELECT
    "FACILITY_ID",
    "FACILITY_NAME",
    "ADDRESS",
    "CITY_TOWN",
    "STATE",
    "ZIP_CODE",
    "COUNTY_PARISH",
    "TELEPHONE_NUMBER",
    "HOSPITAL_TYPE",
    "HOSPITAL_OWNERSHIP",
    "EMERGENCY_SERVICES",
    "MEETS_CRITERIA_FOR_BIRTHING_FRIENDLY_DESIGNATION",
    "HOSPITAL_OVERALL_RATING",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HOSPITAL_OVERALL_RATING_FOOTNOTE"),'nan'),'NaN'),'NAN'),'')) AS "HOSPITAL_OVERALL_RATING_FOOTNOTE",
    "MORT_GROUP_MEASURE_COUNT",
    "COUNT_OF_FACILITY_MORT_MEASURES",
    "COUNT_OF_MORT_MEASURES_BETTER",
    "COUNT_OF_MORT_MEASURES_NO_DIFFERENT",
    "COUNT_OF_MORT_MEASURES_WORSE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MORT_GROUP_FOOTNOTE"),'nan'),'NaN'),'NAN'),'')) AS "MORT_GROUP_FOOTNOTE",
    "SAFETY_GROUP_MEASURE_COUNT",
    "COUNT_OF_FACILITY_SAFETY_MEASURES",
    "COUNT_OF_SAFETY_MEASURES_BETTER",
    "COUNT_OF_SAFETY_MEASURES_NO_DIFFERENT",
    "COUNT_OF_SAFETY_MEASURES_WORSE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SAFETY_GROUP_FOOTNOTE"),'nan'),'NaN'),'NAN'),'')) AS "SAFETY_GROUP_FOOTNOTE",
    "READM_GROUP_MEASURE_COUNT",
    "COUNT_OF_FACILITY_READM_MEASURES",
    "COUNT_OF_READM_MEASURES_BETTER",
    "COUNT_OF_READM_MEASURES_NO_DIFFERENT",
    "COUNT_OF_READM_MEASURES_WORSE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("READM_GROUP_FOOTNOTE"),'nan'),'NaN'),'NAN'),'')) AS "READM_GROUP_FOOTNOTE",
    "PT_EXP_GROUP_MEASURE_COUNT",
    "COUNT_OF_FACILITY_PT_EXP_MEASURES",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PT_EXP_GROUP_FOOTNOTE"),'nan'),'NaN'),'NAN'),'')) AS "PT_EXP_GROUP_FOOTNOTE",
    "TE_GROUP_MEASURE_COUNT",
    "COUNT_OF_FACILITY_TE_MEASURES",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TE_GROUP_FOOTNOTE"),'nan'),'NaN'),'NAN'),'')) AS "TE_GROUP_FOOTNOTE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CMS_HOSPITAL_COMPARE;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.INJURY_VIOLENCE_DEATH_RATES COPY GRANTS COMMENT='CDC estimates of death and injury rates for each US county, broken out by intent (suicide, homicide, unintentional, etc.) -- the county-level picture of overdose and gun violence. Rates come with margins of error, and small counts are suppressed for privacy. Raw as loaded (all text); GEOID is the county FIPS code -- your join to any other county data. From CDC.' AS
SELECT
    "GEOID",
    "NAME",
    "ST_GEOID",
    "ST_NAME",
    "INTENT",
    "PERIOD",
    "COUNT_SUP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RATE"),'nan'),'NaN'),'NAN'),'')) AS "RATE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RATE_M"),'nan'),'NaN'),'NAN'),'')) AS "RATE_M",
    "RATE_M_CI",
    "DATA_AS_OF",
    "TTM_DATE_RANGE",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CDC_INJURY_VIOLENCE_COUNTY;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.INPATIENT_REHAB_FACILITIES COPY GRANTS COMMENT='All 1,222 inpatient rehabilitation facilities certified by Medicare (where patients recover after strokes, injuries, or surgery), with location, ownership type, and certification date. One row per facility, keyed by CCN so it joins to billing, ownership, and quality data. Raw landing table, values stored as text.' AS
SELECT
    "CCN",
    "PROVIDER_NAME",
    "ADDRESS_LINE_1",
    "ADDRESS_LINE_2",
    "CITY_TOWN",
    "STATE",
    "ZIP_CODE",
    "COUNTY_PARISH",
    "TELEPHONE_NUMBER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CMS_REGION"),'nan'),'NaN'),'NAN'),'')) AS "CMS_REGION",
    "OWNERSHIP_TYPE",
    CASE WHEN TRIM("CERTIFICATION_DATE") LIKE '%-%' OR TRIM("CERTIFICATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CERTIFICATION_DATE")) END AS "CERTIFICATION_DATE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CMS_IRF;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.LIFE_EXPECTANCY COPY GRANTS COMMENT='For each country and year, how many years a newborn can expect to live -- the single best summary of a population''s overall health. Great for long-run trends and comparing countries. Raw as loaded (all text); no join key, matched on country name/code. From Our World in Data.' AS
SELECT
    "ENTITY",
    "CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LIFE_EXPECTANCY"),'nan'),'NaN'),'NAN'),'')) AS "LIFE_EXPECTANCY",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_OWID_LIFE_EXPECTANCY;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.LONG_TERM_CARE_HOSPITALS COPY GRANTS COMMENT='All 311 long-term care hospitals certified by Medicare (facilities treating patients who need extended hospital-level care), with location, ownership type, bed count, and certification date. One row per hospital, keyed by CCN so it joins to billing, ownership, and quality data. Raw landing table, values stored as text.' AS
SELECT
    "CCN",
    "PROVIDER_NAME",
    "ADDRESS_LINE_1",
    "ADDRESS_LINE_2",
    "CITY_TOWN",
    "STATE",
    "ZIP_CODE",
    "COUNTY_PARISH",
    "TELEPHONE_NUMBER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CMS_REGION"),'nan'),'NaN'),'NAN'),'')) AS "CMS_REGION",
    "OWNERSHIP_TYPE",
    CASE WHEN TRIM("CERTIFICATION_DATE") LIKE '%-%' OR TRIM("CERTIFICATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CERTIFICATION_DATE")) END AS "CERTIFICATION_DATE",
    "TOTAL_NUMBER_OF_BEDS",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CMS_LTCH;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.MEDICARE_DRUG_PRESCRIBERS COPY GRANTS COMMENT='One row per prescriber showing their Medicare Part D prescribing: total claims, drug cost, day supply, brand vs generic split, and dedicated opioid and antibiotic measures including opioid prescribing rate. 1.4M rows keyed by NPI. Pair it with pharma payments to test whether industry money tracks with what doctors prescribe. Raw landing, all text.' AS
SELECT
    "NPI",
    "PRSCRBR_LAST_ORG_NAME",
    "PRSCRBR_FIRST_NAME",
    "PRSCRBR_MI",
    "PRSCRBR_CRDNTLS",
    "PRSCRBR_ENT_CD",
    "PRSCRBR_ST1",
    "PRSCRBR_ST2",
    "PRSCRBR_CITY",
    "PRSCRBR_STATE_ABRVTN",
    "PRSCRBR_STATE_FIPS",
    "PRSCRBR_ZIP5",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PRSCRBR_RUCA"),'nan'),'NaN'),'NAN'),'')) AS "PRSCRBR_RUCA",
    "PRSCRBR_RUCA_DESC",
    "PRSCRBR_CNTRY",
    "PRSCRBR_TYPE",
    "PRSCRBR_TYPE_SRC",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOT_CLMS"),'nan'),'NaN'),'NAN'),'')) AS "TOT_CLMS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOT_30DAY_FILLS"),'nan'),'NaN'),'NAN'),'')) AS "TOT_30DAY_FILLS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOT_DRUG_CST"),'nan'),'NaN'),'NAN'),'')) AS "TOT_DRUG_CST",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOT_DAY_SUPLY"),'nan'),'NaN'),'NAN'),'')) AS "TOT_DAY_SUPLY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOT_BENES"),'nan'),'NaN'),'NAN'),'')) AS "TOT_BENES",
    "GE65_SPRSN_FLAG",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GE65_TOT_CLMS"),'nan'),'NaN'),'NAN'),'')) AS "GE65_TOT_CLMS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GE65_TOT_30DAY_FILLS"),'nan'),'NaN'),'NAN'),'')) AS "GE65_TOT_30DAY_FILLS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GE65_TOT_DRUG_CST"),'nan'),'NaN'),'NAN'),'')) AS "GE65_TOT_DRUG_CST",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GE65_TOT_DAY_SUPLY"),'nan'),'NaN'),'NAN'),'')) AS "GE65_TOT_DAY_SUPLY",
    "GE65_BENE_SPRSN_FLAG",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GE65_TOT_BENES"),'nan'),'NaN'),'NAN'),'')) AS "GE65_TOT_BENES",
    "BRND_SPRSN_FLAG",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BRND_TOT_CLMS"),'nan'),'NaN'),'NAN'),'')) AS "BRND_TOT_CLMS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BRND_TOT_DRUG_CST"),'nan'),'NaN'),'NAN'),'')) AS "BRND_TOT_DRUG_CST",
    "GNRC_SPRSN_FLAG",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GNRC_TOT_CLMS"),'nan'),'NaN'),'NAN'),'')) AS "GNRC_TOT_CLMS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GNRC_TOT_DRUG_CST"),'nan'),'NaN'),'NAN'),'')) AS "GNRC_TOT_DRUG_CST",
    "OTHR_SPRSN_FLAG",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OTHR_TOT_CLMS"),'nan'),'NaN'),'NAN'),'')) AS "OTHR_TOT_CLMS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OTHR_TOT_DRUG_CST"),'nan'),'NaN'),'NAN'),'')) AS "OTHR_TOT_DRUG_CST",
    "MAPD_SPRSN_FLAG",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MAPD_TOT_CLMS"),'nan'),'NaN'),'NAN'),'')) AS "MAPD_TOT_CLMS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MAPD_TOT_DRUG_CST"),'nan'),'NaN'),'NAN'),'')) AS "MAPD_TOT_DRUG_CST",
    "PDP_SPRSN_FLAG",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PDP_TOT_CLMS"),'nan'),'NaN'),'NAN'),'')) AS "PDP_TOT_CLMS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PDP_TOT_DRUG_CST"),'nan'),'NaN'),'NAN'),'')) AS "PDP_TOT_DRUG_CST",
    "LIS_SPRSN_FLAG",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LIS_TOT_CLMS"),'nan'),'NaN'),'NAN'),'')) AS "LIS_TOT_CLMS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LIS_DRUG_CST"),'nan'),'NaN'),'NAN'),'')) AS "LIS_DRUG_CST",
    "NONLIS_SPRSN_FLAG",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NONLIS_TOT_CLMS"),'nan'),'NaN'),'NAN'),'')) AS "NONLIS_TOT_CLMS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NONLIS_DRUG_CST"),'nan'),'NaN'),'NAN'),'')) AS "NONLIS_DRUG_CST",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OPIOID_TOT_CLMS"),'nan'),'NaN'),'NAN'),'')) AS "OPIOID_TOT_CLMS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OPIOID_TOT_DRUG_CST"),'nan'),'NaN'),'NAN'),'')) AS "OPIOID_TOT_DRUG_CST",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OPIOID_TOT_SUPLY"),'nan'),'NaN'),'NAN'),'')) AS "OPIOID_TOT_SUPLY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OPIOID_TOT_BENES"),'nan'),'NaN'),'NAN'),'')) AS "OPIOID_TOT_BENES",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OPIOID_PRSCRBR_RATE"),'nan'),'NaN'),'NAN'),'')) AS "OPIOID_PRSCRBR_RATE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OPIOID_LA_TOT_CLMS"),'nan'),'NaN'),'NAN'),'')) AS "OPIOID_LA_TOT_CLMS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OPIOID_LA_TOT_DRUG_CST"),'nan'),'NaN'),'NAN'),'')) AS "OPIOID_LA_TOT_DRUG_CST",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OPIOID_LA_TOT_SUPLY"),'nan'),'NaN'),'NAN'),'')) AS "OPIOID_LA_TOT_SUPLY",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OPIOID_LA_TOT_BENES"),'nan'),'NaN'),'NAN'),'')) AS "OPIOID_LA_TOT_BENES",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OPIOID_LA_PRSCRBR_RATE"),'nan'),'NaN'),'NAN'),'')) AS "OPIOID_LA_PRSCRBR_RATE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ANTBTC_TOT_CLMS"),'nan'),'NaN'),'NAN'),'')) AS "ANTBTC_TOT_CLMS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ANTBTC_TOT_DRUG_CST"),'nan'),'NaN'),'NAN'),'')) AS "ANTBTC_TOT_DRUG_CST",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ANTBTC_TOT_BENES"),'nan'),'NaN'),'NAN'),'')) AS "ANTBTC_TOT_BENES",
    "ANTPSYCT_GE65_SPRSN_FLAG",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ANTPSYCT_GE65_TOT_CLMS"),'nan'),'NaN'),'NAN'),'')) AS "ANTPSYCT_GE65_TOT_CLMS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ANTPSYCT_GE65_TOT_DRUG_CST"),'nan'),'NaN'),'NAN'),'')) AS "ANTPSYCT_GE65_TOT_DRUG_CST",
    "ANTPSYCT_GE65_BENE_SUPRSN_FLAG",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ANTPSYCT_GE65_TOT_BENES"),'nan'),'NaN'),'NAN'),'')) AS "ANTPSYCT_GE65_TOT_BENES",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_AVG_AGE"),'nan'),'NaN'),'NAN'),'')) AS "BENE_AVG_AGE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_AGE_LT_65_CNT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_AGE_LT_65_CNT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_AGE_65_74_CNT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_AGE_65_74_CNT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_AGE_75_84_CNT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_AGE_75_84_CNT",
