    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_RACE_BLACK_CNT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_RACE_BLACK_CNT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_RACE_API_CNT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_RACE_API_CNT",
