    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_RACE_NATIND_CNT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_RACE_NATIND_CNT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_RACE_OTHR_CNT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_RACE_OTHR_CNT",
