CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.MEDICARE_FACILITIES COPY GRANTS COMMENT='CMS Provider of Services file: the deep-detail record for ~44,000 hospitals and non-hospital facilities, with hundreds of columns on bed counts, staffing, services offered, ownership changes, and termination status. Keyed by CCN and carrying FIPS geography, it''s the backbone reference for what a Medicare facility actually is and does. Raw landing table, values stored as text -- and yes, the column names are cryptic CMS codes.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PRVDR_CTGRY_SBTYP_CD"),'nan'),'NaN'),'NAN'),'')) AS "PRVDR_CTGRY_SBTYP_CD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PRVDR_CTGRY_CD"),'nan'),'NaN'),'NAN'),'')) AS "PRVDR_CTGRY_CD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CHOW_CNT"),'nan'),'NaN'),'NAN'),'')) AS "CHOW_CNT",
    TRY_TO_DATE(TRIM("CHOW_DT"),'YYYYMMDD') AS "CHOW_DT",
    "CITY_NAME",
    "ACPTBL_POC_SW",
    "CMPLNC_STUS_CD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SSA_CNTY_CD"),'nan'),'NaN'),'NAN'),'')) AS "SSA_CNTY_CD",
    "CROSS_REF_PROVIDER_NUMBER",
    TRY_TO_DATE(TRIM("CRTFCTN_DT"),'YYYYMMDD') AS "CRTFCTN_DT",
    "ELGBLTY_SW",
    "FAC_NAME",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("INTRMDRY_CARR_CD"),'nan'),'NaN'),'NAN'),'')) AS "INTRMDRY_CARR_CD",
    "MDCD_VNDR_NUM",
    TRY_TO_DATE(TRIM("ORGNL_PRTCPTN_DT"),'YYYYMMDD') AS "ORGNL_PRTCPTN_DT",
    TRY_TO_DATE(TRIM("CHOW_PRIOR_DT"),'YYYYMMDD') AS "CHOW_PRIOR_DT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("INTRMDRY_CARR_PRIOR_CD"),'nan'),'NaN'),'NAN'),'')) AS "INTRMDRY_CARR_PRIOR_CD",
    "CCN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RGN_CD"),'nan'),'NaN'),'NAN'),'')) AS "RGN_CD",
    "SKLTN_REC_SW",
