CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.MEDICARE_PROVIDER_BILLING COPY GRANTS COMMENT='One row per provider per year showing what they billed Medicare: services rendered, patients seen, charges submitted, and dollars Medicare actually paid, plus patient demographics and chronic-condition mix. 1.3M rows keyed by NPI, so it joins to the provider spine, pharma payments, and the banned-provider list. Raw landing -- every value is text, cast dollar amounts before you sum them.' AS
SELECT
    "NPI",
    "RNDRNG_PRVDR_LAST_ORG_NAME",
    "RNDRNG_PRVDR_FIRST_NAME",
    "RNDRNG_PRVDR_MI",
    "RNDRNG_PRVDR_CRDNTLS",
    "RNDRNG_PRVDR_ENT_CD",
    "RNDRNG_PRVDR_ST1",
    "RNDRNG_PRVDR_ST2",
    "RNDRNG_PRVDR_CITY",
    "RNDRNG_PRVDR_STATE_ABRVTN",
    "RNDRNG_PRVDR_STATE_FIPS",
    "RNDRNG_PRVDR_ZIP5",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RNDRNG_PRVDR_RUCA"),'nan'),'NaN'),'NAN'),'')) AS "RNDRNG_PRVDR_RUCA",
    "RNDRNG_PRVDR_RUCA_DESC",
    "RNDRNG_PRVDR_CNTRY",
    "RNDRNG_PRVDR_TYPE",
    "RNDRNG_PRVDR_MDCR_PRTCPTG_IND",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOT_HCPCS_CDS"),'nan'),'NaN'),'NAN'),'')) AS "TOT_HCPCS_CDS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOT_BENES"),'nan'),'NaN'),'NAN'),'')) AS "TOT_BENES",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOT_SRVCS"),'nan'),'NaN'),'NAN'),'')) AS "TOT_SRVCS",
