    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_CC_BH_SCHIZO_OTHPSY_V1_PCT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_CC_BH_SCHIZO_OTHPSY_V1_PCT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_CC_PH_ASTHMA_V2_PCT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_CC_PH_ASTHMA_V2_PCT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_CC_PH_AFIB_V2_PCT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_CC_PH_AFIB_V2_PCT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_CC_PH_CANCER6_V2_PCT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_CC_PH_CANCER6_V2_PCT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_CC_PH_CKD_V2_PCT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_CC_PH_CKD_V2_PCT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_CC_PH_COPD_V2_PCT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_CC_PH_COPD_V2_PCT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_CC_PH_DIABETES_V2_PCT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_CC_PH_DIABETES_V2_PCT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_CC_PH_HF_NONIHD_V2_PCT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_CC_PH_HF_NONIHD_V2_PCT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_CC_PH_HYPERLIPIDEMIA_V2_PCT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_CC_PH_HYPERLIPIDEMIA_V2_PCT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_CC_PH_HYPERTENSION_V2_PCT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_CC_PH_HYPERTENSION_V2_PCT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_CC_PH_ISCHEMICHEART_V2_PCT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_CC_PH_ISCHEMICHEART_V2_PCT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_CC_PH_OSTEOPOROSIS_V2_PCT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_CC_PH_OSTEOPOROSIS_V2_PCT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_CC_PH_PARKINSON_V2_PCT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_CC_PH_PARKINSON_V2_PCT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_CC_PH_ARTHRITIS_V2_PCT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_CC_PH_ARTHRITIS_V2_PCT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_CC_PH_STROKE_TIA_V2_PCT"),'nan'),'NaN'),'NAN'),'')) AS "BENE_CC_PH_STROKE_TIA_V2_PCT",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BENE_AVG_RISK_SCRE"),'nan'),'NaN'),'NAN'),'')) AS "BENE_AVG_RISK_SCRE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CMS_MEDICARE_PROVIDER;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.MONTHLY_ABORTION_COUNTS COPY GRANTS COMMENT='Guttmacher''s monthly estimate of abortions in each US state -- a median plus a lower and upper bound, because these are modeled estimates, not a hard count. The go-to for tracking how state bans shifted where abortions happen. Raw as loaded (all text); no join key, matched on state name. Treat the numbers as estimates with error bars, not exact totals.' AS
SELECT
    "STATE",
    "MONTH",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MEDIAN"),'nan'),'NaN'),'NAN'),'')) AS "MEDIAN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LOWERBOUND"),'nan'),'NaN'),'NAN'),'')) AS "LOWERBOUND",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("UPPERBOUND"),'nan'),'NaN'),'NAN'),'')) AS "UPPERBOUND",
    "SOURCE",
    "NOTES",
    "PUBLISHDATE",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_GUTTMACHER_MONTHLY_ABORTION;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.NURSING_HOME_WATCHDOG_DATA COPY GRANTS COMMENT='Facility-level nursing home data compiled by the Long Term Care Community Coalition from CMS sources: certified beds, staffing levels, ownership type and detail, inspections, and penalties. Overlaps the official NURSING_HOMES table but adds the watchdog''s ownership-detail angle -- CCN joins the two.' AS
SELECT
    "CMS_CERTIFICATION_NUMBER_CCN",
    "STATE",
    "PROVIDER_NAME",
    "PROVIDER_ADDRESS",
    "CITY_TOWN",
    "COUNTY_PARISH",
    "OWNERSHIP_TYPE",
    "OWNERSHIP_TYPE_DETAIL",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NUMBER_OF_CERTIFIED_BEDS"),'nan'),'NaN'),'NAN'),'')) AS "NUMBER_OF_CERTIFIED_BEDS",
    "AVERAGE_NUMBER_OF_RESIDENTS_PER_DAY",
    "PROVIDER_TYPE",
    "PROVIDER_RESIDES_IN_HOSPITAL",
    CASE WHEN TRIM("DATE_FIRST_APPROVED_TO_PROVIDE_MEDICARE_AND_MEDICAID_SERVICES") LIKE '%-%' OR TRIM("DATE_FIRST_APPROVED_TO_PROVIDE_MEDICARE_AND_MEDICAID_SERVICES") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE_FIRST_APPROVED_TO_PROVIDE_MEDICARE_AND_MEDICAID_SERVICES")) END AS "DATE_FIRST_APPROVED_TO_PROVIDE_MEDICARE_AND_MEDICAID_SERVICES",
    "CHAIN_NAME",
    "CHAIN_ID",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NUMBER_OF_FACILITIES_IN_CHAIN"),'nan'),'NaN'),'NAN'),'')) AS "NUMBER_OF_FACILITIES_IN_CHAIN",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CHAIN_AVERAGE_OVERALL_5_STAR_RATING"),'nan'),'NaN'),'NAN'),'')) AS "CHAIN_AVERAGE_OVERALL_5_STAR_RATING",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CHAIN_AVERAGE_HEALTH_INSPECTION_RATING"),'nan'),'NaN'),'NAN'),'')) AS "CHAIN_AVERAGE_HEALTH_INSPECTION_RATING",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CHAIN_AVERAGE_STAFFING_RATING"),'nan'),'NaN'),'NAN'),'')) AS "CHAIN_AVERAGE_STAFFING_RATING",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CHAIN_AVERAGE_QM_RATING"),'nan'),'NaN'),'NAN'),'')) AS "CHAIN_AVERAGE_QM_RATING",
    "CONTINUING_CARE_RETIREMENT_COMMUNITY",
    "SPECIAL_FOCUS_STATUS",
    "ABUSE_ICON",
    "PROBLEM_FACILITIES_SFFS_CANDIDATES_ONE_STAR",
    "MOST_RECENT_HEALTH_INSPECTION_MORE_THAN_2_YEARS_AGO",
    "PROVIDER_CHANGED_OWNERSHIP_IN_LAST_12_MONTHS",
    "WITH_A_RESIDENT_AND_FAMILY_COUNCIL",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OVERALL_RATING"),'nan'),'NaN'),'NAN'),'')) AS "OVERALL_RATING",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HEALTH_INSPECTION_RATING"),'nan'),'NaN'),'NAN'),'')) AS "HEALTH_INSPECTION_RATING",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("STAFFING_RATING"),'nan'),'NaN'),'NAN'),'')) AS "STAFFING_RATING",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("QM_RATING"),'nan'),'NaN'),'NAN'),'')) AS "QM_RATING",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REPORTED_NURSE_AIDE_STAFFING_HOURS_PER_RESIDENT_PER_DAY"),'nan'),'NaN'),'NAN'),'')) AS "REPORTED_NURSE_AIDE_STAFFING_HOURS_PER_RESIDENT_PER_DAY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXPECTED_NURSE_AIDE_STAFFING_HOURS_PER_RESIDENT_DAY"),'nan'),'NaN'),'NAN'),'')) AS "EXPECTED_NURSE_AIDE_STAFFING_HOURS_PER_RESIDENT_DAY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEVIATION_FROM_EXPECTED_NURSE_AIDE_STAFFING"),'nan'),'NaN'),'NAN'),'')) AS "DEVIATION_FROM_EXPECTED_NURSE_AIDE_STAFFING",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REPORTED_LPN_STAFFING_HOURS_PER_RESIDENT_PER_DAY"),'nan'),'NaN'),'NAN'),'')) AS "REPORTED_LPN_STAFFING_HOURS_PER_RESIDENT_PER_DAY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REPORTED_RN_STAFFING_HOURS_PER_RESIDENT_PER_DAY"),'nan'),'NaN'),'NAN'),'')) AS "REPORTED_RN_STAFFING_HOURS_PER_RESIDENT_PER_DAY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXPECTED_RN_STAFFING_HOURS_PER_RESIDENT_PER_DAY"),'nan'),'NaN'),'NAN'),'')) AS "EXPECTED_RN_STAFFING_HOURS_PER_RESIDENT_PER_DAY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEVIATION_FROM_EXPECTED_RN_STAFFING"),'nan'),'NaN'),'NAN'),'')) AS "DEVIATION_FROM_EXPECTED_RN_STAFFING",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REPORTED_LICENSED_STAFFING_HOURS_PER_RESIDENT_PER_DAY"),'nan'),'NaN'),'NAN'),'')) AS "REPORTED_LICENSED_STAFFING_HOURS_PER_RESIDENT_PER_DAY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REPORTED_TOTAL_NURSE_STAFFING_HOURS_PER_RESIDENT_PER_DAY"),'nan'),'NaN'),'NAN'),'')) AS "REPORTED_TOTAL_NURSE_STAFFING_HOURS_PER_RESIDENT_PER_DAY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("EXPECTED_TOTAL_NURSE_STAFFING_HOURS_PER_RESIDENT_DAY"),'nan'),'NaN'),'NAN'),'')) AS "EXPECTED_TOTAL_NURSE_STAFFING_HOURS_PER_RESIDENT_DAY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEVIATION_FROM_EXPECTED_TOTAL_NURSE_HOURS_PER_RESIDENT_PER_DAY"),'nan'),'NaN'),'NAN'),'')) AS "DEVIATION_FROM_EXPECTED_TOTAL_NURSE_HOURS_PER_RESIDENT_PER_DAY",
    "TOTAL_NUMBER_OF_NURSE_STAFF_HOURS_PER_RESIDENT_PER_DAY_ON_THE_WEEKEND",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REGISTERED_NURSE_HOURS_PER_RESIDENT_PER_DAY_ON_THE_WEEKEND"),'nan'),'NaN'),'NAN'),'')) AS "REGISTERED_NURSE_HOURS_PER_RESIDENT_PER_DAY_ON_THE_WEEKEND",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REPORTED_PHYSICAL_THERAPIST_STAFFING_HOURS_PER_RESIDENT_PER_DAY"),'nan'),'NaN'),'NAN'),'')) AS "REPORTED_PHYSICAL_THERAPIST_STAFFING_HOURS_PER_RESIDENT_PER_DAY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_NURSING_STAFF_TURNOVER"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_NURSING_STAFF_TURNOVER",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REGISTERED_NURSE_TURNOVER"),'nan'),'NaN'),'NAN'),'')) AS "REGISTERED_NURSE_TURNOVER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NUMBER_OF_ADMINISTRATORS_WHO_HAVE_LEFT_THE_NURSING_HOME"),'nan'),'NaN'),'NAN'),'')) AS "NUMBER_OF_ADMINISTRATORS_WHO_HAVE_LEFT_THE_NURSING_HOME",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NURSING_CASE_MIX_INDEX"),'nan'),'NaN'),'NAN'),'')) AS "NURSING_CASE_MIX_INDEX",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NURSING_CASE_MIX_INDEX_RATIO"),'nan'),'NaN'),'NAN'),'')) AS "NURSING_CASE_MIX_INDEX_RATIO",
    CASE WHEN TRIM("RATING_CYCLE_1_STANDARD_SURVEY_HEALTH_DATE") LIKE '%-%' OR TRIM("RATING_CYCLE_1_STANDARD_SURVEY_HEALTH_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("RATING_CYCLE_1_STANDARD_SURVEY_HEALTH_DATE")) END AS "RATING_CYCLE_1_STANDARD_SURVEY_HEALTH_DATE",
    "RATING_CYCLE_1_TOTAL_NUMBER_OF_HEALTH_DEFICIENCIES",
    "RATING_CYCLE_1_NUMBER_OF_STANDARD_HEALTH_DEFICIENCIES",
    "RATING_CYCLE_1_NUMBER_OF_COMPLAINT_HEALTH_DEFICIENCIES",
    "RATING_CYCLE_1_NUMBER_OF_HEALTH_REVISITS",
    CASE WHEN TRIM("RATING_CYCLE_2_STANDARD_HEALTH_SURVEY_DATE") LIKE '%-%' OR TRIM("RATING_CYCLE_2_STANDARD_HEALTH_SURVEY_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("RATING_CYCLE_2_STANDARD_HEALTH_SURVEY_DATE")) END AS "RATING_CYCLE_2_STANDARD_HEALTH_SURVEY_DATE",
    "RATING_CYCLE_2_3_TOTAL_NUMBER_OF_HEALTH_DEFICIENCIES",
    "RATING_CYCLE_2_NUMBER_OF_STANDARD_HEALTH_DEFICIENCIES",
    "RATING_CYCLE_2_3_NUMBER_OF_COMPLAINT_HEALTH_DEFICIENCIES",
    "RATING_CYCLE_2_3_NUMBER_OF_HEALTH_REVISITS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NUMBER_OF_FACILITY_REPORTED_INCIDENTS"),'nan'),'NaN'),'NAN'),'')) AS "NUMBER_OF_FACILITY_REPORTED_INCIDENTS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NUMBER_OF_SUBSTANTIATED_COMPLAINTS"),'nan'),'NaN'),'NAN'),'')) AS "NUMBER_OF_SUBSTANTIATED_COMPLAINTS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NUMBER_OF_FINES"),'nan'),'NaN'),'NAN'),'')) AS "NUMBER_OF_FINES",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_AMOUNT_OF_FINES_IN_DOLLARS"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_AMOUNT_OF_FINES_IN_DOLLARS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NUMBER_OF_PAYMENT_DENIALS"),'nan'),'NaN'),'NAN'),'')) AS "NUMBER_OF_PAYMENT_DENIALS",
    "TOTAL_NUMBER_OF_PENALTIES",
    "LOCATION",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LATITUDE"),'nan'),'NaN'),'NAN'),'')) AS "LATITUDE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LONGITUDE"),'nan'),'NaN'),'NAN'),'')) AS "LONGITUDE",
    "CMS_REGION_NUMBER",
    CASE WHEN TRIM("PROCESSING_DATE") LIKE '%-%' OR TRIM("PROCESSING_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("PROCESSING_DATE")) END AS "PROCESSING_DATE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_NURSINGHOME411;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.PHARMA_PAYMENTS_TO_DOCTORS COPY GRANTS COMMENT='CMS Open Payments general-payments detail: 15.4M individual payments and gifts from drug and device companies to physicians and teaching hospitals -- who paid, who got it (with NPI), how much, what it was for (meals, travel, consulting, speaking), and the drug or device involved. Cross it with Medicare prescribing to see whether the money moves the pen. Raw landing, all text -- cast the dollar amount before summing.' AS
SELECT
    "CHANGE_TYPE",
    "COVERED_RECIPIENT_TYPE",
    "CCN",
    "TEACHING_HOSPITAL_ID",
    "TEACHING_HOSPITAL_NAME",
    "COVERED_RECIPIENT_PROFILE_ID",
    "NPI",
    "COVERED_RECIPIENT_FIRST_NAME",
    "COVERED_RECIPIENT_MIDDLE_NAME",
    "COVERED_RECIPIENT_LAST_NAME",
    "COVERED_RECIPIENT_NAME_SUFFIX",
    "RECIPIENT_PRIMARY_BUSINESS_STREET_ADDRESS_LINE1",
    "RECIPIENT_PRIMARY_BUSINESS_STREET_ADDRESS_LINE2",
    "RECIPIENT_CITY",
    "RECIPIENT_STATE",
    "RECIPIENT_ZIP_CODE",
    "RECIPIENT_COUNTRY",
    "RECIPIENT_PROVINCE",
    "RECIPIENT_POSTAL_CODE",
    "COVERED_RECIPIENT_PRIMARY_TYPE_1",
    "COVERED_RECIPIENT_PRIMARY_TYPE_2",
    "COVERED_RECIPIENT_PRIMARY_TYPE_3",
    "COVERED_RECIPIENT_PRIMARY_TYPE_4",
    "COVERED_RECIPIENT_PRIMARY_TYPE_5",
    "COVERED_RECIPIENT_PRIMARY_TYPE_6",
    "COVERED_RECIPIENT_SPECIALTY_1",
    "COVERED_RECIPIENT_SPECIALTY_2",
    "COVERED_RECIPIENT_SPECIALTY_3",
    "COVERED_RECIPIENT_SPECIALTY_4",
    "COVERED_RECIPIENT_SPECIALTY_5",
    "COVERED_RECIPIENT_SPECIALTY_6",
    "COVERED_RECIPIENT_LICENSE_STATE_CODE1",
    "COVERED_RECIPIENT_LICENSE_STATE_CODE2",
    "COVERED_RECIPIENT_LICENSE_STATE_CODE3",
    "COVERED_RECIPIENT_LICENSE_STATE_CODE4",
    "COVERED_RECIPIENT_LICENSE_STATE_CODE5",
    "SUBMITTING_APPLICABLE_MANUFACTURER_OR_APPLICABLE_GPO_NAME",
    "APPLICABLE_MANUFACTURER_OR_APPLICABLE_GPO_MAKING_PAYMENT_ID",
    "APPLICABLE_MANUFACTURER_OR_APPLICABLE_GPO_MAKING_PAYMENT_NAME",
    "APPLICABLE_MANUFACTURER_OR_APPLICABLE_GPO_MAKING_PAYMENT_STATE",
    "APPLICABLE_MANUFACTURER_OR_APPLICABLE_GPO_MAKING_PAYMENT_COUNTRY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_AMOUNT_OF_PAYMENT_USDOLLARS"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_AMOUNT_OF_PAYMENT_USDOLLARS",
    CASE WHEN TRIM("DATE_OF_PAYMENT") LIKE '%-%' OR TRIM("DATE_OF_PAYMENT") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE_OF_PAYMENT")) END AS "DATE_OF_PAYMENT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NUMBER_OF_PAYMENTS_INCLUDED_IN_TOTAL_AMOUNT"),'nan'),'NaN'),'NAN'),'')) AS "NUMBER_OF_PAYMENTS_INCLUDED_IN_TOTAL_AMOUNT",
    "FORM_OF_PAYMENT_OR_TRANSFER_OF_VALUE",
    "NATURE_OF_PAYMENT_OR_TRANSFER_OF_VALUE",
    "CITY_OF_TRAVEL",
    "STATE_OF_TRAVEL",
    "COUNTRY_OF_TRAVEL",
    "PHYSICIAN_OWNERSHIP_INDICATOR",
    "THIRD_PARTY_PAYMENT_RECIPIENT_INDICATOR",
    "NAME_OF_THIRD_PARTY_ENTITY_RECEIVING_PAYMENT_OR_TRANSFER_OF_VALUE",
    "CHARITY_INDICATOR",
    "THIRD_PARTY_EQUALS_COVERED_RECIPIENT_INDICATOR",
    "CONTEXTUAL_INFORMATION",
    "DELAY_IN_PUBLICATION_INDICATOR",
    "RECORD_ID",
    "DISPUTE_STATUS_FOR_PUBLICATION",
    "RELATED_PRODUCT_INDICATOR",
    "COVERED_OR_NONCOVERED_INDICATOR_1",
    "INDICATE_DRUG_OR_BIOLOGICAL_OR_DEVICE_OR_MEDICAL_SUPPLY_1",
    "PRODUCT_CATEGORY_OR_THERAPEUTIC_AREA_1",
    "NAME_OF_DRUG_OR_BIOLOGICAL_OR_DEVICE_OR_MEDICAL_SUPPLY_1",
    "ASSOCIATED_DRUG_OR_BIOLOGICAL_NDC_1",
    "ASSOCIATED_DEVICE_OR_MEDICAL_SUPPLY_PDI_1",
    "COVERED_OR_NONCOVERED_INDICATOR_2",
    "INDICATE_DRUG_OR_BIOLOGICAL_OR_DEVICE_OR_MEDICAL_SUPPLY_2",
    "PRODUCT_CATEGORY_OR_THERAPEUTIC_AREA_2",
    "NAME_OF_DRUG_OR_BIOLOGICAL_OR_DEVICE_OR_MEDICAL_SUPPLY_2",
    "ASSOCIATED_DRUG_OR_BIOLOGICAL_NDC_2",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ASSOCIATED_DEVICE_OR_MEDICAL_SUPPLY_PDI_2"),'nan'),'NaN'),'NAN'),'')) AS "ASSOCIATED_DEVICE_OR_MEDICAL_SUPPLY_PDI_2",
    "COVERED_OR_NONCOVERED_INDICATOR_3",
    "INDICATE_DRUG_OR_BIOLOGICAL_OR_DEVICE_OR_MEDICAL_SUPPLY_3",
    "PRODUCT_CATEGORY_OR_THERAPEUTIC_AREA_3",
    "NAME_OF_DRUG_OR_BIOLOGICAL_OR_DEVICE_OR_MEDICAL_SUPPLY_3",
    "ASSOCIATED_DRUG_OR_BIOLOGICAL_NDC_3",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ASSOCIATED_DEVICE_OR_MEDICAL_SUPPLY_PDI_3"),'nan'),'NaN'),'NAN'),'')) AS "ASSOCIATED_DEVICE_OR_MEDICAL_SUPPLY_PDI_3",
    "COVERED_OR_NONCOVERED_INDICATOR_4",
    "INDICATE_DRUG_OR_BIOLOGICAL_OR_DEVICE_OR_MEDICAL_SUPPLY_4",
    "PRODUCT_CATEGORY_OR_THERAPEUTIC_AREA_4",
    "NAME_OF_DRUG_OR_BIOLOGICAL_OR_DEVICE_OR_MEDICAL_SUPPLY_4",
    "ASSOCIATED_DRUG_OR_BIOLOGICAL_NDC_4",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ASSOCIATED_DEVICE_OR_MEDICAL_SUPPLY_PDI_4"),'nan'),'NaN'),'NAN'),'')) AS "ASSOCIATED_DEVICE_OR_MEDICAL_SUPPLY_PDI_4",
    "COVERED_OR_NONCOVERED_INDICATOR_5",
    "INDICATE_DRUG_OR_BIOLOGICAL_OR_DEVICE_OR_MEDICAL_SUPPLY_5",
    "PRODUCT_CATEGORY_OR_THERAPEUTIC_AREA_5",
    "NAME_OF_DRUG_OR_BIOLOGICAL_OR_DEVICE_OR_MEDICAL_SUPPLY_5",
    "ASSOCIATED_DRUG_OR_BIOLOGICAL_NDC_5",
    "ASSOCIATED_DEVICE_OR_MEDICAL_SUPPLY_PDI_5",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PROGRAM_YEAR"),'nan'),'NaN'),'NAN'),'')) AS "PROGRAM_YEAR",
    CASE WHEN TRIM("PAYMENT_PUBLICATION_DATE") LIKE '%-%' OR TRIM("PAYMENT_PUBLICATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("PAYMENT_PUBLICATION_DATE")) END AS "PAYMENT_PUBLICATION_DATE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CMS_OPEN_PAYMENTS;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.PHARMA_PAYMENTS_TO_DOCTORS_2023 COPY GRANTS COMMENT='CMS Open Payments for 2023: each general payment or gift from a pharma/device company to a physician or teaching hospital -- amount, date, the company, and the drug or device it was tied to (14.7M rows). This is how you see which doctors take money from whom. Carries NPI (doctor) and CCN (hospital) so it links to the provider spine and the banned-provider list. Raw landing -- every field text, one program year (2023) only.' AS
SELECT
    "CHANGE_TYPE",
    "COVERED_RECIPIENT_TYPE",
    "CCN",
    "TEACHING_HOSPITAL_ID",
    "TEACHING_HOSPITAL_NAME",
