CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.SUICIDE_DEATH_RATES COPY GRANTS COMMENT='The CDC''s official suicide death rates for the US, sliced by year, age group, sex and race/ethnicity. Good for tracking how suicide has moved over decades and which groups are hit hardest. Raw as loaded (every value stored as text) -- ESTIMATE is a rate, not a count, and rows carry demographic-breakdown labels (STUB_NAME/STUB_LABEL) you filter on. No geography and no join keys, so it stands alone as a trend source.' AS
SELECT
    "INDICATOR",
    "UNIT",
    "UNIT_NUM",
    "STUB_NAME",
    "STUB_NAME_NUM",
    "STUB_LABEL",
    "STUB_LABEL_NUM",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    "YEAR_NUM",
    "AGE",
    "AGE_NUM",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ESTIMATE"),'nan'),'NaN'),'NAN'),'')) AS "ESTIMATE",
    "FLAG",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_CDC_SUICIDE_RATES;

CREATE OR REPLACE VIEW THE_LIBRARY.HEALTH.VETERAN_SUICIDE_RATES COPY GRANTS COMMENT='The VA''s National Veteran Suicide report appendix: veteran suicide death counts and adjusted rates broken out by sex over 2001-2023. The authoritative federal number on veteran suicide. Heads up: this is a raw spreadsheet dump (144 rows) -- the real column headers are buried in the data (columns are named COL_1..COL_12) and need reshaping in staging before it''s usable. Raw as loaded (every value stored as text).' AS
SELECT
    "VETERAN_DEATHS_BY_SUICIDE_UNADJUSTED_AND_ADJUSTED_RATES_BY_SEX_2001_23",
    "COL_1",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COL_2"),'nan'),'NaN'),'NAN'),'')) AS "COL_2",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COL_3"),'nan'),'NaN'),'NAN'),'')) AS "COL_3",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COL_4"),'nan'),'NaN'),'NAN'),'')) AS "COL_4",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COL_5"),'nan'),'NaN'),'NAN'),'')) AS "COL_5",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COL_6"),'nan'),'NaN'),'NAN'),'')) AS "COL_6",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COL_7"),'nan'),'NaN'),'NAN'),'')) AS "COL_7",
    "COL_8",
    "COL_9",
    "COL_10",
    "COL_11",
    "COL_12",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_VA_SUICIDE_APPENDIX;

CREATE OR REPLACE VIEW THE_LIBRARY.HISTORY.INTRA_AMERICAN_SLAVE_VOYAGES COPY GRANTS COMMENT='A voyage-level record of the intra-American slave trade (Americas to Americas), roughly 1550-1888: one row per documented slaving voyage with the ship, captain, ports of embarkation and arrival, and the number of captives loaded and landed. 11,521 voyages, 169 detailed variables. From the SlaveVoyages project (Emory/Harvard). Raw landing, stored as text.' AS
