CREATE OR REPLACE VIEW THE_LIBRARY.HOUSING.HOUSE_PRICE_INDEX COPY GRANTS COMMENT='The authoritative US house-price index from the FHFA, tracking how home prices move over time at every geography down to census tract. The price half of housing affordability -- joins by FIPS/ZIP onto redlining, census, and rent data. Heads up: values are unitless index numbers (not dollars) with different base years per series, and the file mixes geographic levels and index types in one table -- split and base-note it before use. Raw landing, stored as text; 184,807 rows.' AS
SELECT
    "HPI_TYPE",
    "HPI_FLAVOR",
    "FREQUENCY",
    "LEVEL",
    "PLACE_NAME",
    "PLACE_ID",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YR"),'nan'),'NaN'),'NAN'),'')) AS "YR",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PERIOD"),'nan'),'NaN'),'NAN'),'')) AS "PERIOD",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("INDEX_NSA"),'nan'),'NaN'),'NAN'),'')) AS "INDEX_NSA",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("INDEX_SA"),'nan'),'NaN'),'NAN'),'')) AS "INDEX_SA",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RSTDERR"),'nan'),'NaN'),'NAN'),'')) AS "RSTDERR",
    "NOTE",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_FHFA_HPI;

CREATE OR REPLACE VIEW THE_LIBRARY.HOUSING.HUD_DATASET_CATALOG COPY GRANTS COMMENT='A catalog of HUD Policy Development & Research datasets: name, URL, description, and rough geography columns. It''s the shopping list, not the groceries -- 77 pointers to housing datasets worth pouring individually.' AS
SELECT
    "DATASET_NAME",
    "DATASET_URL",
    "DESCRIPTION",
    "FIPS",
    "ZIP",
    "EIN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    "VALUE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_HUD_DATA;

CREATE OR REPLACE VIEW THE_LIBRARY.HOUSING.MORTGAGE_APPLICATIONS COPY GRANTS COMMENT='Home Mortgage Disclosure Act records: one row per mortgage application with lender (LEI), census tract, borrower demographics, loan terms, and outcome. The landed 28K rows are a sample of an enormous annual release. This is the canonical dataset for lending-discrimination analysis -- census tract joins it to redlining maps and demographics.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTIVITY_YEAR"),'nan'),'NaN'),'NAN'),'')) AS "ACTIVITY_YEAR",
    "LEI",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DERIVED_MSA_MD"),'nan'),'NaN'),'NAN'),'')) AS "DERIVED_MSA_MD",
    "STATE_CODE",
