    "DERIVED_LOAN_PRODUCT_TYPE",
    "DERIVED_DWELLING_CATEGORY",
    "DERIVED_ETHNICITY",
    "DERIVED_RACE",
    "DERIVED_SEX",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACTION_TAKEN"),'nan'),'NaN'),'NAN'),'')) AS "ACTION_TAKEN",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PURCHASER_TYPE"),'nan'),'NaN'),'NAN'),'')) AS "PURCHASER_TYPE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PREAPPROVAL"),'nan'),'NaN'),'NAN'),'')) AS "PREAPPROVAL",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LOAN_TYPE"),'nan'),'NaN'),'NAN'),'')) AS "LOAN_TYPE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LOAN_PURPOSE"),'nan'),'NaN'),'NAN'),'')) AS "LOAN_PURPOSE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LIEN_STATUS"),'nan'),'NaN'),'NAN'),'')) AS "LIEN_STATUS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REVERSE_MORTGAGE"),'nan'),'NaN'),'NAN'),'')) AS "REVERSE_MORTGAGE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OPEN_END_LINE_OF_CREDIT"),'nan'),'NaN'),'NAN'),'')) AS "OPEN_END_LINE_OF_CREDIT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BUSINESS_OR_COMMERCIAL_PURPOSE"),'nan'),'NaN'),'NAN'),'')) AS "BUSINESS_OR_COMMERCIAL_PURPOSE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LOAN_AMOUNT"),'nan'),'NaN'),'NAN'),'')) AS "LOAN_AMOUNT",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LOAN_TO_VALUE_RATIO"),'nan'),'NaN'),'NAN'),'')) AS "LOAN_TO_VALUE_RATIO",
