CREATE OR REPLACE VIEW THE_LIBRARY.IMMIGRATION.BORDER_ENFORCEMENT_MONTHLY COPY GRANTS COMMENT='Monthly operational statistics from DHS''s Office of Homeland Security Statistics: encounter type, region/sector, citizenship, family status, criminality, and outcomes. The most granular public view of border and interior enforcement -- the numbers behind every enforcement-surge story.' AS
SELECT
    "REPORT_MONTH",
    "TABLE_NAME",
    "ENCOUNTER_TYPE",
    "REGION_OR_SECTOR",
    "CITIZENSHIP",
    "FAMILY_STATUS",
    "CRIMINALITY",
    "INITIAL_ARRESTING_AGENCY",
