CREATE OR REPLACE VIEW THE_LIBRARY.IMMIGRATION.FOREIGN_WORKER_VISA_APPLICATIONS COPY GRANTS COMMENT='Case-level foreign labor certification disclosures from DOL: employer name, job title, SOC code, wage, visa class, and case outcome. 665K rows and one of the most-connected tables in the Library -- employer names match to companies, and it''s the definitive ''who sponsors foreign workers, for what jobs, at what pay'' table.' AS
SELECT
    "CASE_NUMBER",
    "CASE_STATUS",
    "CASE_SUBMITTED",
    CASE WHEN TRIM("DECISION_DATE") LIKE '%-%' OR TRIM("DECISION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DECISION_DATE")) END AS "DECISION_DATE",
    CASE WHEN TRIM("ORIGINAL_CERT_DATE") LIKE '%-%' OR TRIM("ORIGINAL_CERT_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("ORIGINAL_CERT_DATE")) END AS "ORIGINAL_CERT_DATE",
    "VISA_CLASS",
    "JOB_TITLE",
    "SOC_CODE",
    "SOC_TITLE",
    "FULL_TIME_POSITION",
    CASE WHEN TRIM("PERIOD_OF_EMPLOYMENT_START_DATE") LIKE '%-%' OR TRIM("PERIOD_OF_EMPLOYMENT_START_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("PERIOD_OF_EMPLOYMENT_START_DATE")) END AS "PERIOD_OF_EMPLOYMENT_START_DATE",
    CASE WHEN TRIM("PERIOD_OF_EMPLOYMENT_END_DATE") LIKE '%-%' OR TRIM("PERIOD_OF_EMPLOYMENT_END_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("PERIOD_OF_EMPLOYMENT_END_DATE")) END AS "PERIOD_OF_EMPLOYMENT_END_DATE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_WORKER_POSITIONS"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_WORKER_POSITIONS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NEW_EMPLOYMENT"),'nan'),'NaN'),'NAN'),'')) AS "NEW_EMPLOYMENT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CONTINUED_EMPLOYMENT"),'nan'),'NaN'),'NAN'),'')) AS "CONTINUED_EMPLOYMENT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CHANGE_PREVIOUS_EMPLOYMENT"),'nan'),'NaN'),'NAN'),'')) AS "CHANGE_PREVIOUS_EMPLOYMENT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NEW_CONCURRENT_EMPLOYMENT"),'nan'),'NaN'),'NAN'),'')) AS "NEW_CONCURRENT_EMPLOYMENT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("CHANGE_EMPLOYER"),'nan'),'NaN'),'NAN'),'')) AS "CHANGE_EMPLOYER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("AMENDED_PETITION"),'nan'),'NaN'),'NAN'),'')) AS "AMENDED_PETITION",
    "EMPLOYER_NAME",
    "EMPLOYER_BUSINESS_DBA",
    "EMPLOYER_ADDRESS1",
    "EMPLOYER_ADDRESS2",
    "EMPLOYER_CITY",
    "EMPLOYER_STATE",
    "EMPLOYER_POSTAL_CODE",
    "EMPLOYER_COUNTRY",
    "EMPLOYER_PROVINCE",
    "EMPLOYER_PHONE",
    "EMPLOYER_PHONE_EXT",
    "NAICS_CODE",
    "AGENT_REPRESENTING_EMPLOYER",
    "AGENT_ATTORNEY_LAW_FIRM_BUSINESS_NAME",
    "AGENT_ATTORNEY_ADDRESS1",
    "AGENT_ATTORNEY_ADDRESS2",
    "AGENT_ATTORNEY_CITY",
    "AGENT_ATTORNEY_STATE",
    "AGENT_ATTORNEY_POSTAL_CODE",
    "AGENT_ATTORNEY_COUNTRY",
    "AGENT_ATTORNEY_PROVINCE",
    "AGENT_ATTORNEY_PHONE",
    "AGENT_ATTORNEY_PHONE_EXT",
    "STATE_OF_HIGHEST_COURT",
    "NAME_OF_HIGHEST_STATE_COURT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WORKSITE_WORKERS_1"),'nan'),'NaN'),'NAN'),'')) AS "WORKSITE_WORKERS_1",
    "SECONDARY_ENTITY_1",
    "SECONDARY_ENTITY_BUSINESS_NAME_1",
    "WORKSITE_ADDRESS1_1",
    "WORKSITE_ADDRESS2_1",
    "WORKSITE_CITY_1",
    "WORKSITE_COUNTY_1",
    "WORKSITE_STATE_1",
    "WORKSITE_POSTAL_CODE_1",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WAGE_RATE_OF_PAY_FROM_1"),'nan'),'NaN'),'NAN'),'')) AS "WAGE_RATE_OF_PAY_FROM_1",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WAGE_RATE_OF_PAY_TO_1"),'nan'),'NaN'),'NAN'),'')) AS "WAGE_RATE_OF_PAY_TO_1",
    "WAGE_UNIT_OF_PAY_1",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PREVAILING_WAGE_1"),'nan'),'NaN'),'NAN'),'')) AS "PREVAILING_WAGE_1",
    "PW_UNIT_OF_PAY_1",
    "PW_TRACKING_NUMBER_1",
    "PW_WAGE_LEVEL_1",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PW_OES_YEAR_1"),'nan'),'NaN'),'NAN'),'')) AS "PW_OES_YEAR_1",
    "PW_OTHER_SOURCE_1",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PW_NON_OES_YEAR_1"),'nan'),'NaN'),'NAN'),'')) AS "PW_NON_OES_YEAR_1",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PW_SURVEY_PUBLISHER_1"),'nan'),'NaN'),'NAN'),'')) AS "PW_SURVEY_PUBLISHER_1",
    "PW_SURVEY_NAME_1",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WORKSITE_WORKERS_2"),'nan'),'NaN'),'NAN'),'')) AS "WORKSITE_WORKERS_2",
