    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WAGE_RATE_OF_PAY_TO_2"),'nan'),'NaN'),'NAN'),'')) AS "WAGE_RATE_OF_PAY_TO_2",
    "WAGE_UNIT_OF_PAY_2",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PREVAILING_WAGE_2"),'nan'),'NaN'),'NAN'),'')) AS "PREVAILING_WAGE_2",
    "PW_UNIT_OF_PAY_2",
    "PW_TRACKING_NUMBER_2",
    "PW_WAGE_LEVEL_2",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PW_OES_YEAR_2"),'nan'),'NaN'),'NAN'),'')) AS "PW_OES_YEAR_2",
    "PW_OTHER_SOURCE_2",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PW_NON_OES_YEAR_2"),'nan'),'NaN'),'NAN'),'')) AS "PW_NON_OES_YEAR_2",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PW_SURVEY_PUBLISHER_2"),'nan'),'NaN'),'NAN'),'')) AS "PW_SURVEY_PUBLISHER_2",
    "PW_SURVEY_NAME_2",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WORKSITE_WORKERS_3"),'nan'),'NaN'),'NAN'),'')) AS "WORKSITE_WORKERS_3",
