    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WAGE_RATE_OF_PAY_TO_3"),'nan'),'NaN'),'NAN'),'')) AS "WAGE_RATE_OF_PAY_TO_3",
