CREATE OR REPLACE VIEW THE_LIBRARY.IMMIGRATION.ICE_ENFORCEMENT_STATS COPY GRANTS COMMENT='Quarterly ICE Enforcement and Removal Operations statistics: metric, fiscal quarter, country of citizenship, criminal-history category, and area of responsibility. Aggregate-level (221 rows) -- topline context that pairs with the bigger BORDER_ENFORCEMENT_MONTHLY table.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FISCAL_YEAR"),'nan'),'NaN'),'NAN'),'')) AS "FISCAL_YEAR",
    "FISCAL_QUARTER",
    "METRIC_TYPE",
    "COUNTRY_OF_CITIZENSHIP",
    "CRIMINAL_HISTORY_CATEGORY",
    "AOR",
    "COUNT",
    "REMOVAL_AUTHORITY",
    "ATD_MONITORING_TYPE",
    CASE WHEN TRIM("SNAPSHOT_DATE") LIKE '%-%' OR TRIM("SNAPSHOT_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("SNAPSHOT_DATE")) END AS "SNAPSHOT_DATE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_ICE_STATISTICS;

CREATE OR REPLACE VIEW THE_LIBRARY.IMMIGRATION.IMMIGRATION_YEARBOOK_TABLES COPY GRANTS COMMENT='Rows from the DHS Yearbook of Immigration Statistics: category, fiscal year, country, and count across lawful permanent residents, admissions, refugees, and enforcement. A 27-row probe of the yearbook''s tables -- historical context, decades deep once fully poured.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FISCAL_YEAR"),'nan'),'NaN'),'NAN'),'')) AS "FISCAL_YEAR",
    "COUNTRY_OF_BIRTH",
    "COUNTRY_OF_LAST_RESIDENCE",
    "CATEGORY",
    "STATE",
    "COUNT",
    "TABLE_NAME",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEARBOOK_EDITION"),'nan'),'NaN'),'NAN'),'')) AS "YEARBOOK_EDITION",
    "ENFORCEMENT_ACTION_TYPE",
    "VISA_CLASS",
    "SOURCE_PDF_URL",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_DHS_YEARBOOK;

CREATE OR REPLACE VIEW THE_LIBRARY.IMMIGRATION.REFUGEES_BY_ORIGIN_COUNTRY COPY GRANTS COMMENT='Refugee counts by country of origin and year (Our World in Data / UNHCR): each row says how many people from a given country were living as refugees that year, tagged with world region. It answers ''where are people fleeing from, and how has that grown?'' Country is an ISO3 code for joining to other international data. Raw landing table -- values stored as text, so cast the count before summing.' AS
SELECT
    "ENTITY",
    "CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("REFUGEES_BY_COUNTRY_OF_ORIGIN"),'nan'),'NaN'),'NAN'),'')) AS "REFUGEES_BY_COUNTRY_OF_ORIGIN",
    "WORLD_REGION_ACCORDING_TO_OWID",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.XC_OWID_REFUGEES;

CREATE OR REPLACE VIEW THE_LIBRARY.INVESTIGATIONS.RUSSIAN_OPERATIONS_AGAINST_EUROPE COPY GRANTS COMMENT='An academic dataset (Harvard Dataverse) cataloging Russian covert and hybrid operations against Europe: what happened, where, the event category, the apparent goal, and the target type. The evidence base for Russia-NATO gray-zone conflict reporting. Heads up: 153 hand-coded incidents -- an analyst-curated set, not a comprehensive registry, and the coding categories are judgment calls. Raw as loaded (every value stored as text).' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("INCIDENTYEAR"),'nan'),'NaN'),'NAN'),'')) AS "INCIDENTYEAR",
    "INCIDENTMONTH",
    "INCIDENTDATERANGE",
    "INCIDENTDATESTART",
    "INCIDENTDATEEND",
    "WHAT",
    "C_WHERE",
    "EVENTCATEGORY",
    "EVENTCATEGORY2",
    "APPARENTGOAL1",
    "APPARENTGOAL2",
    "TARGETTYPE",
    "TARGETTYPE2",
    "DISPOSABLEAGENTSINVOLVED",
    "FOR_DISCUSSION",
    "NOTE",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_LEIDEN_RUSSIAN_OPS_EUROPE;

CREATE OR REPLACE VIEW THE_LIBRARY.JUSTICE.AG_MULTISTATE_SETTLEMENTS COPY GRANTS COMMENT='The canonical list of multistate settlements concluded by state Attorneys General from 1980 to today: who the defendants were, total dollars, the split between states and the feds, which AGs led vs. joined (with party breakdown), the industry, and the issue. Follow corporate wrongdoing to the money it cost. Raw landing, stored as text; 882 settlements from NAAG.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_CASE"),'nan'),'NaN'),'NAN'),'')) AS "C_CASE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    CASE WHEN TRIM("DATERESOLVED") LIKE '%-%' OR TRIM("DATERESOLVED") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATERESOLVED")) END AS "DATERESOLVED",
    "DEFENDANTS",
    "ADDITIONALDEFENDANTS",
    "TOTALSETTLEMENTAMOUNT",
    "TOTALSTATESHARE",
    "TOTAL_FEDERAL_SHARE",
    "LEADAGS",
    "PARTICIPATINGAGS",
    "DEMLEADSTATES",
    "GOPLEADSTATES",
    "DEMPARTICIPATINGSTATE",
    "GOPPARTICIPATINGSTATE",
    "INDUSTRYTYPE",
    "ISSUEAREAGENERAL",
    "ISSUEAREASPECIFIC",
    "ENFORCEMENTCAMPAIGN",
    "PRODUCT_INVOLVED",
    "DESCRIPTION",
    CASE WHEN TRIM("DATE_ENTRY_CREATED") LIKE '%-%' OR TRIM("DATE_ENTRY_CREATED") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE_ENTRY_CREATED")) END AS "DATE_ENTRY_CREATED",
    "DATE_ENTRY_UPDATED",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OFAGS"),'nan'),'NaN'),'NAN'),'')) AS "OFAGS",
    "FEDERALINVOLVEMENT",
    "CONSUMER_RESTITUTION",
    "LOCATION_SETTLEMENT_FILED",
    "RELATED6DIGITNAICSCODE",
    "FILED_COMPLAINT",
    "SETTLEMENT_DOCUMENTS_OR_PRESS_RELEASE",
    "PRESS_RELEASES",
    "OTHER_SINGLE_STATE_SETTLEMENTS",
    "KEYSETTLEMENTTERMS",
    "COURT_LEVEL",
    "CITATION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTALDEMAGSINOFFICE"),'nan'),'NaN'),'NAN'),'')) AS "TOTALDEMAGSINOFFICE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTALGOPAGSINOFFICE"),'nan'),'NaN'),'NAN'),'')) AS "TOTALGOPAGSINOFFICE",
    "LEGAL_BASIS",
    "SETTLEMENT_PROVISION_TYPES",
    "CORPORATE_MONITOR_PROVISION",
    "RELATED4DIGITNAICSCODE",
    "CORPORATEHEADQUARTERS",
    "OTHERPARTIESINVOLVED",
    "FOCUS",
    "DATE_FILED",
    "DATE_OF_FINAL_COURT_APPROVAL",
    "PRESIDENTIALADMINISTRATION",
    "QUI_TAM_REALTOR_SHARE",
    "OTHER_SETTLEMENT_AMOUNT",
    "STATE_COSTS_FEES",
    "RELATED_CLASS_ACTION_SETTLEMENT_S",
    "SORT_ID",
    "ID",
    "INGESTED_AT",
    "SOURCE_RUN_ID",
    "SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_NAAG_MULTISTATE_SETTLEMENTS;

CREATE OR REPLACE VIEW THE_LIBRARY.JUSTICE.EU_LEGAL_ACTS COPY GRANTS COMMENT='Document-level records from the EU''s official legal repository: CELEX identifier, document type, author institution, dates, and whether it''s in force. A 53-row probe of the API. The CELEX/ELI/ECLI identifier columns are the join keys of the EU legal world.' AS
SELECT
    "CELEX_ID",
    "ELI_URI",
    "ECLI_ID",
    "TITLE",
    "DOCUMENT_TYPE",
    "AUTHOR",
    CASE WHEN TRIM("DATE_PUBLISHED") LIKE '%-%' OR TRIM("DATE_PUBLISHED") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE_PUBLISHED")) END AS "DATE_PUBLISHED",
    CASE WHEN TRIM("DATE_OF_DOCUMENT") LIKE '%-%' OR TRIM("DATE_OF_DOCUMENT") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE_OF_DOCUMENT")) END AS "DATE_OF_DOCUMENT",
    "IN_FORCE",
    "SUBJECT_MATTER",
    "COUNTRY",
    "LANGUAGE",
    "OJ_SERIES",
    "OJ_NUMBER",
    "CONTENT_URL",
    "FORMAT_AVAILABLE",
    "CELLAR_URI",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_EURLEX_CELLAR;

CREATE OR REPLACE VIEW THE_LIBRARY.JUSTICE.FEDERAL_PRISON_STATS COPY GRANTS COMMENT='Aggregate federal inmate and facility statistics published by BOP, landed as metric rows (category, metric, value, date). Small reference table -- good for topline context like population trends, not individual-level analysis.' AS
SELECT
    CASE WHEN TRIM("REPORT_DATE") LIKE '%-%' OR TRIM("REPORT_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("REPORT_DATE")) END AS "REPORT_DATE",
    "CATEGORY",
    "METRIC_NAME",
    "METRIC_VALUE",
    "METRIC_UNIT",
    "FACILITY_TYPE",
    "STATE_FIPS",
    "SOURCE_URL",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_BOP_STATISTICS;

CREATE OR REPLACE VIEW THE_LIBRARY.JUSTICE.FTC_ENFORCEMENT_ACTIONS COPY GRANTS COMMENT='Federal Trade Commission enforcement matters: who the FTC went after, when, for what (consumer protection vs. antitrust), and where the case stands. Respondent names and EINs make it matchable against company tables -- the ''has this company been in trouble before'' lookup.' AS
SELECT
    "ACTION_NAME",
    "RESPONDENT",
    CASE WHEN TRIM("DATE_FILED") LIKE '%-%' OR TRIM("DATE_FILED") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE_FILED")) END AS "DATE_FILED",
    "CASE_TYPE",
    "STATUS",
    "TOPIC",
    "DOCUMENT_URL",
    "EIN",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_FTC_DATASETS;

CREATE OR REPLACE VIEW THE_LIBRARY.JUSTICE.INCARCERATION_TRENDS_BY_COUNTY COPY GRANTS COMMENT='The Vera Institute''s county-level record of who''s locked up in America: jail and prison populations, admissions, and rates over decades, split by race and sex. The spine of mass-incarceration reporting. Keyed by county FIPS, so it joins to almost any US geographic data. Heads up: not every county reports every year, so coverage is patchy across the time series. Raw as loaded (every value stored as text) -- and it''s very wide, with hundreds of demographic breakdown columns.' AS
SELECT
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR",
    "COUNTY_FIPS",
    "COUNTY_NAME",
    "STATE_ABBR",
    "STATE_FIPS",
    "STATE_CODE",
    "COUNTY_CODE",
    "URBANICITY",
    "REGION",
    "DIVISION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("METRO_AREA"),'nan'),'NaN'),'NAN'),'')) AS "METRO_AREA",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COMMUTING_ZONE"),'nan'),'NaN'),'NAN'),'')) AS "COMMUTING_ZONE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LAND_AREA"),'nan'),'NaN'),'NAN'),'')) AS "LAND_AREA",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_JAIL_POP"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_JAIL_POP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MALE_JAIL_POP"),'nan'),'NaN'),'NAN'),'')) AS "MALE_JAIL_POP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FEMALE_JAIL_POP"),'nan'),'NaN'),'NAN'),'')) AS "FEMALE_JAIL_POP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BLACK_JAIL_POP"),'nan'),'NaN'),'NAN'),'')) AS "BLACK_JAIL_POP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BLACK_MALE_JAIL_POP"),'nan'),'NaN'),'NAN'),'')) AS "BLACK_MALE_JAIL_POP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("BLACK_FEMALE_JAIL_POP"),'nan'),'NaN'),'NAN'),'')) AS "BLACK_FEMALE_JAIL_POP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LATINX_JAIL_POP"),'nan'),'NaN'),'NAN'),'')) AS "LATINX_JAIL_POP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LATINX_MALE_JAIL_POP"),'nan'),'NaN'),'NAN'),'')) AS "LATINX_MALE_JAIL_POP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LATINX_FEMALE_JAIL_POP"),'nan'),'NaN'),'NAN'),'')) AS "LATINX_FEMALE_JAIL_POP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WHITE_JAIL_POP"),'nan'),'NaN'),'NAN'),'')) AS "WHITE_JAIL_POP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WHITE_MALE_JAIL_POP"),'nan'),'NaN'),'NAN'),'')) AS "WHITE_MALE_JAIL_POP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WHITE_FEMALE_JAIL_POP"),'nan'),'NaN'),'NAN'),'')) AS "WHITE_FEMALE_JAIL_POP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NATIVE_JAIL_POP"),'nan'),'NaN'),'NAN'),'')) AS "NATIVE_JAIL_POP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("AAPI_JAIL_POP"),'nan'),'NaN'),'NAN'),'')) AS "AAPI_JAIL_POP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("OTHER_RACE_JAIL_POP"),'nan'),'NaN'),'NAN'),'')) AS "OTHER_RACE_JAIL_POP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_PRETRIAL_CUSTODY"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_PRETRIAL_CUSTODY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_PRETRIAL_JURIS"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_PRETRIAL_JURIS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_JAIL_FROM_FED"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_JAIL_FROM_FED",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_JAIL_FROM_PRISON"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_JAIL_FROM_PRISON",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_JAIL_FROM_OTHER_JAIL"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_JAIL_FROM_OTHER_JAIL",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_JAIL_FROM_BIA"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_JAIL_FROM_BIA",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_JAIL_FROM_BOP"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_JAIL_FROM_BOP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_JAIL_FROM_ICE"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_JAIL_FROM_ICE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_JAIL_FROM_MARSHALS"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_JAIL_FROM_MARSHALS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_JAIL_FROM_OTHER_FED"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_JAIL_FROM_OTHER_FED",
    "TOTAL_CONTRACTED_OUT",
    "TOTAL_CONTRACTED_IN",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_JAIL_ADMITS"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_JAIL_ADMITS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MALE_JAIL_ADMITS"),'nan'),'NaN'),'NAN'),'')) AS "MALE_JAIL_ADMITS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FEMALE_JAIL_ADMITS"),'nan'),'NaN'),'NAN'),'')) AS "FEMALE_JAIL_ADMITS",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_JAIL_DISCHARGES"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_JAIL_DISCHARGES",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MALE_JAIL_DISCHARGES"),'nan'),'NaN'),'NAN'),'')) AS "MALE_JAIL_DISCHARGES",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FEMALE_JAIL_DISCHARGES"),'nan'),'NaN'),'NAN'),'')) AS "FEMALE_JAIL_DISCHARGES",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("JAIL_RATED_CAPACITY"),'nan'),'NaN'),'NAN'),'')) AS "JAIL_RATED_CAPACITY",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_SENTENCED_CUSTODY"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_SENTENCED_CUSTODY",
    "IS_REGIONAL_JAIL",
    "IS_UNIFIED_STATE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TOTAL_PRISON_POP"),'nan'),'NaN'),'NAN'),'')) AS "TOTAL_PRISON_POP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FEMALE_PRISON_POP"),'nan'),'NaN'),'NAN'),'')) AS "FEMALE_PRISON_POP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MALE_PRISON_POP"),'nan'),'NaN'),'NAN'),'')) AS "MALE_PRISON_POP",
