CREATE OR REPLACE VIEW THE_LIBRARY.MONEY.CREDIT_UNION_CALL_REPORTS COPY GRANTS COMMENT='The credit-union equivalent of bank call reports: quarterly account-level financial data for every federally insured credit union, in long format (one row per institution-quarter-account code). EIN and state columns make it joinable; the account-code layout means you filter to the metric you want, then pivot.' AS
SELECT
    "CU_NUMBER",
    CASE WHEN TRIM("CYCLE_DATE") LIKE '%-%' OR TRIM("CYCLE_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CYCLE_DATE")) END AS "CYCLE_DATE",
    "ACCT_CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ACCT_VALUE"),'nan'),'NaN'),'NAN'),'')) AS "ACCT_VALUE",
    "CU_NAME",
    "STATE",
    "CITY",
    "ZIP_CODE",
    "EIN",
    "CHARTER_TYPE",
    "TABLE_NAME",
    "ACCT_DESC",
    "ACCT_STATUS",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_NCUA_CALL_REPORTS;

CREATE OR REPLACE VIEW THE_LIBRARY.MONEY.IRS_INCOME_STATS_BY_ZIP COPY GRANTS COMMENT='Aggregated tax-return statistics from the IRS SOI program at ZIP-code level: number of returns, income bracket (AGI stub), joint filers, exemptions, and more. This is the closest public thing to ''how much money lives in this ZIP'' -- a natural denominator for any per-place analysis.' AS
SELECT
    "STATE_FIPS",
    "STATE",
    "ZIP_CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("AGI_STUB"),'nan'),'NaN'),'NAN'),'')) AS "AGI_STUB",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("N_RETURNS"),'nan'),'NaN'),'NAN'),'')) AS "N_RETURNS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MARS1"),'nan'),'NaN'),'NAN'),'')) AS "MARS1",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("N_JOINT_RETURNS"),'nan'),'NaN'),'NAN'),'')) AS "N_JOINT_RETURNS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MARS4"),'nan'),'NaN'),'NAN'),'')) AS "MARS4",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PREP"),'nan'),'NaN'),'NAN'),'')) AS "PREP",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("N2"),'nan'),'NaN'),'NAN'),'')) AS "N2",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("N_EXEMPTIONS"),'nan'),'NaN'),'NAN'),'')) AS "N_EXEMPTIONS",
