CREATE OR REPLACE VIEW THE_LIBRARY.MONEY.SEC_FILING_SUBMISSIONS COPY GRANTS COMMENT='One row per financial statement filing to the SEC: the filer''s name, CIK, EIN, industry code (SIC), addresses, fiscal period, and form type (10-K, 10-Q, etc.). The index to public companies'' financials -- join out to the actual line-item numbers by accession number (ADSH). Raw as loaded (all text); carries CIK and EIN as join keys. From SEC DERA.' AS
SELECT
    "ADSH",
    "CIK",
    "NAME",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SIC"),'nan'),'NaN'),'NAN'),'')) AS "SIC",
    "COUNTRYBA",
    "STPRBA",
    "CITYBA",
    "ZIPBA",
    "BAS1",
    "BAS2",
    "BAPH",
    "COUNTRYMA",
    "STPRMA",
    "CITYMA",
    "ZIPMA",
    "MAS1",
    "MAS2",
    "COUNTRYINC",
    "STPRINC",
    "EIN",
    "FORMER",
    "CHANGED",
    "AFS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("WKSI"),'nan'),'NaN'),'NAN'),'')) AS "WKSI",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FYE"),'nan'),'NaN'),'NAN'),'')) AS "FYE",
    "FORM",
    "PERIOD",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("FY"),'nan'),'NaN'),'NAN'),'')) AS "FY",
    "FP",
    "FILED",
    "ACCEPTED",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("PREVRPT"),'nan'),'NaN'),'NAN'),'')) AS "PREVRPT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DETAIL"),'nan'),'NaN'),'NAN'),'')) AS "DETAIL",
    "INSTANCE",
    "NCIKS",
    "ACIKS",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256",
    "SOURCE_FILE"
FROM LIBRARY_RAW.LANDING.FED_SEC_EDGAR_FINANCIALS;

CREATE OR REPLACE VIEW THE_LIBRARY.MONEY.SOVEREIGN_DEBT_BY_CREDITOR COPY GRANTS COMMENT='The World Bank''s International Debt Statistics: developing-country external debt -- stocks and debt service -- with a rare creditor-by-creditor breakdown showing who each country actually owes (bilateral, multilateral, private). The core source for the global debt crisis. Keyed by ISO-3 country code plus a counterpart (creditor) code; filter counterpart to WLD for a clean all-creditors country panel. Heads up: only low- and middle-income countries (no G7 debtors), years run wide (1970-2032) and 2025+ are projections/nulls. Wide format -- one column per year. Raw as loaded (text).' AS
SELECT
    "COUNTRY_NAME",
    "COUNTRY_CODE",
    "COUNTERPART_AREA_NAME",
    "COUNTERPART_AREA_CODE",
    "SERIES_NAME",
    "SERIES_CODE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1970"),'nan'),'NaN'),'NAN'),'')) AS "C_1970",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1971"),'nan'),'NaN'),'NAN'),'')) AS "C_1971",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1972"),'nan'),'NaN'),'NAN'),'')) AS "C_1972",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1973"),'nan'),'NaN'),'NAN'),'')) AS "C_1973",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1974"),'nan'),'NaN'),'NAN'),'')) AS "C_1974",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1975"),'nan'),'NaN'),'NAN'),'')) AS "C_1975",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1976"),'nan'),'NaN'),'NAN'),'')) AS "C_1976",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1977"),'nan'),'NaN'),'NAN'),'')) AS "C_1977",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1978"),'nan'),'NaN'),'NAN'),'')) AS "C_1978",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1979"),'nan'),'NaN'),'NAN'),'')) AS "C_1979",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1980"),'nan'),'NaN'),'NAN'),'')) AS "C_1980",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1981"),'nan'),'NaN'),'NAN'),'')) AS "C_1981",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1982"),'nan'),'NaN'),'NAN'),'')) AS "C_1982",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1983"),'nan'),'NaN'),'NAN'),'')) AS "C_1983",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1984"),'nan'),'NaN'),'NAN'),'')) AS "C_1984",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_1985"),'nan'),'NaN'),'NAN'),'')) AS "C_1985",
