CREATE OR REPLACE VIEW THE_LIBRARY.OPEN_DATA.FRANCE_OPEN_DATA_CATALOG COPY GRANTS COMMENT='Dataset-level catalog of data.gouv.fr: what France publishes, who publishes it, license, and update dates. A finding aid -- use it to spot French datasets worth pouring, not as data itself.' AS
SELECT
    "DATASET_ID",
    "SLUG",
    "TITLE",
    "DESCRIPTION",
    "ORGANIZATION_ID",
    "ORGANIZATION_NAME",
    "LICENSE",
    "FREQUENCY",
    "CREATED_AT",
    "LAST_MODIFIED",
    CASE WHEN TRIM("LAST_UPDATE") LIKE '%-%' OR TRIM("LAST_UPDATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("LAST_UPDATE")) END AS "LAST_UPDATE",
    "NB_RESOURCES",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NB_REUSES"),'nan'),'NaN'),'NAN'),'')) AS "NB_REUSES",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NB_FOLLOWERS"),'nan'),'NaN'),'NAN'),'')) AS "NB_FOLLOWERS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NB_VIEWS"),'nan'),'NaN'),'NAN'),'')) AS "NB_VIEWS",
    "TAGS",
    "TOPIC",
    "SPATIAL_GRANULARITY",
    "SPATIAL_ZONES",
    "TEMPORAL_COVERAGE_START",
    "TEMPORAL_COVERAGE_END",
    "PAGE_URL",
    "RESOURCE_ID",
    "RESOURCE_TITLE",
    "RESOURCE_URL",
    "RESOURCE_FORMAT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RESOURCE_FILESIZE"),'nan'),'NaN'),'NAN'),'')) AS "RESOURCE_FILESIZE",
    "RESOURCE_LAST_MODIFIED",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_FR_DATA_GOUV;

CREATE OR REPLACE VIEW THE_LIBRARY.SANCTIONS.EU_SANCTIONS_LIST COPY GRANTS COMMENT='The EU''s official consolidated sanctions list: subject type, names/aliases, programme, and legal-basis references, maintained daily by the European Commission. The European counterpart to OFAC''s list -- run any name of interest against both; entity records here match to companies and vessels elsewhere in the Library.' AS
SELECT
    CASE WHEN TRIM("DATE_FILE") LIKE '%-%' OR TRIM("DATE_FILE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("DATE_FILE")) END AS "DATE_FILE",
    "ENTITY_LOGICAL_ID",
    "SUBJECT_TYPE",
    "LEBA_NUMTITLE",
    CASE WHEN TRIM("LEBA_PUBLICATION_DATE") LIKE '%-%' OR TRIM("LEBA_PUBLICATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("LEBA_PUBLICATION_DATE")) END AS "LEBA_PUBLICATION_DATE",
    "LEBA_URL",
    "PROGRAMME",
    "ENTITY_REMARK",
    "NAAL_LOGICAL_ID",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ENTITY_LOGICAL_ID_1"),'nan'),'NaN'),'NAN'),'')) AS "ENTITY_LOGICAL_ID_1",
    "NAAL_LEBA_NUMTITLE",
    CASE WHEN TRIM("NAAL_LEBA_PUBLICATION_DATE") LIKE '%-%' OR TRIM("NAAL_LEBA_PUBLICATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("NAAL_LEBA_PUBLICATION_DATE")) END AS "NAAL_LEBA_PUBLICATION_DATE",
    "NAAL_LEBA_URL",
    "NAAL_PROGRAMME",
    "NAAL_LASTNAME",
    "NAAL_FIRSTNAME",
    "NAAL_MIDDLENAME",
    "NAAL_WHOLENAME",
    "NAAL_GENDER",
    "NAAL_TITLE",
    "NAAL_FUNCTION",
    "NAAL_LANGUAGE",
    "ADDR_LOGICAL_ID",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ENTITY_LOGICAL_ID_2"),'nan'),'NaN'),'NAN'),'')) AS "ENTITY_LOGICAL_ID_2",
    "ADDR_LEBA_NUMTITLE",
    CASE WHEN TRIM("ADDR_LEBA_PUBLICATION_DATE") LIKE '%-%' OR TRIM("ADDR_LEBA_PUBLICATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("ADDR_LEBA_PUBLICATION_DATE")) END AS "ADDR_LEBA_PUBLICATION_DATE",
    "ADDR_LEBA_URL",
    "ADDR_PROGRAMME",
    "ADDR_NUMBER",
    "ADDR_STREET",
    "ADDR_ZIPCODE",
    "ADDR_CITY",
    "ADDR_COUNTRY",
    "ADDR_OTHER",
    "BIRT_LOGICAL_ID",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ENTITY_LOGICAL_ID_3"),'nan'),'NaN'),'NAN'),'')) AS "ENTITY_LOGICAL_ID_3",
    "BIRT_LEBA_NUMTITLE",
    CASE WHEN TRIM("BIRT_LEBA_PUBLICATION_DATE") LIKE '%-%' OR TRIM("BIRT_LEBA_PUBLICATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("BIRT_LEBA_PUBLICATION_DATE")) END AS "BIRT_LEBA_PUBLICATION_DATE",
    "BIRT_LEBA_URL",
    "BIRT_PROGRAMME",
    CASE WHEN TRIM("BIRT_DATE") LIKE '%-%' OR TRIM("BIRT_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("BIRT_DATE")) END AS "BIRT_DATE",
    "BIRT_PLACE",
    "BIRT_COUNTRY",
    "IDEN_LOGICAL_ID",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ENTITY_LOGICAL_ID_4"),'nan'),'NaN'),'NAN'),'')) AS "ENTITY_LOGICAL_ID_4",
    "IDEN_LEBA_NUMTITLE",
    CASE WHEN TRIM("IDEN_LEBA_PUBLICATION_DATE") LIKE '%-%' OR TRIM("IDEN_LEBA_PUBLICATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("IDEN_LEBA_PUBLICATION_DATE")) END AS "IDEN_LEBA_PUBLICATION_DATE",
    "IDEN_LEBA_URL",
    "IDEN_PROGRAMME",
    "IDEN_NUMBER",
    "IDEN_COUNTRY",
    "CITI_LOGICAL_ID",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ENTITY_LOGICAL_ID_5"),'nan'),'NaN'),'NAN'),'')) AS "ENTITY_LOGICAL_ID_5",
    "CITI_LEBA_NUMTITLE",
    CASE WHEN TRIM("CITI_LEBA_PUBLICATION_DATE") LIKE '%-%' OR TRIM("CITI_LEBA_PUBLICATION_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("CITI_LEBA_PUBLICATION_DATE")) END AS "CITI_LEBA_PUBLICATION_DATE",
    "CITI_LEBA_URL",
    "CITI_PROGRAMME",
    "CITI_COUNTRY",
    "EU_REF_NUM",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_EU_SANCTIONS;

CREATE OR REPLACE VIEW THE_LIBRARY.SANCTIONS.SANCTIONED_PARTIES COPY GRANTS COMMENT='The OFAC Specially Designated Nationals list -- 19,115 rows of people, entities, and vessels the U.S. Treasury has sanctioned, plus the program (Iran, Russia, narcotics, terrorism, etc.) that got them listed. Vessel rows carry a 7-digit IMO number, so you can tie a sanctioned ship to its movements. Raw landing: every value is stored as text exactly as published.' AS
SELECT
    "ENT_NUM",
    "SDN_NAME",
    "SDN_TYPE",
    "PROGRAM",
    "TITLE",
    "CALL_SIGN",
    "VESS_TYPE",
    "TONNAGE",
    "GRT",
    "VESS_FLAG",
    "VESS_OWNER",
    "REMARKS",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("IMO"),'nan'),'NaN'),'NAN'),'')) AS "IMO",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_OFAC_SDN;

CREATE OR REPLACE VIEW THE_LIBRARY.SCIENCE.EARTHQUAKES COPY GRANTS COMMENT='The full USGS catalog of every earthquake magnitude 2.5 and up: when it hit, exactly where (lat/lon), how deep, how strong, and a plain-language place name. 443,274 events across the whole history the survey tracks. Joins to anything geographic by lat/lon. Raw landing, values stored as text; from the US Geological Survey.' AS
SELECT
    "TIME",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LATITUDE"),'nan'),'NaN'),'NAN'),'')) AS "LATITUDE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("LONGITUDE"),'nan'),'NaN'),'NAN'),'')) AS "LONGITUDE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEPTH"),'nan'),'NaN'),'NAN'),'')) AS "DEPTH",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MAG"),'nan'),'NaN'),'NAN'),'')) AS "MAG",
    "MAGTYPE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("NST"),'nan'),'NaN'),'NAN'),'')) AS "NST",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("GAP"),'nan'),'NaN'),'NAN'),'')) AS "GAP",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DMIN"),'nan'),'NaN'),'NAN'),'')) AS "DMIN",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("RMS"),'nan'),'NaN'),'NAN'),'')) AS "RMS",
    "NET",
    "ID",
    CASE WHEN TRIM("UPDATED") LIKE '%-%' OR TRIM("UPDATED") LIKE '%/%' THEN TRY_TO_DATE(TRIM("UPDATED")) END AS "UPDATED",
    "PLACE",
    "TYPE",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("HORIZONTALERROR"),'nan'),'NaN'),'NAN'),'')) AS "HORIZONTALERROR",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("DEPTHERROR"),'nan'),'NaN'),'NAN'),'')) AS "DEPTHERROR",
    TRY_TO_DOUBLE(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MAGERROR"),'nan'),'NaN'),'NAN'),'')) AS "MAGERROR",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("MAGNST"),'nan'),'NaN'),'NAN'),'')) AS "MAGNST",
    "STATUS",
    "LOCATIONSOURCE",
    "MAGSOURCE",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_USGS_EARTHQUAKES;

CREATE OR REPLACE VIEW THE_LIBRARY.SCIENCE.GENOME_ANNOTATIONS COPY GRANTS COMMENT='Records from the Ensembl REST API: species, assembly, region, feature type, and gene symbols. A 643-row probe demonstrating the API. Far from the Library''s accountability core -- parked here in case a bio-adjacent story ever needs it.' AS
SELECT
    "ID",
    "SPECIES",
    "ASSEMBLY",
    "REGION",
    "FEATURE_TYPE",
    "SYMBOL",
    "BIOTYPE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("STRAND"),'nan'),'NaN'),'NAN'),'')) AS "STRAND",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("C_START"),'nan'),'NaN'),'NAN'),'')) AS "C_START",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("END"),'nan'),'NaN'),'NAN'),'')) AS "END",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("SEQ_REGION_NAME"),'nan'),'NaN'),'NAN'),'')) AS "SEQ_REGION_NAME",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("VERSION"),'nan'),'NaN'),'NAN'),'')) AS "VERSION",
    "DB_TYPE",
    "TAXON_ID",
    "CONSEQUENCE_TYPE",
    "ALLELE_STRING",
    "POPULATION_NAME",
    "ONTOLOGY_TERM",
    "SOURCE_NAME",
    "PRIMARY_ACCESSION",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.INTL_EMBL_ENSEMBL;

CREATE OR REPLACE VIEW THE_LIBRARY.SCIENCE.NASA_API_SAMPLES COPY GRANTS COMMENT='A sampler of NASA''s public APIs: which API, the request, and the response metadata with links. 54 rows landed as a capability probe -- a menu of what NASA offers rather than a dataset in itself.' AS
SELECT
    "API_NAME",
    "REQUEST_URL",
    CASE WHEN TRIM("RESPONSE_DATE") LIKE '%-%' OR TRIM("RESPONSE_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("RESPONSE_DATE")) END AS "RESPONSE_DATE",
    "TITLE",
    "DESCRIPTION",
    "URL",
    "MEDIA_TYPE",
    "RAW_JSON",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_NASA_OPEN_DATA;

CREATE OR REPLACE VIEW THE_LIBRARY.SCIENCE.NSF_RESEARCH_GRANTS COPY GRANTS COMMENT='Award records from the NSF: title, awardee institution, PI, program officer, amount, and dates. A 125-row probe of the search API. Institution names match to universities across the Library; the full feed is worth a deeper pour.' AS
SELECT
    "AWARD_ID",
    "TITLE",
    "AWARDEE_NAME",
    "INSTITUTION",
    "PI_NAME",
    "CO_PI_NAMES",
    "PROGRAM_OFFICER",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("AWARD_AMOUNT"),'nan'),'NaN'),'NAN'),'')) AS "AWARD_AMOUNT",
    CASE WHEN TRIM("AWARD_DATE") LIKE '%-%' OR TRIM("AWARD_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("AWARD_DATE")) END AS "AWARD_DATE",
    CASE WHEN TRIM("START_DATE") LIKE '%-%' OR TRIM("START_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("START_DATE")) END AS "START_DATE",
    CASE WHEN TRIM("END_DATE") LIKE '%-%' OR TRIM("END_DATE") LIKE '%/%' THEN TRY_TO_DATE(TRIM("END_DATE")) END AS "END_DATE",
    "STATUS",
    "ABSTRACT",
    "PROGRAM_NAME",
    "EIN",
    "ZIP",
    "CITY",
    "STATE",
    "COUNTRY",
    "CFDA_NUMBER",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_NSF_AWARDS;

CREATE OR REPLACE VIEW THE_LIBRARY.TRANSPORT.AIRCRAFT_REGISTRY COPY GRANTS COMMENT='Every US-registered civil aircraft: N-number, serial, make/model, year, and the registrant''s name and address. The ''who owns that plane'' table -- owner names and addresses match to companies and people across the Library, and it pairs naturally with flight-tracking work.' AS
SELECT
    "N_NUMBER",
    "SERIAL_NUMBER",
    "MFR_MDL_CODE",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("ENG_MFR_MDL"),'nan'),'NaN'),'NAN'),'')) AS "ENG_MFR_MDL",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("YEAR_MFR"),'nan'),'NaN'),'NAN'),'')) AS "YEAR_MFR",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TYPE_REGISTRANT"),'nan'),'NaN'),'NAN'),'')) AS "TYPE_REGISTRANT",
    "NAME",
    "STREET",
    "STREET2",
    "CITY",
    "STATE",
    "ZIP_CODE",
    "REGION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("COUNTY"),'nan'),'NaN'),'NAN'),'')) AS "COUNTY",
    "COUNTRY",
    TRY_TO_DATE(TRIM("LAST_ACTION_DATE"),'YYYYMMDD') AS "LAST_ACTION_DATE",
    TRY_TO_DATE(TRIM("CERT_ISSUE_DATE"),'YYYYMMDD') AS "CERT_ISSUE_DATE",
    "CERTIFICATION",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TYPE_AIRCRAFT"),'nan'),'NaN'),'NAN'),'')) AS "TYPE_AIRCRAFT",
    TRY_TO_NUMBER(NULLIF(NULLIF(NULLIF(NULLIF(TRIM("TYPE_ENGINE"),'nan'),'NaN'),'NAN'),'')) AS "TYPE_ENGINE",
    "STATUS_CODE",
    "MODE_S_CODE",
    "FRACT_OWNER",
    TRY_TO_DATE(TRIM("AIR_WORTH_DATE"),'YYYYMMDD') AS "AIR_WORTH_DATE",
    "OTHER_NAMES_1",
    "OTHER_NAMES_2",
    "OTHER_NAMES_3",
    "OTHER_NAMES_4",
    "OTHER_NAMES_5",
    TRY_TO_DATE(TRIM("EXPIRATION_DATE"),'YYYYMMDD') AS "EXPIRATION_DATE",
    "UNIQUE_ID",
    "KIT_MFR",
    "KIT_MODEL",
    "MODE_S_CODE_HEX",
    "_INGESTED_AT",
    "_SOURCE_RUN_ID",
    "_SRC_SHA256"
FROM LIBRARY_RAW.LANDING.FED_FAA_REGISTRY;
